"use client";

import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "next/navigation";
import { Edit, MapPin, Trash2 } from "@esparex/ui";
import { useAdminLocations } from "@/hooks/useAdminLocations";
import { useCatalogQueryStateSync } from "@/hooks/useCatalogQueryStateSync";
import { getLocationOptions } from "@/lib/api/locations";
import { type Location } from "@/types/location";
import { CatalogPageTemplate } from "@/components/catalog/CatalogPageTemplate";
import {
    CatalogActionsRow,
    CatalogActiveStatusFilter,
    CatalogActionIconButton,
    CatalogActiveToggleButton,
    CatalogEntityCell,
    CatalogSearchInput,
    CatalogSelectFilter,
} from "@/components/catalog/CatalogUiPrimitives";
import { adminLocationSchema } from "@/schemas/admin.schemas";
import { locationsTabs } from "@/components/layout/adminModuleTabSets";
import {
    normalizeSearchParamValue,
    parsePositiveIntParam,
} from "@/lib/urlSearchParams";
import {
    LocationFormFields,
    type LocationFormData,
} from "./components/LocationFormFields";
import { LocationDeleteModal } from "./components/LocationDeleteModal";

const LOCATION_STATUS_VALUES = new Set(["all", "active", "inactive"]);
const LOCATION_LEVEL_VALUES = new Set(["all", "state", "city", "area"]);

const normalizeStatusParam = (value: string | null) =>
    value && LOCATION_STATUS_VALUES.has(value) ? value : "all";

const normalizeLevelParam = (value: string | null) =>
    value && LOCATION_LEVEL_VALUES.has(value) ? value : "all";

type LocationsPageContentProps = {
    initialSearch: string;
    initialStatus: string;
    initialState: string;
    initialLevel: string;
    initialPage: number;
};

function LocationsPageContent({
    initialSearch,
    initialStatus,
    initialState,
    initialLevel,
    initialPage,
}: LocationsPageContentProps) {
    const [searchInput, setSearchInput] = useState(initialSearch);
    const [stateOptions, setStateOptions] = useState<Location[]>([]);
    const [deletingLocation, setDeletingLocation] = useState<Location | null>(null);
    const [isDeleting, setIsDeleting] = useState(false);

    const filters = useMemo(
        () => ({
            search: initialSearch,
            status: initialStatus as "all" | "active" | "inactive",
            state: initialState || "all",
            level: initialLevel as "all" | "state" | "city" | "area",
        }),
        [initialLevel, initialSearch, initialState, initialStatus]
    );

    const {
        locations,
        states,
        loading,
        error,
        handleToggleStatus,
        handleDelete,
        handleCreate,
        handleUpdate,
        pagination,
    } = useAdminLocations({
        filters,
        page: initialPage,
        limit: 20,
    });

    const confirmDelete = async () => {
        if (!deletingLocation) return;
        setIsDeleting(true);
        const success = await handleDelete(deletingLocation.id);
        setIsDeleting(false);
        if (success) setDeletingLocation(null);
    };

    useEffect(() => {
        setSearchInput(initialSearch);
    }, [initialSearch]);

    const { replaceQueryState } = useCatalogQueryStateSync({
        searchInput,
        initialSearch,
        loading,
        initialPage,
        totalPages: pagination.totalPages,
    });

    useEffect(() => {
        let active = true;

        const loadStateOptions = async () => {
            const nextStates = await getLocationOptions({
                level: "state",
                status: "active",
                limit: 100,
            });

            if (active) {
                setStateOptions(nextStates);
            }
        };

        void loadStateOptions();

        return () => {
            active = false;
        };
    }, []);

    return (
        <>
            <CatalogPageTemplate<Location, LocationFormData>
                title="Location Management"
                description="Manage hierarchy-based master locations used by posting, reverse geocoding, and location analytics."
                tabs={locationsTabs}
                createLabel="Add Location"
                csvFileName="locations.csv"
                items={locations}
                loading={loading}
                error={error}
                pagination={pagination}
                setPage={(page) => replaceQueryState({ page: page > 1 ? page : null })}
                handleCreate={handleCreate}
                handleUpdate={handleUpdate}
                defaultFormData={{
                    name: "",
                    level: "city",
                    parentId: "",
                    parentStateId: "",
                    longitude: "",
                    latitude: "",
                    isActive: true,
                    country: "India",
                }}
                customSubmitValidation={(formData) => {
                    const validation = adminLocationSchema.safeParse({
                        name: formData.name,
                        level: formData.level,
                        parentId: formData.level === "state" ? null : formData.parentId,
                        longitude: formData.longitude,
                        latitude: formData.latitude,
                    });

                    if (!validation.success) {
                        return validation.error.issues[0]?.message || "Invalid form data";
                    }

                    if (formData.level === "area" && !formData.parentStateId) {
                        return "State is required for area creation";
                    }

                    return null;
                }}
                onModalOpen={(item, setFormData) => {
                    if (!item) return;

                    const level =
                        item.level === "state" || item.level === "city" || item.level === "area"
                            ? item.level
                            : "city";
                    const parentStateId =
                        level === "area"
                            ? item.path?.find((entry) => stateOptions.some((state) => state.id === entry)) ||
                              item.path?.[0] ||
                              ""
                            : "";

                    setFormData({
                        name: item.name,
                        level,
                        parentId: item.parentId || "",
                        parentStateId,
                        longitude: item.coordinates?.coordinates?.[0]?.toString() || "",
                        latitude: item.coordinates?.coordinates?.[1]?.toString() || "",
                        isActive: item.isActive,
                        country: item.country || "India",
                    });
                }}
                generateColumns={(openEditModal) => [
                    {
                        header: "Location",
                        cell: (location) => (
                            <CatalogEntityCell
                                icon={<MapPin size={20} />}
                                iconClassName="rounded-full bg-blue-50 text-blue-600"
                                title={location.name || location.city}
                                subtitle={`${location.state || "Unknown State"}, ${location.country}`}
                            />
                        ),
                    },
                    {
                        header: "Level",
                        cell: (location) => (
                            <span className="px-2 py-0.5 rounded text-tiny font-bold uppercase tracking-wider bg-slate-100 text-foreground-secondary">
                                {location.level}
                            </span>
                        ),
                    },
                    {
                        header: "Stats",
                        cell: (location) => (
                            <div className="text-xs space-y-0.5">
                                <div className="text-foreground-secondary">
                                    <span className="font-bold">{location.adsCount || 0}</span> Ads
                                </div>
                                <div className="text-foreground-subtle">{location.usersCount || 0} Users</div>
                            </div>
                        ),
                    },
                    {
                        header: "Status",
                        cell: (location) => (
                            <CatalogActiveToggleButton
                                isActive={location.isActive}
                                onClick={() => void handleToggleStatus(location.id)}
                            />
                        ),
                    },
                    {
                        header: "Actions",
                        className: "text-right",
                        cell: (location) => (
                            <CatalogActionsRow>
                                <CatalogActionIconButton
                                    onClick={() => openEditModal(location)}
                                    className="p-1.5 text-foreground-subtle hover:text-primary hover:bg-primary/5 rounded-lg transition-all"
                                    title="Edit"
                                    icon={<Edit size={18} />}
                                />
                                <CatalogActionIconButton
                                    onClick={() => setDeletingLocation(location)}
                                    className="p-1.5 text-foreground-subtle hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                                    title="Delete"
                                    icon={<Trash2 size={18} />}
                                />
                            </CatalogActionsRow>
                        ),
                    },
                ]}
                filterLayoutClassName="md:grid-cols-5"
                filtersRenderer={
                    <>
                        <CatalogSearchInput
                            className="col-span-1 md:col-span-2"
                            value={searchInput}
                            placeholder="Search location name or slug..."
                            onChange={setSearchInput}
                        />
                        <CatalogActiveStatusFilter
                            withFilterIcon
                            value={filters.status ?? "all"}
                            onChange={(status) =>
                                replaceQueryState({ status: status === "all" ? null : status, page: null })
                            }
                        />
                        <CatalogSelectFilter
                            value={filters.state ?? "all"}
                            onChange={(state) =>
                                replaceQueryState({ state: state === "all" ? null : state, page: null })
                            }
                            options={[
                                { value: "all", label: "All States" },
                                ...states.map((state) => ({ value: state, label: state })),
                            ]}
                        />
                        <CatalogSelectFilter
                            value={filters.level ?? "all"}
                            onChange={(level) =>
                                replaceQueryState({ level: level === "all" ? null : level, page: null })
                            }
                            options={[
                                { value: "all", label: "All Levels" },
                                { value: "state", label: "State" },
                                { value: "city", label: "City" },
                                { value: "area", label: "Area" },
                            ]}
                        />
                    </>
                }
                formRenderer={(formData, setFormData) => (
                    <LocationFormFields
                        formData={formData}
                        setFormData={setFormData}
                        stateOptions={stateOptions}
                    />
                )}
            />

            <LocationDeleteModal
                deletingLocation={deletingLocation}
                isDeleting={isDeleting}
                onClose={() => setDeletingLocation(null)}
                onConfirm={() => void confirmDelete()}
            />
        </>
    );
}

export default function LocationsPage() {
    const searchParams = useSearchParams();

    const initialSearch = normalizeSearchParamValue(searchParams.get("q") ?? searchParams.get("search"));
    const initialStatus = normalizeStatusParam(searchParams.get("status"));
    const initialState = normalizeSearchParamValue(searchParams.get("state"));
    const initialLevel = normalizeLevelParam(searchParams.get("level"));
    const initialPage = parsePositiveIntParam(searchParams.get("page"), 1);

    return (
        <LocationsPageContent
            initialSearch={initialSearch}
            initialStatus={initialStatus}
            initialState={initialState}
            initialLevel={initialLevel}
            initialPage={initialPage}
        />
    );
}

"use client";

import { useEffect, useMemo, useState, useRef } from "react";
import { AlertCircle, RefreshCcw, EyeOff, ChevronDown, Loader2 } from "@esparex/ui";
import { AdsTable } from "@/components/moderation/AdsTable";
import { RejectAdModal } from "@/components/moderation/RejectAdModal";
import { ViewAdModal } from "@/components/moderation/ViewAdModal";
import { AdminModuleTabs } from "@/components/layout/AdminModuleTabs";
import { AdminPageShell } from "@/components/layout/AdminPageShell";
import { AdminFilterToolbar } from "@/components/layout/AdminFilterToolbar";
import { moderationTabs } from "@/components/layout/adminModuleTabSets";
import { AdminErrorBoundary } from "@/components/common/AdminErrorBoundary";
import { getListingPresentation } from "@/components/moderation/listingPresentation";
import { CatalogModal } from "@/components/catalog/CatalogModal";

import { useAdFilters } from "./hooks/useAdFilters";
import { useAdSelection } from "./hooks/useAdSelection";
import { useAdTableData } from "./hooks/useAdTableData";
import { useAdActions } from "./hooks/useAdActions";
import { ModerationFilters } from "@/components/moderation/moderationTypes";

import { AdsColumnVisibilityMenu } from "./components/AdsColumnVisibilityMenu";
import { AdsFilterToolbarExtras } from "./components/AdsFilterToolbarExtras";

const allowed = new Set(["pending", "live", "rejected", "deactivated", "sold", "expired", "all"]);

type AdsViewProps = {
    mode?: "ads";
    listingType?: "ad" | "service" | "spare_part";
};

export default function AdsView({ listingType }: AdsViewProps) {
    const presentation = getListingPresentation(listingType);
    const entityLabel = presentation.actionEntityLabel;
    const entityLabelPlural = presentation.actionEntityLabelPlural;

    const [refreshKey, setRefreshKey] = useState(0);
    const refresh = () => setRefreshKey((value) => value + 1);

    // ── Local UI State ─────────────────────────────────────────────────────────
    const [columnVisibility, setColumnVisibility] = useState<Record<string, boolean>>({
        select: true,
        image: true,
        details: true,
        seller: true,
        location: true,
        attribute: true,
        risk: true,
        status: true,
        created: true,
        actions: true
    });

    // ── Modular Hooks ──────────────────────────────────────────────────────────
    const { 
        filters, page, pageSize, updateFilter, clearFilters, replaceRoute 
    } = useAdFilters(listingType);
    const normalizedStatus = allowed.has(filters.status) ? filters.status : "all";

    const { 
        items, pagination, isLoading, error, moduleTabs, activeStatusOptions 
    } = useAdTableData({ filters, page, pageSize, refreshKey });

    const { 
        selectedIds, selectedCount, toggleSelect, toggleSelectAll, setSelectedIds 
    } = useAdSelection(items);

    const {
        viewAd, viewModalOpen, setViewModalOpen, viewLoading, viewError, handleView, setViewAd, setViewError,
        rejectModalOpen, setRejectModalOpen, rejectTitle, rejectTargetIds, isMutating, setRejectTargetIds, setRejectTitle,
        openSingleReject, openBulkReject, handleRejectSubmit,
        handleApprove, handleDeactivate, handleActivate, handleDelete, handleBanSeller, 
        handleBulkApprove, handleBulkDelete, handleBulkDeactivate, handleBulkExpire, handleBulkExtend,
        handleBulkResendWarnings, handleBulkResendSpotlightWarnings,
        handleModalApprove, handleModalDeactivate, handleModalActivate, handleModalBlockSeller, handleModalExtend,
        deleteModalOpen, setDeleteModalOpen, deleteTargetIds, deleteDisplayTitle, handleConfirmDelete,
        banModalOpen, setBanModalOpen, banTargetSellerName, handleConfirmBan,
    } = useAdActions({
        items,
        entityLabel,
        entityLabelPlural,
        refresh,
        selectedIds,
        setSelectedIds
    });

    // ── Sync: Page existence check ───────────────────────────────────────────
    useEffect(() => {
        if (page > pagination.pages && pagination.pages > 0) {
            replaceRoute({ page: pagination.pages });
        }
    }, [page, pagination.pages, replaceRoute]);

    const columnOptions = useMemo(() => [
        { id: "select", label: "Checkboxes" },
        { id: "image", label: "Image" },
        { id: "details", label: "Details" },
        { id: "seller", label: "Seller" },
        { id: "location", label: "Location" },
        { id: "attribute", label: presentation.attributeHeader },
        { id: "risk", label: "Risk" },
        { id: "status", label: "Status" },
        { id: "created", label: "Created" },
        { id: "actions", label: "Actions" },
    ], [presentation.attributeHeader]);

    return (
        <AdminPageShell
            headerVariant="compact"
            title={listingType ? presentation.pageTitle : "Listings"}
            tabs={
                <div className="flex flex-col gap-4 mb-2">
                    <AdminModuleTabs tabs={moderationTabs} variant="primary" />
                    <AdminModuleTabs tabs={moduleTabs} variant="pills" />
                </div>
            }
            actions={
                <div className="flex items-center gap-2">
                    <AdsColumnVisibilityMenu
                        columnOptions={columnOptions}
                        columnVisibility={columnVisibility}
                        onChangeColumnVisibility={(id, visible) =>
                            setColumnVisibility((prev) => ({ ...prev, [id]: visible }))
                        }
                    />

                    <button
                        type="button"
                        onClick={refresh}
                        className="inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-foreground-secondary hover:bg-slate-50 transition-all active:scale-95"
                    >
                        <RefreshCcw size={14} /> 
                        <span>Refresh</span>
                    </button>
                </div>
            }
        >
            <div className="flex min-h-0 flex-1 flex-col gap-3">
                {/* Filter toolbar */}
                <AdminFilterToolbar
                    search={filters.search}
                    onSearchChange={(val) => updateFilter("search", val)}
                    searchPlaceholder="Search title, description, seller, phone"
                    status={filters.status}
                    onStatusChange={(val) => updateFilter("status", val as ModerationFilters["status"])}
                    statusOptions={activeStatusOptions}
                    extraFilters={
                        <AdsFilterToolbarExtras
                            filters={filters}
                            updateFilter={updateFilter}
                            clearFilters={clearFilters}
                        />
                    }
                />

                {error && (
                    <div className="flex items-center gap-2 rounded-lg border border-red-100 bg-red-50 p-4 text-sm font-medium text-red-600">
                        <AlertCircle size={16} /> {error}
                    </div>
                )}

                <div className="min-h-0 flex-1">
                    <AdsTable
                        data={items}
                        listingType={listingType}
                        isLoading={isLoading}
                        emptyMessage={`No ${entityLabelPlural} matched current moderation filters`}
                        currentPage={page}
                        totalPages={pagination.pages}
                        totalItems={pagination.total}
                        pageSize={pagination.limit}
                        selectedIds={selectedIds}
                        onToggleSelect={toggleSelect}
                        onToggleSelectAll={toggleSelectAll}
                        onPageChange={(nextPage) => replaceRoute({ page: nextPage })}
                        onPageSizeChange={(size) => {
                            replaceRoute({ page: 1, limit: size });
                        }}
                        onView={handleView}
                        onApprove={(item) => void handleApprove(item)}
                        onReject={openSingleReject}
                        onDeactivate={(item) => void handleDeactivate(item)}
                        onActivate={(item) => void handleActivate(item)}
                        onDelete={(item) => void handleDelete(item)}
                        onBanSeller={(item) => void handleBanSeller(item)}
                        showCheckboxes={true}
                        columnVisibility={columnVisibility}
                        onColumnVisibilityChange={setColumnVisibility}
                        hideColumnVisibilityButton={true}
                        bulkActions={
                            selectedCount > 0 ? (
                                <div className="flex items-center gap-2">
                                    {normalizedStatus === 'pending' && (
                                        <>
                                            <button
                                                type="button"
                                                onClick={() => void handleBulkApprove()}
                                                className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-semibold text-white hover:bg-emerald-700 transition-all shadow-sm"
                                            >
                                                Approve Selected
                                            </button>
                                            <button
                                                type="button"
                                                onClick={openBulkReject}
                                                className="rounded-lg bg-amber-600 px-3 py-2 text-xs font-semibold text-white hover:bg-amber-700 transition-all shadow-sm"
                                            >
                                                Reject Selected
                                            </button>
                                        </>
                                    )}

                                    {filters.status !== 'pending' && (
                                        <div className="flex items-center gap-2">
                                            {filters.status === 'live' && (
                                                <>
                                                    <button
                                                        type="button"
                                                        onClick={() => void handleBulkDeactivate()}
                                                        className="rounded-lg bg-slate-600 px-3 py-2 text-xs font-semibold text-white hover:bg-slate-700 transition-all shadow-sm"
                                                    >
                                                        Deactivate Selected
                                                    </button>
                                                    <button
                                                        type="button"
                                                        onClick={() => void handleBulkExpire()}
                                                        className="rounded-lg bg-orange-600 px-3 py-2 text-xs font-semibold text-white hover:bg-orange-700 transition-all shadow-sm"
                                                    >
                                                        Expire Selected
                                                    </button>
                                                </>
                                            )}
                                            {(filters.status === 'live' || filters.status === 'expired') && (
                                                <button
                                                    type="button"
                                                    onClick={() => void handleBulkExtend()}
                                                    className="rounded-lg bg-indigo-600 px-3 py-2 text-xs font-semibold text-white hover:bg-indigo-700 transition-all shadow-sm"
                                                >
                                                    Extend Selected
                                                </button>
                                            )}
                                            <button
                                                type="button"
                                                onClick={() => void handleBulkResendWarnings()}
                                                className="rounded-lg border border-indigo-200 bg-indigo-50 px-3 py-2 text-xs font-semibold text-indigo-700 hover:bg-indigo-100 transition-all shadow-sm"
                                            >
                                                Resend Warnings
                                            </button>
                                            {listingType === 'ad' && (
                                                <button
                                                    type="button"
                                                    onClick={() => void handleBulkResendSpotlightWarnings()}
                                                    className="rounded-lg border border-fuchsia-200 bg-fuchsia-50 px-3 py-2 text-xs font-semibold text-fuchsia-700 hover:bg-fuchsia-100 transition-all shadow-sm"
                                                >
                                                    Resend Spotlight
                                                </button>
                                            )}
                                        </div>
                                    )}

                                    <button
                                        type="button"
                                        onClick={() => void handleBulkDelete()}
                                        className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-xs font-semibold text-foreground-secondary hover:bg-slate-50 transition-all shadow-sm"
                                    >
                                        Delete Selected
                                    </button>
                                </div>
                            ) : undefined
                        }
                    />
                </div>

                <AdminErrorBoundary fallbackLabel="Moderation Modal Error">
                    <RejectAdModal
                        open={rejectModalOpen}
                        title={rejectTitle}
                        entityLabel={entityLabel}
                        affectedCount={rejectTargetIds.length}
                        isSubmitting={isMutating}
                        onClose={() => {
                            setRejectModalOpen(false);
                            setRejectTargetIds([]);
                            setRejectTitle(undefined);
                        }}
                        onSubmit={handleRejectSubmit}
                    />

                    {/* Hardened Deletion Modal */}
                    <CatalogModal
                        isOpen={deleteModalOpen}
                        onClose={() => !isMutating && setDeleteModalOpen(false)}
                        title={`Delete ${entityLabelPlural}`}
                    >
                        <div className="p-6 space-y-4">
                            <div className="flex items-start gap-4 p-4 bg-red-50 rounded-xl border border-red-200">
                                <AlertCircle className="h-5 w-5 text-red-600 shrink-0 mt-0.5" />
                                <div>
                                    <h3 className="text-sm font-bold text-red-900">Permanent Action</h3>
                                    <p className="mt-1 text-sm text-red-800 leading-relaxed">
                                        Are you sure you want to delete {deleteTargetIds.length === 1 ? `"${deleteDisplayTitle || "this " + entityLabel}"` : `${deleteTargetIds.length} selected ${entityLabelPlural}`}? 
                                        This action cannot be undone and will remove all associated data.
                                    </p>
                                </div>
                            </div>
                            <div className="flex justify-end gap-3 pt-2">
                                <button
                                    type="button"
                                    disabled={isMutating}
                                    onClick={() => setDeleteModalOpen(false)}
                                    className="px-4 py-2 rounded-lg border border-slate-200 text-sm font-semibold text-foreground-secondary hover:bg-slate-50 transition-all"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="button"
                                    disabled={isMutating}
                                    onClick={handleConfirmDelete}
                                    className="flex items-center gap-2 px-4 py-2 rounded-lg bg-red-600 text-white text-sm font-bold hover:bg-red-700 transition-all shadow-lg shadow-red-200"
                                >
                                    {isMutating ? <><Loader2 size={16} className="animate-spin" /> Deleting...</> : "Confirm Delete"}
                                </button>
                            </div>
                        </div>
                    </CatalogModal>

                    {/* Hardened Ban Modal */}
                    <CatalogModal
                        isOpen={banModalOpen}
                        onClose={() => !isMutating && setBanModalOpen(false)}
                        title="Block Seller"
                    >
                        <div className="p-6 space-y-4">
                            <div className="flex items-start gap-4 p-4 bg-amber-50 rounded-xl border border-amber-200">
                                <AlertCircle className="h-5 w-5 text-amber-600 shrink-0 mt-0.5" />
                                <div>
                                    <h3 className="text-sm font-bold text-amber-900">Restrict Platform Access</h3>
                                    <p className="mt-1 text-sm text-amber-800 leading-relaxed">
                                        You are about to block <strong>{banTargetSellerName || "this seller"}</strong>. 
                                        They will be unable to post new {entityLabelPlural} or manage existing ones until globally reinstated by an admin.
                                    </p>
                                </div>
                            </div>
                            <div className="flex justify-end gap-3 pt-2">
                                <button
                                    type="button"
                                    disabled={isMutating}
                                    onClick={() => setBanModalOpen(false)}
                                    className="px-4 py-2 rounded-lg border border-slate-200 text-sm font-semibold text-foreground-secondary hover:bg-slate-50 transition-all"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="button"
                                    disabled={isMutating}
                                    onClick={handleConfirmBan}
                                    className="flex items-center gap-2 px-4 py-2 rounded-lg bg-amber-600 text-white text-sm font-bold hover:bg-amber-700 transition-all shadow-lg shadow-amber-200"
                                >
                                    {isMutating ? <><Loader2 size={16} className="animate-spin" /> Blocking...</> : "Block Seller"}
                                </button>
                            </div>
                        </div>
                    </CatalogModal>

                    <ViewAdModal
                        open={viewModalOpen}
                        ad={viewAd}
                        listingType={listingType}
                        loading={viewLoading}
                        error={viewError}
                        onClose={() => {
                            setViewModalOpen(false);
                            setViewAd(null);
                            setViewError("");
                        }}
                        onApprove={handleModalApprove}
                        onReject={(adId) => {
                            const ad = items.find((item) => item.id === adId) || viewAd;
                            if (ad) openSingleReject(ad);
                        }}
                        onDeactivate={handleModalDeactivate}
                        onActivate={handleModalActivate}
                        onBlockSeller={handleModalBlockSeller}
                        onExtend={handleModalExtend}
                    />
                </AdminErrorBoundary>
            </div>
        </AdminPageShell>
    );
}

