import React, { useState } from 'react';
import { View, TouchableOpacity, ActivityIndicator, Alert } from 'react-native';
import { Container, Card, AppText } from '@esparex/mobile-ui';
import { base } from '@esparex/design-tokens';
import * as ImagePicker from 'expo-image-picker';
import { BusinessFormState } from '../../domain/BusinessFormState';
import { services } from '../../../../bootstrap';

interface StepDocumentsUploadProps {
  formState: BusinessFormState;
  onChange: (updates: Partial<BusinessFormState>) => void;
}

export function StepDocumentsUpload({ formState, onChange }: StepDocumentsUploadProps) {
  const [uploading, setUploading] = useState(false);

  const handlePickDocument = async (docType: 'id_proof' | 'business_proof' | 'certificate') => {
    try {
      const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
      if (!permission.granted) {
        Alert.alert('Permission Required', 'Media library access is required to attach verification documents.');
        return;
      }

      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ImagePicker.MediaTypeOptions.Images,
        quality: 0.8,
      });

      if (!result.canceled && result.assets && result.assets[0]) {
        const asset = result.assets[0];
        setUploading(true);
        const fileUrl = await services.businessService.uploadDocument(asset.uri, asset.mimeType || 'image/jpeg');

        const updatedDocs = formState.documents.filter((d) => d.type !== docType);
        updatedDocs.push({
          type: docType,
          url: fileUrl,
          idProofType: docType === 'id_proof' ? 'aadhaar' : undefined,
        });

        onChange({ documents: updatedDocs });
      }
    } catch (err: any) {
      Alert.alert('Upload Failed', err?.message || 'Unable to upload document. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  const isUploaded = (type: string) => formState.documents.some((d) => d.type === type);

  return (
    <Container className="p-4">
      <Card className="p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800">
        <AppText variant="h3" className="font-bold text-slate-900 dark:text-slate-100 mb-1">
          Verification Documents
        </AppText>
        <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mb-4">
          Upload your ID proof and business verification documents
        </AppText>

        {uploading && (
          <View className="flex-row items-center bg-sky-50 dark:bg-sky-950 p-2.5 rounded-lg mb-3">
            <ActivityIndicator size="small" color={base.brand[500]} />
            <AppText variant="caption" className="ml-2 text-sky-700 dark:text-sky-300">
              Uploading document to secure storage...
            </AppText>
          </View>
        )}

        <View className="flex-row items-center justify-between py-3 border-b border-slate-100 dark:border-slate-800">
          <View className="flex-1 mr-3">
            <AppText variant="body" className="font-semibold text-slate-900 dark:text-slate-100 text-sm">
              Identity Proof (Aadhaar / PAN) *
            </AppText>
            <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mt-0.5">
              Government issued photo ID proof
            </AppText>
          </View>
          <TouchableOpacity
            className={`px-3.5 py-2 rounded-lg ${
              isUploaded('id_proof')
                ? 'bg-emerald-100 dark:bg-emerald-950'
                : 'bg-brand-600 dark:bg-brand-500'
            }`}
            onPress={() => handlePickDocument('id_proof')}
            disabled={uploading}
          >
            <AppText
              variant="caption"
              className={`font-semibold ${
                isUploaded('id_proof')
                  ? 'text-emerald-700 dark:text-emerald-300'
                  : 'text-white'
              }`}
            >
              {isUploaded('id_proof') ? '✓ Attached' : 'Upload ID'}
            </AppText>
          </TouchableOpacity>
        </View>

        <View className="flex-row items-center justify-between py-3">
          <View className="flex-1 mr-3">
            <AppText variant="body" className="font-semibold text-slate-900 dark:text-slate-100 text-sm">
              Business Proof (GST / Shop License)
            </AppText>
            <AppText variant="caption" className="text-slate-500 dark:text-slate-400 mt-0.5">
              Shop establishment certificate or GST card
            </AppText>
          </View>
          <TouchableOpacity
            className={`px-3.5 py-2 rounded-lg ${
              isUploaded('business_proof')
                ? 'bg-emerald-100 dark:bg-emerald-950'
                : 'bg-brand-600 dark:bg-brand-500'
            }`}
            onPress={() => handlePickDocument('business_proof')}
            disabled={uploading}
          >
            <AppText
              variant="caption"
              className={`font-semibold ${
                isUploaded('business_proof')
                  ? 'text-emerald-700 dark:text-emerald-300'
                  : 'text-white'
              }`}
            >
              {isUploaded('business_proof') ? '✓ Attached' : 'Upload Proof'}
            </AppText>
          </TouchableOpacity>
        </View>
      </Card>
    </Container>
  );
}

import React, { useState, useCallback, useRef } from 'react';
import { View, FlatList, TouchableOpacity, KeyboardAvoidingView, Platform, StyleSheet } from 'react-native';
import { Screen, Container, AppText, AppInput, AppIcon } from '@esparex/mobile-ui';
import { base } from '@esparex/design-tokens';
import { useChatThread } from '../hooks/useChatThread';
import { useSendMessage } from '../hooks/useSendMessage';
import { useProfile } from '../../../user/presentation/hooks/useProfile';
import { IMessageDTO } from '@esparex/contracts';
import { ErrorState } from '../../../common/components/ErrorState';

interface ChatThreadScreenProps {
  conversationId: string;
  currentUserId?: string;
  onBack?: () => void;
}

export const ChatThreadScreen: React.FC<ChatThreadScreenProps> = ({
  conversationId,
  currentUserId: currentUserIdProp,
  onBack,
}) => {
  const { data: userProfile } = useProfile();
  const activeUserId = currentUserIdProp || userProfile?.id || '';
  const { data: messages, isLoading, isError, refetch } = useChatThread(conversationId);
  const sendMessageMutation = useSendMessage();
  const [inputText, setInputText] = useState('');
  const flatListRef = useRef<FlatList>(null);

  const handleSend = useCallback(() => {
    const trimmed = inputText.trim();
    if (!trimmed || sendMessageMutation.isPending) return;

    sendMessageMutation.mutate(
      { conversationId, text: trimmed },
      {
        onSuccess: () => {
          setInputText('');
          setTimeout(() => flatListRef.current?.scrollToEnd({ animated: true }), 100);
        },
      }
    );
  }, [inputText, conversationId, sendMessageMutation]);

  const renderMessageItem = useCallback(
    ({ item }: { item: IMessageDTO }) => {
      const isMine = item.senderId === activeUserId;
      const formattedTime = item.createdAt
        ? new Date(item.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        : '';

      if (item.isSystemMessage) {
        return (
          <View className="items-center my-2 px-4">
            <View className="bg-slate-200 dark:bg-slate-800 rounded-full px-3 py-1">
              <AppText variant="caption" className="text-slate-600 dark:text-slate-400 text-xs">
                {item.text}
              </AppText>
            </View>
          </View>
        );
      }

      return (
        <View className={`my-1.5 flex-row ${isMine ? 'justify-end' : 'justify-start'}`}>
          <View
            className={`max-w-[78%] rounded-2xl px-4 py-2.5 ${
              isMine
                ? 'bg-brand-600 rounded-tr-none text-white'
                : 'bg-slate-200 dark:bg-slate-800 rounded-tl-none'
            }`}
          >
            <AppText
              variant="body"
              className={isMine ? 'text-white font-medium' : 'text-slate-900 dark:text-slate-100 font-medium'}
            >
              {item.text}
            </AppText>
            {formattedTime ? (
              <AppText
                variant="tiny"
                className={`text-right mt-1 ${
                  isMine ? 'text-brand-100' : 'text-slate-500 dark:text-slate-400'
                }`}
              >
                {formattedTime}
              </AppText>
            ) : null}
          </View>
        </View>
      );
    },
    [activeUserId]
  );

  if (isError) {
    return (
      <Screen>
        <ErrorState onRetry={refetch} />
      </Screen>
    );
  }

  return (
    <Screen edges={['top', 'left', 'right']}>
      <Container className="flex-1 bg-slate-50 dark:bg-slate-950">
        {/* Header */}
        <View className="flex-row items-center p-4 border-b border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900">
          {onBack && (
            <TouchableOpacity onPress={onBack} className="mr-3" accessibilityLabel="Back to chat list">
              <AppIcon name="ArrowLeft" size={20} color={base.brand[500]} />
            </TouchableOpacity>
          )}
          <AppText variant="h3" className="font-bold text-slate-900 dark:text-white flex-1">
            Chat Thread
          </AppText>
        </View>

        {/* Keyboard-aware Message Feed */}
        <KeyboardAvoidingView
          style={styles.kavContainer}
          behavior={Platform.OS === 'ios' ? 'padding' : undefined}
          keyboardVerticalOffset={Platform.OS === 'ios' ? 90 : 0}
        >
          <FlatList
            ref={flatListRef}
            data={messages || []}
            keyExtractor={(item) => item.id}
            renderItem={renderMessageItem}
            contentContainerStyle={styles.scrollContent}
            showsVerticalScrollIndicator={false}
            onContentSizeChange={() => flatListRef.current?.scrollToEnd({ animated: false })}
            windowSize={10}
            maxToRenderPerBatch={10}
            initialNumToRender={15}
            removeClippedSubviews={true}
          />

          {/* Input Composer */}
          <View className="flex-row items-center p-3 border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900">
            <View className="flex-1 mr-2">
              <AppInput
                placeholder="Type a message..."
                value={inputText}
                onChangeText={setInputText}
                onSubmitEditing={handleSend}
              />
            </View>
            <TouchableOpacity
              onPress={handleSend}
              disabled={!inputText.trim() || sendMessageMutation.isPending}
              className={`w-11 h-11 rounded-full items-center justify-center ${
                inputText.trim() ? 'bg-brand-600' : 'bg-slate-200 dark:bg-slate-800'
              }`}
              accessibilityLabel="Send message"
            >
              <AppIcon name="Send" size={18} color={inputText.trim() ? '#ffffff' : base.slate[400]} />
            </TouchableOpacity>
          </View>
        </KeyboardAvoidingView>
      </Container>
    </Screen>
  );
};

const styles = StyleSheet.create({
  kavContainer: { flex: 1 },
  scrollContent: { padding: 16, paddingBottom: 20 },
});

import { IListingRepository } from './IListingRepository';
