          )}
        </View>

        {/* Notifications List */}
        <FlatList
          data={notifications || []}
          keyExtractor={(item) => item.id}
          renderItem={renderNotificationItem}
          showsVerticalScrollIndicator={false}
          refreshControl={<RefreshControl refreshing={isRefetching} onRefresh={refetch} />}
          removeClippedSubviews={true}
