import axios, { AxiosError, AxiosRequestConfig } from 'axios';

type QueuedRequest = {
  resolve: (value?: unknown) => void;
  reject: (reason?: unknown) => void;
  config: AxiosRequestConfig;
};

export type RefreshExecutor = () => Promise<string | null>;

let refreshExecutor: RefreshExecutor | null = null;
let isRefreshing = false;
let failedQueue: QueuedRequest[] = [];

/**
 * Sets the injectable refresh executor to decouple authentication 
 * logic from the API infrastructure.
 */
export const setRefreshExecutor = (executor: RefreshExecutor) => {
  refreshExecutor = executor;
};

/**
 * Processes the queue of failed requests.
 * @param error - If present, rejects all queued requests with this error.
 * @param token - If present, resolves all queued requests.
 */
const processQueue = (error: Error | null, token: string | null = null) => {
  failedQueue.forEach(prom => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });

  failedQueue = [];
};

/**
 * Enqueues a failed request or initiates a refresh if one isn't already in progress.
 */
export const handleRefresh = async (failedRequestConfig: AxiosRequestConfig): Promise<unknown> => {
  if (isRefreshing) {
    return new Promise((resolve, reject) => {
      failedQueue.push({ resolve, reject, config: failedRequestConfig });
    });
  }

  isRefreshing = true;

  return new Promise((resolve, reject) => {
    // Add the original request to the queue to be retried
    failedQueue.push({ resolve, reject, config: failedRequestConfig });

    if (!refreshExecutor) {
      const err = new Error('Refresh executor is not configured.');
      processQueue(err, null);
      isRefreshing = false;
      return;
    }

    refreshExecutor()
      .then((token) => {
        processQueue(null, token);
      })
      .catch((err) => {
        processQueue(err, null);
      })
      .finally(() => {
        isRefreshing = false;
      });
  });
};

import { AxiosInstance } from 'axios';
import { IAuthService, AuthResult } from './AuthService';
import { ITokenStorage } from './ITokenStorage';
import { IPushTokenRegistrationService } from '../../features/notifications/application/IPushTokenRegistrationService';

export class AuthServiceImpl implements IAuthService {
  constructor(
    private readonly apiClient: AxiosInstance,
    private readonly tokenStorage: ITokenStorage,
    private readonly pushTokenRegistrationService?: IPushTokenRegistrationService
  ) {
    // Bind the executeTokenRefresh context so it can be passed freely
    this.executeTokenRefresh = this.executeTokenRefresh.bind(this);
  }

  async login(payload: unknown): Promise<AuthResult> {
    const response = await this.apiClient.post('/auth/login', payload);

    // Ensure we handle cases where the token might not be returned immediately,
    // though the contract implies it will be in the response body.
    const accessToken = response.data?.accessToken;
    const refreshToken = response.data?.refreshToken;
    const userId = response.data?.userId || 'unknown-user';

    if (accessToken && refreshToken) {
      await this.tokenStorage.setTokens(accessToken, refreshToken);
    }

    if (this.pushTokenRegistrationService) {
      await this.pushTokenRegistrationService.registerPushToken();
    }

    // Map backend DTO to Domain AuthResult
    return {
      userId,
    };
  }

  async logout(): Promise<void> {
    try {
      if (this.pushTokenRegistrationService) {
        await this.pushTokenRegistrationService.unregisterPushToken();
      } else {
        await this.apiClient.post('/auth/logout');
      }
    } catch (e) {
      // Ignore network errors on logout, we still want to clear the local session
    } finally {
      await this.tokenStorage.clearTokens();
    }
  }

  async executeTokenRefresh(): Promise<string> {
    const tokens = await this.tokenStorage.getTokens();

    if (!tokens.refreshToken) {
      throw new Error('No refresh token available');
    }

    try {
      const response = await this.apiClient.post('/auth/refresh', {
        refreshToken: tokens.refreshToken,
      });

      const newAccessToken = response.data?.accessToken;
      const newRefreshToken = response.data?.refreshToken;

      if (!newAccessToken) {
        throw new Error('No access token returned from refresh endpoint');
      }

      await this.tokenStorage.setTokens(
        newAccessToken, 
        newRefreshToken || tokens.refreshToken // Fallback to existing refresh token if not rotated
      );

      return newAccessToken;
    } catch (error) {
      // If refresh fails, clear tokens so the user is forced to log in again
      await this.tokenStorage.clearTokens();
      throw error;
    }
  }
}

import { SecureStoreAdapter } from './SecureStoreAdapter';

export type SessionState =
  | { status: 'authenticated'; accessToken: string; refreshToken: string }
  | { status: 'anonymous' };

/**
 * Handles the cold-launch session initialization by querying the secure store.
 * Returns the resolved session state to be utilized by the AuthProvider later.
 * Architecture Note: Does not mutate application state context directly.
 */
export const SessionRestoration = {
  /**
   * Restores the session from the hardware-backed keystore.
   */
  async restoreSession(): Promise<SessionState> {
    try {
      const { accessToken, refreshToken } = await SecureStoreAdapter.getTokens();

      if (accessToken && refreshToken) {
        return {
          status: 'authenticated',
          accessToken,
          refreshToken,
        };
      }

      return { status: 'anonymous' };
    } catch (error) {
      // In case of Keystore failure, fallback to anonymous (e.g. key corruption)
      return { status: 'anonymous' };
    }
  }
};

