"use client";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { Loader2 } from "@/icons/IconRegistry";
import { Login } from "@/components/user/Login";
import { useAuth } from "@/context/AuthContext";
import { normalizeAuthCallbackUrl } from "@/lib/authHelpers";

interface LoginFlowProps {
  callbackUrl?: string | null;
  mode?: "page" | "modal";
  onClose?: () => void;
  onBack?: () => void;
}

export function LoginFlow({
  callbackUrl,
  mode = "modal",
  onClose,
  onBack,
}: LoginFlowProps) {
  const router = useRouter();
  const { status } = useAuth();
  const safeCallbackUrl = useMemo(
    () => normalizeAuthCallbackUrl(callbackUrl),
    [callbackUrl]
  );

  const [isRedirecting, setIsRedirecting] = useState(false);

  const handleLoginSuccess = useCallback(
    () => {
      setIsRedirecting(true);
      onClose?.();
      void router.push(safeCallbackUrl);
    },
    [safeCallbackUrl, onClose, router]
  );

  useEffect(() => {
    if (isRedirecting) return;
    // Page mode auto-redirect guard if already authenticated when visiting /login page directly
    if (mode === "page" && status === "authenticated") {
      setIsRedirecting(true);
      void router.push(safeCallbackUrl);
    }
  }, [isRedirecting, mode, status, safeCallbackUrl, router]);

  return (
    <div className="relative">
      <Login
        mode={mode}
        onLoginSuccess={handleLoginSuccess}
        onBack={onBack ?? (mode === "page" ? () => void router.push("/") : undefined)}
      />

      {isRedirecting && status !== "unauthenticated" && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/80 backdrop-blur-sm">
          <div className="space-y-3 text-center">
            <Loader2 className="mx-auto h-8 w-8 animate-spin text-primary" />
            <p className="text-sm text-muted-foreground">
              Setting up your account...
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { useLocationStatus, useLocationDispatch, useLocationData } from "@/context/LocationContext";

export function HomeLocationAutoPrompt() {
    const { status, promptDismissed } = useLocationStatus();
    const { location } = useLocationData();
    const { detectLocation } = useLocationDispatch();
    const hasPrompted = useRef(false);

    useEffect(() => {
        // Only run once per session
        if (hasPrompted.current) {
            return;
        }

        // If the global context resolved to 'prompt' and the user hasn't dismissed it,
        // and they don't have a saved location
        if (status === "prompt" && !promptDismissed && location.source === "default") {
            hasPrompted.current = true;
            // Trigger automatic detection (persist = true, force = false, isAutoPrompt = true)
            detectLocation(true, false, true).catch((e) => {
                console.error(`[HomeLocationAutoPrompt] detectLocation error:`, e);
            }); 
        }
    }, [status, promptDismissed, location.source, detectLocation]);

    return null;
}

