interface CategorySelectorGridProps {
    categories: Array<{ id?: string; name?: string; icon?: any }>;
    selectedCategoryId?: string;
    onSelect: (id: string) => void;
    disabled?: boolean;
    defaultIcon: any;
    error?: string;
}

export function CategorySelectorGrid({
    categories,
    selectedCategoryId,
    onSelect,
    disabled = false,
    defaultIcon: DefaultIcon,
    error
}: CategorySelectorGridProps) {
    return (
        <div className="space-y-1.5">
            <div className={cn(
                "grid grid-cols-3 sm:grid-cols-4 gap-2.5 rounded-xl",
                error ? "ring-2 ring-red-100 bg-red-50/30 p-1" : ""
            )}>
            {categories.map((cat) => {
                const Icon = cat.icon || DefaultIcon;
                const selected = cat.id === selectedCategoryId;
                return (
                    <button
                        key={cat.id}
                        type="button"
                        onClick={(e) => {
                            e.currentTarget.blur();
                            onSelect(cat.id || "");
                        }}
                        disabled={disabled || (disabled && !selected)}
                        aria-pressed={selected}
                        className={cn(
                            "flex flex-col items-center justify-center gap-1 h-[56px] sm:h-[60px] py-1 px-2 rounded-xl transition-all duration-200 cursor-pointer select-none group border",
                            selected
                                ? "bg-blue-50/90 border-2 border-blue-600 text-blue-950 font-bold shadow-sm ring-2 ring-blue-600/15"
                                : "bg-white hover:bg-slate-50 border-slate-200 text-slate-700 hover:border-slate-300 shadow-2xs",
                            disabled && !selected ? "opacity-40 cursor-not-allowed" : ""
                        )}
                    >
                        <Icon className={cn("w-4 h-4 sm:w-5 sm:h-5 transition-colors", selected ? "text-blue-600 stroke-[2.2]" : "text-slate-400 group-hover:text-blue-600")} />
                        <span className={cn(
                            "text-tiny sm:text-xs font-semibold text-center leading-tight tracking-tight w-full px-0.5",
                            selected ? "text-blue-950 font-bold" : "text-slate-700 group-hover:text-slate-900 line-clamp-2"
                        )}>
                            {cat.name}
                        </span>
                    </button>
                );
            })}
            </div>
            {error && <p className="text-xs font-medium text-red-500 px-1">{error}</p>}
        </div>
    );
}

export function getFirstFormErrorMessage(error: unknown): string | undefined {
    if (!error) return undefined;
    if (typeof error === "string") return error;
    if (Array.isArray(error)) {
        for (const item of error) {
            const nested = getFirstFormErrorMessage(item);
            if (nested) return nested;
        }
        return undefined;
    }
    if (typeof error === "object") {
        const record = error as Record<string, unknown>;
        if (typeof record.message === "string" && record.message.trim().length > 0) {
            return record.message;
        }
        for (const value of Object.values(record)) {
            const nested = getFirstFormErrorMessage(value);
            if (nested) return nested;
        }
    }
    return undefined;
}

"use client";

import { useState, useRef, useCallback } from "react";
import Image from "next/image";
import { Upload, X, AlertCircle } from "@/icons/IconRegistry";
import type { ListingImage } from "@/types/listing";
import { cn } from "@/components/ui/utils";
import { Stack } from "@esparex/ui";

import { getRemovePhotoAriaLabel } from "./uploadHelpers";
import { useImageDropzone } from "./useImageDropzone";
import { UploadSourcePicker } from "./UploadSourcePicker";
import { useIsMobileDevice } from "@/components/ui/useMobile";

interface ListingImagesFieldProps {
    images: ListingImage[];
    onUpload: (files: File[]) => void;
    onRemove: (idOrIndex: any) => void;
    onSetMain?: (index: number) => void;
    onReorder?: (startIndex: number, endIndex: number) => void;
    firstImageBadgeLabel?: string;
    error?: string;
    helperText?: string;
    disabled?: boolean;
}

export function ListingImagesField({
    images,
    onUpload,
    onRemove,
    onSetMain,
    onReorder,
    firstImageBadgeLabel = "Cover Photo",
    error,
    helperText,
    disabled = false,
}: ListingImagesFieldProps) {
    const [pickerOpen, setPickerOpen] = useState(false);
    const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
    const [dropTargetIndex, setDropTargetIndex] = useState<number | null>(null);

    const cameraInputRef = useRef<HTMLInputElement>(null);
    const galleryInputRef = useRef<HTMLInputElement>(null);
    const isMobileDevice = useIsMobileDevice();

    const { isDraggingOver, dropzoneProps } = useImageDropzone({ onUpload, disabled });

    const handleOpenPicker = () => {
        if (disabled || pickerOpen) return;
        if (isMobileDevice) {
            setPickerOpen(true);
        } else {
            if (galleryInputRef.current) {
                galleryInputRef.current.value = "";
                galleryInputRef.current.click();
            }
        }
    };

    const handleCamera = () => {
        if (cameraInputRef.current) {
            cameraInputRef.current.value = "";
            cameraInputRef.current.click();
        }
    };

    const handleGallery = () => {
        if (galleryInputRef.current) {
            galleryInputRef.current.value = "";
            galleryInputRef.current.click();
        }
    };

    const handleDrop = useCallback((e: React.DragEvent<HTMLDivElement>, targetIndex: number) => {
        e.preventDefault();
        e.stopPropagation();
        if (onReorder && draggedIndex !== null && draggedIndex !== targetIndex) {
            onReorder(draggedIndex, targetIndex);
        }
        setDraggedIndex(null);
        setDropTargetIndex(null);
    }, [draggedIndex, onReorder]);

    return (
        <Stack gap="sm">
            <div className="flex justify-between items-center mb-1.5">
                <label className="text-xs font-semibold text-foreground">
                    Photos (up to 10)
                </label>
                <span className="text-tiny font-medium text-muted-foreground">
                    {images.length}/10 uploaded
                </span>
            </div>

            <div className="w-full">
                <Stack gap="md">
                    <div
                        {...dropzoneProps}
                        className={cn(
                            "flex min-h-[112px] w-full flex-col items-center justify-center rounded-xl border-2 border-dashed p-3 transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 relative overflow-hidden",
                            disabled
                                ? "opacity-60 cursor-not-allowed border-border bg-muted/50"
                                : isDraggingOver
                                    ? "border-primary bg-primary/10 scale-[1.01] shadow-md"
                                    : "border-border bg-card hover:bg-muted/30 hover:border-primary/50"
                        )}
                    >
                        {disabled ? (
                            <div className="flex flex-col items-center justify-center text-primary animate-pulse py-2">
                                <div className="h-6 w-6 border-2 border-primary border-t-transparent rounded-full animate-spin mb-2" />
                                <span className="text-xs font-semibold">Processing & Compressing Photos...</span>
                            </div>
                        ) : isDraggingOver ? (
                            <div className="flex flex-col items-center justify-center text-primary py-2">
                                <Upload className="w-8 h-8 mb-2 text-primary animate-bounce" />
                                <span className="text-xs font-semibold">Drop photos here</span>
                            </div>
                        ) : (
                            <div className="flex flex-col items-center gap-2">
                                <button
                                    type="button"
                                    disabled={disabled}
                                    onClick={handleOpenPicker}
                                    aria-label="Add product photos"
                                    className="flex h-11 items-center justify-center gap-2 rounded-xl border border-border bg-background px-5 text-xs font-semibold text-foreground shadow-sm transition-all hover:bg-muted hover:border-primary/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary touch-manipulation cursor-pointer active:scale-95"
                                >
                                    <Upload className="w-4 h-4 text-primary" />
                                    <span>+ Add Photos</span>
                                </button>
                                {images.length === 0 && (
                                    <span className="text-xs text-muted-foreground">First image will be the cover</span>
                                )}
                            </div>
                        )}
                    </div>

                    <input
                        ref={cameraInputRef}
                        type="file"
                        accept="image/*"
                        capture="environment"
                        className="hidden"
                        tabIndex={-1}
                        aria-label="Take photo with camera"
                        disabled={disabled}
                        onChange={(e) => {
                            if (!e.target.files) return;
                            onUpload(Array.from(e.target.files));
                            e.target.value = "";
                        }}
                    />

                    <input
                        ref={galleryInputRef}
                        type="file"
                        accept="image/*"
                        multiple
                        className="hidden"
                        tabIndex={-1}
                        aria-label="Choose photos from gallery"
                        disabled={disabled}
                        onChange={(e) => {
                            if (!e.target.files) return;
                            onUpload(Array.from(e.target.files));
                            e.target.value = "";
                        }}
                    />

                    <UploadSourcePicker
                        open={pickerOpen}
                        onOpenChange={setPickerOpen}
                        onCamera={handleCamera}
                        onGallery={handleGallery}
                        variant="listing"
                    />

                    {images.length > 0 && (
                        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-3">
                            {images.map((img, index) => (
                                <div
                                    key={img.id || index}
                                    draggable={Boolean(onReorder && !disabled)}
                                    onDragStart={(e) => {
                                        setDraggedIndex(index);
                                        e.dataTransfer.effectAllowed = "move";
                                        e.dataTransfer.setData("text/plain", String(index));
                                    }}
                                    onDragOver={(e) => {
                                        if (onReorder) {
                                            e.preventDefault();
                                            e.dataTransfer.dropEffect = "move";
                                            if (draggedIndex !== index) {
                                                setDropTargetIndex(index);
                                            }
                                        }
                                    }}
                                    onDragLeave={() => {
                                        if (dropTargetIndex === index) {
                                            setDropTargetIndex(null);
                                        }
                                    }}
                                    onDrop={(e) => handleDrop(e, index)}
                                    onDragEnd={() => {
                                        setDraggedIndex(null);
                                        setDropTargetIndex(null);
                                    }}
                                    className={cn(
                                        "relative aspect-square rounded-xl overflow-hidden border bg-muted group shadow-sm transition-all duration-200",
                                        onReorder && !disabled && "cursor-grab active:cursor-grabbing",
                                        draggedIndex === index && "opacity-40 scale-90 border-primary border-dashed",
                                        dropTargetIndex === index && "ring-2 ring-primary ring-offset-2 scale-105",
                                        "border-border"
                                    )}
                                >
                                    <Image
                                        src={img.preview}
                                        alt={`Photo ${index + 1}`}
                                        fill
                                        unoptimized
                                        sizes="(max-width: 640px) 33vw, (max-width: 768px) 25vw, 20vw"
                                        className="object-cover pointer-events-none"
                                    />

                                    {/* Mobile Always-Visible Remove Button / Desktop Hover Overlay */}
                                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-black/30 opacity-100 sm:opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 transition-opacity flex flex-col justify-between p-2 pointer-events-auto">
                                        <div className="flex justify-end">
                                            <button
                                                type="button"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (window.confirm("Remove this photo?")) {
                                                        onRemove(img.id ?? index);
                                                    }
                                                }}
                                                aria-label={getRemovePhotoAriaLabel(index, images.length)}
                                                className="p-1.5 bg-black/70 text-white rounded-full hover:bg-red-600 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white touch-manipulation min-h-[32px] min-w-[32px] flex items-center justify-center cursor-pointer shadow-sm"
                                            >
                                                <X className="w-3.5 h-3.5" />
                                            </button>
                                        </div>
                                        {onSetMain && index !== 0 && (
                                            <button
                                                type="button"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    onSetMain(index);
                                                }}
                                                className="w-full py-1.5 text-2xs font-bold text-white bg-black/70 rounded-md backdrop-blur-sm hover:bg-primary transition-colors uppercase tracking-widest focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white touch-manipulation cursor-pointer"
                                            >
                                                Make Cover
                                            </button>
                                        )}
                                    </div>

                                    {index === 0 && (
                                        <div className="absolute bottom-0 left-0 right-0 bg-primary/95 py-1 text-center text-2xs font-bold text-white uppercase tracking-widest pointer-events-none shadow-sm backdrop-blur-sm">
                                            {firstImageBadgeLabel}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    )}
                </Stack>
            </div>

            {(error || helperText) && (
                <div className="mt-1.5">
                    {error ? (
                        <div className="flex items-center gap-1.5 text-destructive text-xs font-medium">
                            <AlertCircle className="w-3.5 h-3.5" />
                            <span>{error}</span>
                        </div>
                    ) : (
                        <p className="text-muted-foreground text-xs">{helperText}</p>
                    )}
                </div>
            )}
        </Stack>
    );
}

import React from "react";
import type { UseFormReturn } from "react-hook-form";
import { useGenericListingForm } from "@/components/user/shared/useGenericListingForm";
import { useListingSubmission } from "@/hooks/listings/useListingSubmission";
import {
    createServiceListing,
    updateServiceListing,
    createSparePartListing,
    updateSparePartListing,
} from "@/lib/api/user/listings/postingAPI";
import {
    ServiceListingPayloadSchema,
} from "@/schemas/serviceListingPayload.schema";
import {
    EditPostSparePartFormSchema,
} from "@/schemas/postSparePartForm.schema";
import {
    buildServiceListingEditValues,
    buildSparePartListingEditValues,
    resolveServiceTypeSelectionIds,
} from "@/lib/listings/postingFormNormalization";
import type { ListingFormConfig } from "./listingFormConfig";
import { LISTING_TYPE } from "@esparex/contracts";
import type { ServiceType } from "@/lib/api/user/masterData";

const ServiceListingEditSchema = ServiceListingPayloadSchema.partial({
    categoryId: true,
    brandId: true,
    modelId: true,
    serviceTypeIds: true,
});

interface UseListingFormOrchestrationProps {
    config: ListingFormConfig;
    form: UseFormReturn<any>;
    editId?: string;
    loadBrandsForCategory: (categoryId: string) => Promise<void>;
    loadCatalogItems: (categoryId: string) => Promise<any>;
    onSubmitted: () => void;
}

export function useListingFormOrchestration({
    config,
    form,
    editId,
    loadBrandsForCategory,
    loadCatalogItems,
    onSubmitted,
}: UseListingFormOrchestrationProps) {
    const isEditMode = Boolean(editId);
    const { setValue } = form;

    const onDataLoaded = React.useCallback(async (payload: Record<string, unknown>) => {
        if (config.listingType === LISTING_TYPE.SERVICE) {
            const normalizedValues = buildServiceListingEditValues(payload);
            form.reset(normalizedValues);

            if (normalizedValues.categoryId) {
                const [, serviceTypes] = await Promise.all([
                    loadBrandsForCategory(normalizedValues.categoryId),
                    loadCatalogItems(normalizedValues.categoryId) as Promise<ServiceType[]>,
                ]);
                const resolvedIds = resolveServiceTypeSelectionIds(
                    normalizedValues.serviceTypeIds ?? [],
                    serviceTypes
                );
                if (resolvedIds.length > 0) {
                    setValue("serviceTypeIds", resolvedIds, { shouldValidate: true });
                }
            }
        } else {
            const normalizedValues = buildSparePartListingEditValues(payload);
            form.reset(normalizedValues);
            const categoryId = normalizedValues.categoryId || "";
            if (categoryId) {
                await Promise.all([
                    loadBrandsForCategory(categoryId),
                    loadCatalogItems(categoryId),
                ]);
            }
        }
    }, [config.listingType, form, loadBrandsForCategory, loadCatalogItems, setValue]);

    const { images, setImages, addImages, removeImage, isFetchingData, businessData } = useGenericListingForm({
        form,
        editId,
        onDataLoaded,
    });

    const submitFn = React.useCallback(async (payload: any, options?: { idempotencyKey?: string }) => {
        if (config.listingType === LISTING_TYPE.SERVICE) {
            if (isEditMode && editId) {
                return updateServiceListing(editId, {
                    title: payload.title,
                    description: payload.description,
                    images: payload.images,
                    serviceTypeIds: payload.serviceTypeIds,
                    priceMin: payload.price,
                });
            }
            const { price, ...rest } = payload;
            return createServiceListing({ ...rest, priceMin: price }, { idempotencyKey: options?.idempotencyKey });
        } else {
            if (isEditMode && editId) {
                return updateSparePartListing(editId, {
                    title: payload.title,
                    description: payload.description,
                    price: payload.price,
                    images: payload.images ?? [],
                });
            }
            return createSparePartListing({
                title: payload.title,
                categoryId: payload.categoryId,
                brandId: payload.brandId || undefined,
                sparePartId: payload.sparePartTypeId,
                price: payload.price,
                description: payload.description,
                images: payload.images ?? [],
            });
        }
    }, [config.listingType, editId, isEditMode]);

    const activePartialSchema = config.listingType === LISTING_TYPE.SERVICE 
        ? ServiceListingEditSchema 
        : EditPostSparePartFormSchema;

    const { onValidSubmit, isSubmitting } = useListingSubmission({
        form,
        listingImages: images,
        isEditMode,
        editId,
        schema: config.schema,
        partialSchema: activePartialSchema,
        submitFn,
        onSuccess: onSubmitted,
    });

    return {
        images,
        setImages,
        addImages,
        removeImage,
        isFetchingData,
        businessData,
        onValidSubmit,
        isSubmitting,
    };
}

