/* eslint-disable react-hooks/preserve-manual-memoization */
"use client";

const SEARCH_DEBOUNCE_MS = 350;

import { startTransition, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";

import type { Category } from "@/lib/api/user/categories";
import { useLocationData, type LocationData } from "@/context/LocationContext";
import { sanitizeLocationLabel } from "@/lib/location/locationLabels";
import { shouldApplyLocationFilter } from "@/lib/location/queryMode";
import type { SortOption } from "@/components/search/SearchResultsHeader";
import {
  buildPublicBrowseRoute,
  parsePublicBrowseParams,
  resolvePublicBrowseCategory,
  type PublicBrowseType,
} from "@/lib/publicBrowseRoutes";
import { usePersistedBrowseView } from "@/components/user/browseViewPreference";
import { useBrowseAdsData } from "@/components/user/useBrowseAdsData";
import { useBrowseFilterPipeline } from "@/components/user/useBrowseFilterPipeline";

type BrowsePageResult<T> = {
  data: T[];
  pagination: {
    total?: number;
    hasMore?: boolean;
  };
};

interface BrowseListingsControllerConfig<TItem, TFilters> {
  browseType: PublicBrowseType;
  initialCategory?: string;
  initialSearchQuery?: string;
  initialResults?: BrowsePageResult<TItem>;
  initialCategories?: Category[];
  pageSize?: number;
  logScope: string;
  loadErrorMessage?: string;
  buildFilters: (args: {
    page: number;
    pageSize: number;
    query: string;
    selectedCategory: string;
    categories: Category[];
    location: LocationData;
    sort: SortOption;
    urlLocationId?: string;
    urlLocationLabel?: string;
    radiusKm?: number;
  }) => TFilters;
  fetchPage: (filters: TFilters) => Promise<BrowsePageResult<TItem>>;
}

export function useBrowseListingsController<TItem, TFilters>({
  browseType,
  initialCategory,
  initialSearchQuery = "",
  initialResults,
  initialCategories,
  pageSize = 20,
  logScope,
  loadErrorMessage = "Failed to load results. Please try again.",
  buildFilters,
  fetchPage,
}: BrowseListingsControllerConfig<TItem, TFilters>) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { location, isLoaded } = useLocationData();
  const routeParams = parsePublicBrowseParams(searchParams);
  const routeCategory = resolvePublicBrowseCategory(routeParams) ?? "";

  const initialSelectedCategory = routeCategory || initialCategory || "";
  const initialSort = (routeParams.sort as SortOption | undefined) ?? "newest";
  const initialPage = routeParams.page && routeParams.page > 0 ? routeParams.page : 1;

  const [query, setQuery] = useState(routeParams.q ?? initialSearchQuery);
  const [inputValue, setInputValue] = useState(routeParams.q ?? initialSearchQuery);
  const [selectedCategory, setSelectedCategory] = useState<string>(initialSelectedCategory);
  const [sort, setSort] = useState<SortOption>(initialSort);
  const [view, setView] = usePersistedBrowseView("grid");
  const [page, setPage] = useState(initialPage);

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const skippedInitialFetchRef = useRef(false);
  const urlLocationId = routeParams.locationId ?? "";
  const urlLocationLabel = sanitizeLocationLabel(routeParams.location) ?? "";
  const urlRadiusKm = routeParams.radiusKm;
  const stableLocation = location;

  const constructFilters = useCallback(
    (requestedPage: number) =>
      buildFilters({
        page: requestedPage,
        pageSize,
        query,
        selectedCategory,
        categories: [],
        location: stableLocation,
        sort,
        urlLocationId: urlLocationId || undefined,
        urlLocationLabel: urlLocationLabel || undefined,
        radiusKm: urlRadiusKm,
      }),
    [buildFilters, pageSize, query, selectedCategory, sort, stableLocation, urlLocationId, urlLocationLabel, urlRadiusKm]
  );

  const {
    items,
    total,
    hasMore,
    loading,
    setLoading,
    error,
    categories,
    loadPageData,
  } = useBrowseAdsData<TItem, TFilters>({
    initialResults,
    initialCategories,
    logScope,
    loadErrorMessage,
    buildFilters: constructFilters,
    fetchPage,
  });

  useEffect(() => {
    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
  }, []);

  const hasLocationFilter = useMemo(() => {
    return shouldApplyLocationFilter(stableLocation, urlLocationId);
  }, [stableLocation, urlLocationId]);

  const shouldUseInitialResults = useMemo(
    () =>
      Boolean(initialResults) &&
      page === 1 &&
      query.trim() === initialSearchQuery.trim() &&
      selectedCategory === (initialCategory ?? "") &&
      sort === "newest" &&
      !hasLocationFilter,
    [
      hasLocationFilter,
      initialCategory,
      initialResults,
      initialSearchQuery,
      page,
      query,
      selectedCategory,
      sort,
    ]
  );

  const fetchItems = useCallback(
    async (requestedPage: number) => {
      await loadPageData(requestedPage);
    },
    [loadPageData]
  );

  useEffect(() => {
    if (!isLoaded) return;
    if (!skippedInitialFetchRef.current && shouldUseInitialResults) {
      skippedInitialFetchRef.current = true;
      setLoading(false);
      return;
    }
    setPage(1);
    void fetchItems(1);
  }, [fetchItems, isLoaded, shouldUseInitialResults]);

  const {
    activeFilterBadges,
    activeFilterCount,
  } = useBrowseFilterPipeline({
    query,
    selectedCategory,
    categories,
    location: stableLocation,
    sort,
    urlLocationId,
    urlLocationLabel,
    urlRadiusKm,
  });

  const buildNextUrl = useCallback(
    (
      overrides: Partial<{
        q: string;
        category: string;
        sort: SortOption;
      }> = {}
    ) => {
      const hasOverride = (key: keyof typeof overrides) =>
        Object.prototype.hasOwnProperty.call(overrides, key);

      return buildPublicBrowseRoute({
        type: browseType,
        q: hasOverride("q") ? overrides.q : query,
        category: hasOverride("category") ? overrides.category : selectedCategory,
        sort: hasOverride("sort") ? overrides.sort : sort,
        locationId: urlLocationId || undefined,
        location: urlLocationId ? urlLocationLabel || undefined : undefined,
        radiusKm: urlRadiusKm,
      });
    },
    [browseType, query, selectedCategory, sort, urlLocationId, urlLocationLabel, urlRadiusKm]
  );


  const handleInputChange = useCallback(
    (value: string) => {
      setInputValue(value);
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
      debounceRef.current = setTimeout(() => {
        setQuery(value);
        void router.push(buildNextUrl({ q: value }), { scroll: false });
      }, SEARCH_DEBOUNCE_MS);
    },
    [buildNextUrl, router]
  );


  const handleCategoryChange = useCallback(
    (value: string) => {
      startTransition(() => {
        setSelectedCategory(value);
        setPage(1);
        void router.push(buildNextUrl({ category: value }), { scroll: false });
      });
    },
    [buildNextUrl, router]
  );


  const handleSortChange = useCallback(
    (value: SortOption) => {
      startTransition(() => {
        setSort(value);
        setPage(1);
        void router.push(buildNextUrl({ sort: value }), { scroll: false });
      });
    },
    [buildNextUrl, router]
  );


  const handleReset = useCallback(() => {
    startTransition(() => {
      setQuery("");
      setInputValue("");
      setSelectedCategory("");
      setSort("newest");
      setPage(1);
      void router.push(buildPublicBrowseRoute({ type: browseType }), { scroll: false });
    });
  }, [browseType, router]);


  const handleLoadMore = useCallback(() => {
    const nextPage = page + 1;
    startTransition(() => {
      setPage(nextPage);
      void fetchItems(nextPage);
    });
  }, [fetchItems, page]);

  const handleRetry = useCallback(() => {
    void fetchItems(1);
  }, [fetchItems]);

  return {
    query,
    inputValue,
    selectedCategory,
    sort,
    view,
    loading,
    error,
    hasMore,
    total,
    categories,
    items,
    activeFilterCount,
    activeFilterBadges,
    setSelectedCategory,
    handleCategoryChange,
    handleSortChange,
    setView,
    handleInputChange,
    handleReset,
    handleLoadMore,
    handleRetry,
  };
}

"use client";

import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useMemo,
  ReactNode,
  useRef,
} from "react";

import { useRouter } from "next/navigation";
import type { User } from "@/types/User";

import { normalizeError } from "@/lib/api/normalizeError";
import { authApi } from "@/lib/api/auth";
import logger from "@/lib/logger";

import {
  AUTH_SESSION_STORAGE_KEY,
  isValidUser,
  isBenignLogoutError,
  replaceToHomeSafely,
} from "./auth/authHelpers";
import { useBackendReadyPoller } from "./auth/useBackendReadyPoller";

/* -------------------------------------------------------------------------- */
/* Types                                                                      */
/* -------------------------------------------------------------------------- */

export type AuthStatus =
  | "loading"
  | "unauthenticated"
  | "authenticated";

export interface AuthStatusContextType {
  status: AuthStatus;
  isAuthResolved: boolean;
  error: Error | null;
  refreshUser: () => Promise<void>;
  logout: (options?: { skipServerLogout?: boolean }) => Promise<void>;
}

export interface AuthUserContextType {
  user: User | null;
  updateUser: (user: User) => void;
}

export interface AuthContextType extends AuthStatusContextType, AuthUserContextType {}

interface BackendReadyContextType {
  backendReady: boolean;
}

/* -------------------------------------------------------------------------- */
/* Contexts                                                                   */
/* -------------------------------------------------------------------------- */

const AuthContext =
  createContext<AuthContextType | undefined>(undefined);

const AuthStatusContext =
  createContext<AuthStatusContextType | undefined>(undefined);

const AuthUserContext =
  createContext<AuthUserContextType | undefined>(undefined);

const BackendReadyContext =
  createContext<BackendReadyContextType | undefined>(undefined);

/* -------------------------------------------------------------------------- */
/* Provider                                                                   */
/* -------------------------------------------------------------------------- */

export function AuthProvider({
  children,
  initialHasAuthCookie = false,
}: {
  children: ReactNode;
  initialHasAuthCookie?: boolean;
}) {
  const router = useRouter();
  const routerRef = useRef(router);
  useEffect(() => {
    routerRef.current = router;
  }, [router]);

  const [user, setUser] = useState<User | null>(null);
  const [error, setError] = useState<Error | null>(null);

  const { backendReady, setBackendReady, hasAuthHint, setHasAuthHint } =
    useBackendReadyPoller(initialHasAuthCookie);

  const [status, setStatus] = useState<AuthStatus>(
    initialHasAuthCookie ? "loading" : "unauthenticated"
  );

  const fetchingRef = useRef(false);
  const authBannerShownRef = useRef(false);
  const wasAuthenticatedRef = useRef(false);
  const staleSessionCleanupRef = useRef(false);
  const networkRetryTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const networkRetryCountRef = useRef(0);

  /* ------------------------------------------------------------------------ */
  /* Fetch User                                                               */
  /* ------------------------------------------------------------------------ */

  const fetchUser = useCallback(async function doFetch(): Promise<void> {
    /* ---------------- Dev Bypass ---------------- */

    if (!backendReady) {
      if (
        process.env.NEXT_PUBLIC_LOCAL_DEV_AUTH === "true" &&
        process.env.NODE_ENV !== "production"
      ) {
        logger.warn("⚠️ LOCAL DEV AUTH ENABLED — DO NOT DEPLOY");

        const devUser: User = {
          id: "local-dev-user",
          name: "Local Dev User",
          email: "dev@localhost",
          mobile: "9999999999",
          role: "user",
          isPhoneVerified: true,
          businessStatus: "pending",
          createdAt: new Date().toISOString(),
        };

        setUser(devUser);
        setStatus("authenticated");
        setBackendReady(true);
        setError(null);

        return;
      }

      setStatus("loading");
      return;
    }

    /* ---------------- Idempotency ---------------- */

    if (fetchingRef.current) return;
    fetchingRef.current = true;
    if (!user) {
      setStatus("loading");
    }

    try {
      const response = await authApi.me({ silent: true });
      const rawUser = response.user;

      if (isValidUser(rawUser)) {
        setUser(rawUser);
        setStatus("authenticated");
        setError(null);
        setHasAuthHint(true);
        if (typeof window !== "undefined") {
          localStorage.setItem(AUTH_SESSION_STORAGE_KEY, "1");
        }
        authBannerShownRef.current = false;
        wasAuthenticatedRef.current = true;
        staleSessionCleanupRef.current = false;
      } else {
        setUser(null);
        setStatus("unauthenticated");
        setHasAuthHint(false);
      }
    } catch (rawError: unknown) {
      const err = normalizeError(rawError);

      if (
        err.response?.status === 401 ||
        err.response?.status === 403
      ) {
        if (!staleSessionCleanupRef.current) {
          staleSessionCleanupRef.current = true;
          try {
            await authApi.logout();
          } catch {
            // Ignore cleanup failures
          }
        }

        if (typeof window !== "undefined") {
          localStorage.removeItem(AUTH_SESSION_STORAGE_KEY);
        }

        setUser(null);
        setStatus("unauthenticated");
        setError(null);
        setHasAuthHint(false);
        const hadActiveSession = wasAuthenticatedRef.current;
        wasAuthenticatedRef.current = false;
        if (hadActiveSession && !authBannerShownRef.current) {
          authBannerShownRef.current = true;
          replaceToHomeSafely(routerRef.current);
        }

        return;
      }

      if (!err.response) {
        const MAX_NETWORK_RETRIES = 3;
        if (networkRetryCountRef.current < MAX_NETWORK_RETRIES) {
          networkRetryCountRef.current += 1;
          const delay = networkRetryCountRef.current * 5_000;
          if (process.env.NODE_ENV === "development") {
            logger.warn(`[Auth] Network error — retrying in ${delay / 1000}s (attempt ${networkRetryCountRef.current}/${MAX_NETWORK_RETRIES})`);
          }
          networkRetryTimerRef.current = setTimeout(() => {
            fetchingRef.current = false;
            void doFetch();
          }, delay);
          return;
        }
        networkRetryCountRef.current = 0;
        setUser(null);
        setStatus("unauthenticated");
        return;
      }

      if (
        err.isExpected ||
        err.response?.status === 429
      ) {
        setUser(null);
        setStatus("unauthenticated");
        setError(null);

        return;
      }

      if (process.env.NODE_ENV === "development") {
        logger.error("[Auth] Fetch failed:", err.message);
      }

      setError(
        new Error(
          err.message || "Authentication failed"
        )
      );

      setUser(null);
      setStatus("unauthenticated");
      setHasAuthHint(false);
    } finally {
      fetchingRef.current = false;
    }
  }, [backendReady, setBackendReady, setHasAuthHint]);

  /* ------------------------------------------------------------------------ */
  /* Session Sync                                                             */
  /* ------------------------------------------------------------------------ */

  useEffect(() => {
    if (!backendReady) return;

    const pathname = window.location.pathname;

    if (pathname.startsWith("/admin")) {
      setTimeout(() => {
        setStatus((prev) =>
          prev === "loading" ? "unauthenticated" : prev
        );
      }, 0);
      return;
    }

    const handleAuthUpdate = () => {
      if (!pathname.startsWith("/admin")) {
        fetchUser();
      }
    };

    if (!hasAuthHint) {
      setUser(null);
      setStatus("unauthenticated");
      setError(null);
      return;
    }

    fetchUser();

    window.addEventListener(
      "esparex_auth_update",
      handleAuthUpdate
    );

    return () => {
      window.removeEventListener(
        "esparex_auth_update",
        handleAuthUpdate
      );
    };
  }, [backendReady, fetchUser, hasAuthHint]);

  /* ------------------------------------------------------------------------ */
  /* Manual Update                                                            */
  /* ------------------------------------------------------------------------ */

  const updateUser = useCallback(
    (newUser: User) => {
      if (!isValidUser(newUser)) {
        logger.error(
          "[Auth] Invalid user payload:",
          newUser
        );
        return;
      }

      setUser(newUser);
      setStatus("authenticated");
      setError(null);
      setHasAuthHint(true);
      if (typeof window !== "undefined") {
        localStorage.setItem(AUTH_SESSION_STORAGE_KEY, "1");
      }
      wasAuthenticatedRef.current = true;
    },
    [setHasAuthHint]
  );

  /* ------------------------------------------------------------------------ */
  /* Logout                                                                   */
  /* ------------------------------------------------------------------------ */

  const logout = useCallback(async (options?: { skipServerLogout?: boolean }) => {
    if (networkRetryTimerRef.current) {
      clearTimeout(networkRetryTimerRef.current);
      networkRetryTimerRef.current = null;
    }
    networkRetryCountRef.current = 0;
    try {
      if (!options?.skipServerLogout) {
        await authApi.logout();
      }
    } catch (error) {
      if (isBenignLogoutError(error)) {
        logger.info("[Auth] Logout skipped: session already cleared.");
      } else {
        logger.error("[Auth] Logout failed:", error);
      }
    } finally {
      if (typeof window !== "undefined") {
        localStorage.removeItem(AUTH_SESSION_STORAGE_KEY);
        localStorage.removeItem("esparex_fcm_token");
        localStorage.removeItem("esparex_fcm_registration_v1");
      }
      setUser(null);
      setStatus("unauthenticated");
      setError(null);
      setHasAuthHint(false);
      wasAuthenticatedRef.current = false;
      authBannerShownRef.current = false;
      staleSessionCleanupRef.current = false;
    }
  }, [setHasAuthHint]);

  /* ------------------------------------------------------------------------ */
  /* Provider Values                                                          */
  /* ------------------------------------------------------------------------ */

  const statusValue = useMemo<AuthStatusContextType>(
    () => ({
      status,
      isAuthResolved: status !== "loading",
      error,
      refreshUser: fetchUser,
      logout,
    }),
    [error, fetchUser, logout, status]
  );

  const userValue = useMemo<AuthUserContextType>(
    () => ({
      user,
      updateUser,
    }),
    [user, updateUser]
  );

  const combinedValue = useMemo<AuthContextType>(
    () => ({
      user,
      status,
      isAuthResolved: status !== "loading",
      error,
      refreshUser: fetchUser,
      updateUser,
      logout,
    }),
    [error, fetchUser, logout, status, updateUser, user]
  );

  const backendReadyValue = useMemo(
    () => ({ backendReady }),
    [backendReady]
  );

  return (
    <BackendReadyContext.Provider value={backendReadyValue}>
      <AuthStatusContext.Provider value={statusValue}>
        <AuthUserContext.Provider value={userValue}>
          <AuthContext.Provider value={combinedValue}>
            {children}
          </AuthContext.Provider>
        </AuthUserContext.Provider>
      </AuthStatusContext.Provider>
    </BackendReadyContext.Provider>
  );
}

/* -------------------------------------------------------------------------- */
/* Hooks                                                                      */
/* -------------------------------------------------------------------------- */

export function useAuthStatus(): AuthStatusContextType {
  const ctx = useContext(AuthStatusContext);
  if (!ctx) throw new Error("useAuthStatus must be used within AuthProvider");
  return ctx;
}

export function useAuthUser(): AuthUserContextType {
  const ctx = useContext(AuthUserContext);
  if (!ctx) throw new Error("useAuthUser must be used within AuthProvider");
  return ctx;
}

export function useAuth(): AuthContextType {
  const ctx = useContext(AuthContext);

  if (!ctx) {
    throw new Error(
      "useAuth must be used within AuthProvider"
    );
  }

  return ctx;
}

export function useBackendReady(): boolean {
  const ctx = useContext(BackendReadyContext);
  if (!ctx) throw new Error("useBackendReady must be used within AuthProvider");
  return ctx.backendReady;
}

