"use client";

import { useState, useEffect } from "react";
import { apiClient } from "@/lib/api/client";
import { AUTH_SESSION_STORAGE_KEY } from "./authHelpers";

export function useBackendReadyPoller(initialHasAuthCookie = false) {
  const [backendReady, setBackendReady] = useState(false);
  const [hasAuthHint, setHasAuthHint] = useState(initialHasAuthCookie);

  useEffect(() => {
    if (initialHasAuthCookie || typeof window === "undefined") return;

    if (localStorage.getItem(AUTH_SESSION_STORAGE_KEY) === "1") {
      setHasAuthHint(true);
    }
  }, [initialHasAuthCookie]);

  useEffect(() => {
    let mounted = true;

    if (
      process.env.NEXT_PUBLIC_LOCAL_DEV_AUTH === "true" &&
      process.env.NODE_ENV !== "production"
    ) {
      setBackendReady(true);
      return;
    }

    const BASE_DELAY_MS = 2_000;
    const MAX_DELAY_MS = 30_000;
    let retryAttempt = 0;

    const waitForBackend = async () => {
      try {
        const ok = await apiClient.checkHealth();

        if (mounted && ok) {
          retryAttempt = 0;
          setBackendReady(true);
        } else if (mounted) {
          const jitter = Math.random() * 1_000;
          const delay =
            Math.min(BASE_DELAY_MS * Math.pow(2, retryAttempt), MAX_DELAY_MS) +
            jitter;
          retryAttempt += 1;
          setTimeout(waitForBackend, delay);
        }
      } catch {
        if (mounted) {
          const jitter = Math.random() * 1_000;
          const delay =
            Math.min(BASE_DELAY_MS * Math.pow(2, retryAttempt), MAX_DELAY_MS) +
            jitter;
          retryAttempt += 1;
          setTimeout(waitForBackend, delay);
        }
      }
    };

    waitForBackend();

    return () => {
      mounted = false;
    };
  }, []);

  return { backendReady, setBackendReady, hasAuthHint, setHasAuthHint };
}

"use client";

import { getCategoryIcon } from "@/utils/getCategoryIcon";
import type { ScreenSize } from "@/lib/api/user/masterData";
import type { Category } from "@/lib/api/user/categories";
import type { ListingCategory } from "@/types/listing";
import { LISTING_TYPE, ListingTypeValue } from "@esparex/contracts";
import type { CategoryFilter } from "@esparex/contracts";

export interface CategorySchemaType {
    categoryId: string;
    categoryName: string;
    filters: CategoryFilter[];
}

const screenSizeSortValue = (raw: string): number => {
    const numeric = Number(raw.replace(/[^\d.]/g, ""));
    return Number.isFinite(numeric) ? numeric : Number.POSITIVE_INFINITY;
};

export const normalizeScreenSizeOptions = (sizes: ScreenSize[]): string[] => {
    const seen = new Set<string>();
    return sizes
        .map((item) => (item.size || item.name || "").trim())
        .filter((value) => value.length > 0)
        .filter((value) => {
            const key = value.toLowerCase();
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
        })
        .sort((a, b) => screenSizeSortValue(a) - screenSizeSortValue(b));
};

export const buildDynamicCategories = (
    categories: Category[],
    listingType: ListingTypeValue
): ListingCategory[] => {
    return categories
        .filter((category) => {
            const types = category.listingType || [];
            return types.includes(listingType);
        })
        .map((category) => ({
            id: String(category.id || (category as any)._id || ""),
            name: category.name,
            slug: category.slug || "",
            icon: getCategoryIcon(category.icon || category.name || category.slug),
            hasScreenSizes: Boolean(category.hasScreenSizes),
            supportsSpareParts: Boolean(category.listingType?.includes(LISTING_TYPE.SPARE_PART)),
            listingType: category.listingType || [],
            serviceSelectionMode: category.serviceSelectionMode as "single" | "multi",
        }));
};

"use client";

import { useState, useCallback } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { queryKeys } from "@/hooks/queries/queryKeys";
import { FieldValues, Path, UseFormReturn } from "react-hook-form";
import { useNavigation } from "@/context/NavigationContext";
import logger from "@/lib/logger";
import { notify } from "@/lib/feedback";
import { popupBus } from "@/lib/popup";
import type { ListingImage } from "@/types/listing";
import type { ListingLocation } from "@/types/listing";
import { sanitizeMongoObjectId } from "@esparex/shared";
import { toCanonicalGeoPoint } from "@esparex/shared";
import { z } from "zod";
import { apiClient } from "@/lib/api/client";

import { generateIdempotencyKey } from "@/lib/listings/submissionUtils";
import { injectApiErrors } from "@/lib/injectApiErrors";
import { mapErrorToMessage } from "@/lib/errorMapper";

function getBackendErrorCode(error: unknown): string | undefined {
    if (!error || typeof error !== "object") return undefined;

    const record = error as {
        code?: unknown;
        context?: { backendErrorCode?: unknown };
        response?: { data?: { code?: unknown } };
    };

    if (typeof record.code === "string" && record.code.trim().length > 0) {
        return record.code;
    }

    if (typeof record.context?.backendErrorCode === "string" && record.context.backendErrorCode.trim().length > 0) {
        return record.context.backendErrorCode;
    }

    const responseCode = record.response?.data?.code;
    return typeof responseCode === "string" && responseCode.trim().length > 0 ? responseCode : undefined;
}

interface UseListingSubmissionProps<TFieldValues extends FieldValues, TResult = unknown> {
    form: UseFormReturn<TFieldValues>;
    listingImages: ListingImage[];
    isEditMode: boolean;
    editId?: string;
    schema: z.ZodTypeAny;
    partialSchema?: z.ZodTypeAny;
    submitFn: (payload: TFieldValues, options?: { idempotencyKey?: string }) => Promise<TResult>;
    onSuccess?: (result: TResult) => void;
    onError?: (error: string) => void;
}

type ListingSubmissionValues = FieldValues & {
    location?: Partial<ListingLocation>;
    images?: string[];
    category?: string;
    brand?: string;
    model?: string;
};

/**
 * 🚀 Unified Submission Hook for Listings
 * Handles validation, image uploads, and API calls.
 */
export function useListingSubmission<T extends ListingSubmissionValues, R = unknown>({
    form,
    listingImages,
    isEditMode,
    editId: _editId,
    schema,
    partialSchema,
    submitFn,
    onSuccess,
    onError,
}: UseListingSubmissionProps<T, R>) {
    const queryClient = useQueryClient();
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [idempotencyKey, setIdempotencyKey] = useState(generateIdempotencyKey);
    const { setIsDirty } = useNavigation();

    const resetIdempotency = useCallback(() => setIdempotencyKey(generateIdempotencyKey()), []);

    const onValidSubmit = useCallback(async (data: T, overrideImages?: ListingImage[]) => {
        setIsSubmitting(true);
        if (onError) onError("");

        const imagesToProcess = overrideImages || listingImages;

        try {
            if (imagesToProcess.length === 0) {
                form.setError("images" as Path<T>, {
                    type: "manual",
                    message: "Add at least one photo to continue.",
                });
                if (typeof document !== "undefined") {
                    document.querySelector("input[type='file']")?.scrollIntoView({ behavior: "smooth", block: "center" });
                }
                return null;
            }
            form.clearErrors("images" as Path<T>);

            // 1. Image Upload Pipeline (Parallel S3 Pre-upload)
            const csrfToken = (await apiClient.getCsrfToken()) || "";
            const headers = { "x-csrf-token": csrfToken };

            const finalImageUrls: string[] = await Promise.all(
                imagesToProcess.map(async (img, idx) => {
                    if (!img) return "";
                    if (img.isRemote) return img.preview;
                    if (typeof img.preview === 'string' && img.preview.startsWith('http')) return img.preview;
                    if (!img.file) return "";

                    const formData = new FormData();
                    formData.append("image", img.file);
                    formData.append("folder", "ads");

                    const response = await fetch("/api/upload/ad-image", {
                        method: "POST",
                        headers,
                        body: formData,
                        credentials: "include",
                    });
                    const payload = await response.json().catch(() => ({} as { success?: boolean; url?: string; error?: string }));
                    const remoteUrl = typeof payload?.url === "string" ? payload.url : "";

                    if (!response.ok || !remoteUrl) {
                        throw new Error(payload?.error || `Failed to upload image ${idx + 1}. Please try again.`);
                    }

                    return remoteUrl;
                })
            ).then((urls) => urls.filter((url): url is string => Boolean(url)));

            // 2. Payload Construction
            const location = data.location;
            const canonicalLocation = location ? {
                city: location.city || "",
                state: location.state || "",
                coordinates: toCanonicalGeoPoint(location.coordinates),
                locationId: sanitizeMongoObjectId(location.locationId) || undefined,
            } : undefined;

            const finalPayload = {
                ...data,
                images: finalImageUrls,
                location: canonicalLocation,
                // Remove UI-only fields if they exist
                category: undefined,
                brand: undefined,
                model: undefined,
            };

            // 3. Validation Check
            const activeSchema = (isEditMode && partialSchema) ? partialSchema : schema;
            const validation = activeSchema.safeParse(finalPayload);

            if (!validation.success) {
                const { issues } = validation.error;
                const [firstIssue] = issues;

                issues.forEach((issue: z.ZodIssue) => {
                    const fieldPath = issue.path
                        .filter((segment): segment is string | number => typeof segment === "string" || typeof segment === "number")
                        .join(".");

                    if (fieldPath) {
                        form.setError(fieldPath as Path<T>, {
                            type: "manual",
                            message: issue.message,
                        });
                    }
                });

                const firstPath = firstIssue?.path
                    .filter((segment): segment is string | number => typeof segment === "string" || typeof segment === "number")
                    .join(".");

                if (typeof document !== "undefined") {
                    if (firstPath === "images") {
                        document.querySelector("input[type='file']")?.scrollIntoView({ behavior: "smooth", block: "center" });
                    } else if (firstPath) {
                        const el = document.querySelector(`[name='${firstPath}']`);
                        if (el) el.scrollIntoView({ behavior: "smooth", block: "center" });
                    }
                }

                return null;
            }

            // 4. API Submission
            const result = await submitFn(finalPayload, { 
                idempotencyKey: isEditMode ? undefined : idempotencyKey 
            });

            if (!result) throw new Error("Submission failed. No result returned.");

            setIsDirty(false);
            void queryClient.invalidateQueries({ queryKey: queryKeys.listings.all });
            onSuccess?.(result);
            return result;

        } catch (e: unknown) {
            logger.error("[Submission] Failed:", e);

            // 🛡️ Policy Guard: Intercept Business Required Threshold & Quota Exhaustion
            const backendErrorCode = getBackendErrorCode(e);
            if (backendErrorCode === 'BUSINESS_REQUIRED_THRESHOLD') {
                const limitMsg = mapErrorToMessage(e, "Business account required.");
                notify.error(limitMsg, {
                    duration: 6000,
                    description: "Please upgrade to a Business account or purchase a premium slot to post more spare parts."
                });
                return null;
            } else if (backendErrorCode === 'QUOTA_EXHAUSTED') {
                const quotaMsg = mapErrorToMessage(e, "Monthly posting limit reached.");
                notify.error(quotaMsg, {
                    duration: 6000,
                    description: "Buy an Ad Pack credit to continue posting or wait until your monthly limit resets."
                });
                return null;
            } else if (backendErrorCode === 'DUPLICATE_AD') {
                const record = e as {
                    details?: { matchedAdId?: string };
                    context?: { details?: { matchedAdId?: string } };
                    response?: { data?: { details?: { matchedAdId?: string } } };
                };
                const matchedAdId = record.details?.matchedAdId || record.context?.details?.matchedAdId || record.response?.data?.details?.matchedAdId;

                popupBus.show({
                    type: "warning",
                    title: "Duplicate Ad",
                    message: "This ad is already listed.",
                    code: "DUPLICATE_AD",
                    actions: [
                        ...(matchedAdId ? [{
                            label: "Edit Existing Listing",
                            action: () => {
                                if (typeof window !== "undefined") {
                                    window.location.href = `/post-ad?edit=${matchedAdId}`;
                                }
                            }
                        }] : []),
                        {
                            label: "View My Listings",
                            action: () => {
                                if (typeof window !== "undefined") {
                                    window.location.href = "/my-account/listings";
                                }
                            }
                        },
                        {
                            label: "Close"
                        }
                    ]
                }, { dedupeKey: "DUPLICATE_AD" });
                return null;
            }

            // Inject API field-level errors into the form (highlights specific fields)
            const injected = form ? injectApiErrors(form, e) : false;
            const msg = mapErrorToMessage(e, "Submission failed. Please try again.");

            if (!injected) {
                if (onError) onError(msg);
                else notify.error(msg);
            }
            resetIdempotency();
        } finally {
            setIsSubmitting(false);
        }
        return null;
    }, [
        form, listingImages, isEditMode, schema, partialSchema,
        submitFn, onSuccess, onError, idempotencyKey, resetIdempotency, setIsDirty
    ]);

    return {
        onValidSubmit,
        isSubmitting,
        idempotencyKey,
        resetIdempotency
    };
}

