"use client";

import { useEffect, useCallback } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { AdPayloadSchema as postAdSchema, PartialAdPayloadSchema as partialAdSchema, AdPayload as PostAdFormData } from "@/schemas/adPayload.schema";
import { Resolver } from "react-hook-form";

const DRAFT_KEY = "esparex_post_ad_draft";

export function usePostAdForm(isEditMode: boolean = false) {
    // Initialize Form
    const form = useForm<PostAdFormData>({
        resolver: zodResolver(isEditMode ? partialAdSchema : postAdSchema) as Resolver<PostAdFormData>,
        mode: "all",
        shouldFocusError: true,
        defaultValues: {
            category: "",
            categoryId: "",
            brand: "",
            brandId: "",
            model: "",
            modelId: "",
            screenSize: "",

            title: "",
            description: "",
            images: [],
            price: undefined as unknown as number,
            isFree: false,
            location: { city: "" } as PostAdFormData["location"],
            spareParts: [],
            deviceCondition: undefined,
        }
    });

    const { register, control, handleSubmit, watch, setValue, trigger, formState: { errors } } = form;

    // Load draft on mount
    useEffect(() => {
        if (isEditMode) return;
        try {
            const draft = localStorage.getItem(DRAFT_KEY);
            if (draft) {
                const parsed = JSON.parse(draft);
                // Keep defaultValues structure but apply draft
                form.reset((prev) => ({ ...prev, ...parsed }));
            }
        } catch (e) {
            console.error("Failed to parse post ad draft", e);
        }
    }, [isEditMode, form]);

    // Save draft on change
    useEffect(() => {
        if (isEditMode) return;
        const subscription = watch((value) => {
            try {
                localStorage.setItem(DRAFT_KEY, JSON.stringify(value));
            } catch (e) {
                console.error("Failed to save post ad draft", e);
            }
        });
        return () => subscription.unsubscribe();
    }, [isEditMode, watch]);

    const clearDraft = useCallback(() => {
        if (isEditMode) return;
        localStorage.removeItem(DRAFT_KEY);
    }, [isEditMode]);

    return {
        form,
        register,
        control,
        errors,
        watch,
        setValue,
        trigger,
        handleSubmit,
        clearDraft,
    };
}

"use client";

import { useEffect, useState, useCallback } from "react";
import type { PostingEntitlementMatrixDTO, SingleEntitlementState } from "@esparex/contracts";
import { apiClient } from "@/lib/api/client";
import { unwrapApiPayload } from "@/lib/api/result";

type ModuleType = "ads" | "services" | "spareParts" | "smartAlerts";

export function usePostingEntitlement(moduleType?: ModuleType) {
  const [matrix, setMatrix] = useState<PostingEntitlementMatrixDTO | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchEntitlements = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);
      const res = await apiClient.get<unknown>("entitlements/posting");
      const unwrapped = unwrapApiPayload<PostingEntitlementMatrixDTO>(res);
      if (unwrapped) {
        setMatrix(unwrapped);
      } else {
        setError("Failed to load posting entitlements");
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Error fetching entitlements";
      setError(msg);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    void fetchEntitlements();
  }, [fetchEntitlements]);

  const activeEntitlement: SingleEntitlementState | null =
    matrix && moduleType ? matrix[moduleType] : null;

  return {
    matrix,
    entitlement: activeEntitlement,
    isAllowed: activeEntitlement ? activeEntitlement.allowed : true,
    isLoading,
    error,
    refetch: fetchEntitlements,
  };
}

import { apiClient } from '@/lib/api/client';
import { toApiResult } from '@/lib/api/result';
import { API_ROUTES } from '../routes';

export interface AIInput {
    type: 'identify' | 'generate';
    image?: string; // Base64
    context?: Record<string, unknown>;
}

export interface AIOutput {
    brand?: string;
    model?: string;
    screenSize?: string;
    title?: string;
    description?: string;
    [key: string]: unknown;
}

export const generateAIContent = async (payload: AIInput): Promise<{ data: AIOutput | null; error: any }> => {
    return await toApiResult<AIOutput>(apiClient.post(API_ROUTES.USER.AI_GENERATE, payload));
};

export const checkAiStatus = async (): Promise<{ available: boolean; reason: string | null; retryAfter: number }> => {
    const { data } = await toApiResult<{ available: boolean; reason: string | null; retryAfter: number }>(
        apiClient.get('/user/ai/status', { silent: true })
    );
    return data || { available: false, reason: 'AI_UNAVAILABLE', retryAfter: 0 };
};

import { 
  normalizeBusinessStatus,
  isBusinessActiveStatus,
  normalizeAdStatus,
  normalizeServiceStatus,
} from "@esparex/shared";
import type { ServiceStatus, AdStatusValue as AdStatus } from "@esparex/contracts";

export type { ServiceStatus, AdStatus };
export type PartStatus = "pending" | "active" | "inactive" | "rejected" | "expired";
export type TransactionStatus = "INITIATED" | "SUCCESS" | "FAILED";

function normalizeLowercase(value: unknown): string {
  return typeof value === "string" ? value.trim().toLowerCase() : "";
}

export { 
  normalizeBusinessStatus,
  isBusinessActiveStatus,
  normalizeAdStatus,
  normalizeServiceStatus
};

export function normalizePartStatus(
  value: unknown,
  fallback: PartStatus = "pending"
): PartStatus | "live" {
  return normalizeAdStatus(value, fallback as any) as PartStatus | "live";
}

export function normalizePartCondition(
  value: unknown
): "new" | "used" | "refurbished" {
  const normalized = normalizeLowercase(value);
  if (normalized === "used") return "used";
  if (normalized === "refurbished") return "refurbished";
  return "new";
}

export function normalizeTransactionStatus(
  value: unknown,
  fallback: TransactionStatus = "INITIATED"
): TransactionStatus {
  const normalized = typeof value === "string" ? value.trim().toUpperCase() : "";
  if (normalized === "SUCCESS" || normalized === "COMPLETED") return "SUCCESS";
  if (normalized === "FAILED" || normalized === "ERROR") return "FAILED";
  if (normalized === "INITIATED" || normalized === "PENDING") return "INITIATED";
  return fallback;
}

import { Request, Response } from "express";
import mongoose from "mongoose";
import { NOTIFICATION_TYPE } from "@esparex/contracts";
import { NotificationIntent } from "@esparex/core/domain/NotificationIntent";
import {
    createNotificationLog,
    createScheduledNotification,
    getNotificationHistory,
    searchNotificationRecipients,
} from "@esparex/core/domains/notifications/application/AdminNotificationService";
import {
    getPaginationParams,
    sendAdminError,
    sendSuccessResponse,
} from '../../utils/adminBaseController';
import { logAdminAction } from "../../utils/adminLogger";
import { NotificationDispatcher } from "@esparex/core/services/notification/NotificationDispatcher";
import { createAdminNotificationTargetCursor } from "@esparex/core/services/notification/AdminNotificationTargetingService";
import { type IUser } from "@esparex/core/models/User";
import { respond } from "../../utils/respond";

const BATCH_SIZE = 500;

type AdminNotificationTargetType = "all" | "topic" | "users";

type HistoryRecord = {
    id: string;
    title: string;
    body: string;
    type: string;
    targetType: AdminNotificationTargetType;
    targetValue?: string;
    userIds?: Array<string | mongoose.Types.ObjectId>;
    actionUrl?: string;
    sentBy: mongoose.Types.ObjectId | Record<string, unknown> | null;
    successCount: number;
    skippedCount: number;
    failureCount: number;
    status: "sent" | "failed" | "scheduled";
    createdAt: Date;
    sendAt?: Date;
};

const escapeRegex = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

async function dispatchToAudience(params: {
    audienceId: string;
    title: string;
    body: string;
    targetType: AdminNotificationTargetType;
    targetValue?: string;
    userIds?: string[];
    actionUrl?: string;
    kind: string;
}) {
    const cursor = createAdminNotificationTargetCursor({
        targetType: params.targetType,
        targetValue: params.targetValue,
        userIds: params.userIds,
    });

    let successCount = 0;
    let skippedCount = 0;
    let failureCount = 0;
    let batch: NotificationIntent[] = [];

    for await (const user of cursor) {
        batch.push(
            NotificationIntent.fromAdminBroadcast(
                user._id.toString(),
                params.audienceId,
                params.title,
                params.body,
                params.kind,
                params.targetType,
                params.actionUrl
            )
        );

        if (batch.length >= BATCH_SIZE) {
            const result = await NotificationDispatcher.bulkDispatch(batch);
            successCount += result.successCount;
            skippedCount += result.skippedCount;
            failureCount += result.failureCount;
            batch = [];
        }
    }

    if (batch.length > 0) {
        const result = await NotificationDispatcher.bulkDispatch(batch);
        successCount += result.successCount;
        skippedCount += result.skippedCount;
        failureCount += result.failureCount;
    }

    return { successCount, skippedCount, failureCount };
}

export async function sendNotification(req: Request, res: Response) {
    try {
        const currentUser = req.user as unknown as IUser;
        const { title, body, targetType, targetValue, userIds, actionUrl, sendAt } = req.body as {
            title: string;
            body: string;
            targetType: AdminNotificationTargetType;
            targetValue?: string;
            userIds?: string[];
            actionUrl?: string;
            sendAt?: string;
        };

        if (sendAt) {
            const scheduledAt = new Date(sendAt);
            if (Number.isNaN(scheduledAt.getTime())) {
                return sendAdminError(req, res, "Invalid scheduled time", 400);
            }
            if (scheduledAt <= new Date()) {
                return sendAdminError(req, res, "Scheduled time must be in the future", 400);
            }

            const scheduled = await createScheduledNotification({
                title,
                body,
                type: NOTIFICATION_TYPE.SYSTEM,
                targetType,
                targetValue,
                userIds: targetType === "users" ? userIds : undefined,
                actionUrl,
                sentBy: currentUser._id,
                sendAt: scheduledAt,
                status: "pending",
            });

            await logAdminAction(req, "SCHEDULE_NOTIFICATION", "ScheduledNotification", scheduled._id.toString(), {
                title,
                targetType,
                targetValue,
                actionUrl,
                sendAt: scheduledAt.toISOString(),
            });

            return sendSuccessResponse(res, scheduled, `Notification scheduled for ${scheduledAt.toLocaleString()}`);
        }

        const audienceId = new mongoose.Types.ObjectId().toString();
        const { successCount, skippedCount, failureCount } = await dispatchToAudience({
            audienceId,
            title,
            body,
            targetType,
            targetValue,
            userIds,
            actionUrl,
            kind: "admin_broadcast",
        });

        const status = successCount > 0 || skippedCount > 0 ? "sent" : "failed";
        const log = await createNotificationLog({
            title,
            body,
            type: NOTIFICATION_TYPE.SYSTEM,
            targetType,
            targetValue,
            userIds: targetType === "users" ? userIds : undefined,
            actionUrl,
            sentBy: currentUser._id,
            successCount,
            skippedCount,
            failureCount,
            status,
        });

        await logAdminAction(req, "SEND_NOTIFICATION", "Notification", log._id.toString(), {
            title,
            targetType,
            targetValue,
            successCount,
            skippedCount,
            failureCount,
            actionUrl,
        });

        return sendSuccessResponse(res, log, status === "sent" ? "Notification sent successfully" : "Notification failed");
    } catch (error) {
        return sendAdminError(req, res, error);
    }
}

export async function getHistory(req: Request, res: Response) {
    try {
        const { page, limit, skip } = getPaginationParams(req);
        const { q, status, targetType } = req.query as {
            q?: string;
            status?: "all" | "sent" | "failed" | "scheduled";
            targetType?: AdminNotificationTargetType;
        };
        const historyStatus = status ?? "all";
        const mergeWindow = skip + limit;
        const searchTerm = q?.trim();
        const searchRegex = searchTerm ? new RegExp(escapeRegex(searchTerm), "i") : null;

        const logMatch: {
            targetType?: AdminNotificationTargetType;
            status?: "sent" | "failed";
            $or?: Array<
                | { title: { $regex: RegExp } }
                | { body: { $regex: RegExp } }
            >;
        } = {};

        const scheduledMatch: {
            targetType?: AdminNotificationTargetType;
            status: "pending";
            $or?: Array<
                | { title: { $regex: RegExp } }
                | { body: { $regex: RegExp } }
            >;
        } = {
            status: "pending",
        };

        if (targetType) {
            logMatch.targetType = targetType;
            scheduledMatch.targetType = targetType;
        }

        if (searchRegex) {
            logMatch.$or = [{ title: { $regex: searchRegex } }, { body: { $regex: searchRegex } }];
            scheduledMatch.$or = [{ title: { $regex: searchRegex } }, { body: { $regex: searchRegex } }];
        }

        if (historyStatus === "sent" || historyStatus === "failed") {
            logMatch.status = historyStatus;
        }

        const includeLogs = historyStatus === "all" || historyStatus === "sent" || historyStatus === "failed";
        const includeScheduled = historyStatus === "all" || historyStatus === "scheduled";

        const { logs, logsTotal, scheduled, scheduledTotal } = await getNotificationHistory(
            logMatch,
            scheduledMatch,
            { includeLogs, includeScheduled, mergeWindow }
        );

        const normalizedLogs: HistoryRecord[] = logs.map((log: Record<string, any>) => ({
            id: log._id.toString(),
            title: log.title,
            body: log.body,
            type: log.type,
            targetType: log.targetType,
            targetValue: log.targetValue,
            userIds: log.userIds,
            actionUrl: log.actionUrl,
            sentBy: (log as unknown as { sentBy?: mongoose.Types.ObjectId | Record<string, unknown> }).sentBy ?? null,
            successCount: log.successCount,
            skippedCount: log.skippedCount ?? 0,
            failureCount: log.failureCount,
            status: log.status,
            createdAt: log.createdAt,
        }));

        const normalizedScheduled: HistoryRecord[] = scheduled.map((job: Record<string, any>) => ({
            id: job._id.toString(),
            title: job.title,
            body: job.body,
            type: job.type,
            targetType: job.targetType,
            targetValue: job.targetValue,
            userIds: job.userIds,
            actionUrl: job.actionUrl,
            sentBy: (job as unknown as { sentBy?: mongoose.Types.ObjectId | Record<string, unknown> }).sentBy ?? null,
            successCount: 0,
            skippedCount: 0,
            failureCount: 0,
            status: "scheduled",
            createdAt: job.sendAt,
            sendAt: job.sendAt,
        }));

        const items = [...normalizedScheduled, ...normalizedLogs]
            .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())
            .slice(skip, skip + limit);

        const total = logsTotal + scheduledTotal;

        return res.status(200).json(
            respond({
                success: true,
                data: {
                    items,
                    pagination: {
                        page,
                        limit,
                        total,
                        totalPages: Math.ceil(total / limit),
                    },
                },
            })
        );
    } catch (error) {
        return sendAdminError(req, res, error);
    }
}

export async function getRecipients(req: Request, res: Response) {
    try {
        const { q, limit = 8 } = req.query as { q?: string; limit?: number };
        const query = q?.trim();

        if (!query) {
            return sendSuccessResponse(res, { items: [] });
        }

        const items = await searchNotificationRecipients(query, typeof limit === 'number' ? limit : Number(limit) || 8);

        return sendSuccessResponse(res, { items });
    } catch (error) {
        return sendAdminError(req, res, error);
    }
}

import mongoose from 'mongoose';
import { Request, Response } from 'express';
import logger from '@esparex/core/utils/logger';
import { toOptionalString } from './inputCoercion';
import { setCache } from '@esparex/core/utils/redisCache';
import { getVariantsAndModelsForParentModels, getBrandModelsForDuplicateCheck } from '@esparex/core/services/catalog/CatalogBrandModelService';
import { validateModelHierarchyMutation } from '@esparex/core/services/catalog/CatalogHierarchyService';
import { detectDuplicateCandidates } from '@esparex/core/services/catalog/CatalogSearchGovernanceService';

export const CATALOG_CACHE_TTL = 300;

export const normalizeCacheValue = (value: unknown): string => {
    if (Array.isArray(value)) return value.map(normalizeCacheValue).join(',');
    if (value === undefined || value === null || value === '') return 'all';
    return encodeURIComponent(String(value));
};

export const catalogCacheKey = {
    brands: (categoryId: string) => `catalog:brands:${normalizeCacheValue(categoryId)}`,
    models: (params: {
        categoryId?: unknown; brandId?: unknown; parentModelId?: unknown; variantModelId?: unknown;
        includeVariants?: unknown; treeView?: unknown; search?: unknown; q?: unknown;
        page?: unknown; limit?: unknown; sort?: unknown;
    }) => ['catalog:models', `category=${normalizeCacheValue(params.categoryId)}`, `brand=${normalizeCacheValue(params.brandId)}`,
        `parent=${normalizeCacheValue(params.parentModelId)}`, `variant=${normalizeCacheValue(params.variantModelId)}`,
        `includeVariants=${normalizeCacheValue(params.includeVariants)}`, `treeView=${normalizeCacheValue(params.treeView)}`,
        `search=${normalizeCacheValue(params.search ?? params.q)}`, `page=${normalizeCacheValue(params.page ?? 1)}`,
        `limit=${normalizeCacheValue(params.limit ?? 100)}`, `sort=${normalizeCacheValue(params.sort ?? 'name')}`,
    ].join(':'),
};

export const normalizeOptionalObjectIdQuery = (value: unknown): string | undefined => {
    const raw = Array.isArray(value) ? value[0] : value;
    if (typeof raw !== 'string') return undefined;
    const normalized = raw.trim();
    if (!normalized || normalized === 'all') return undefined;
    return mongoose.Types.ObjectId.isValid(normalized) ? normalized : undefined;
};

export const normalizeBooleanQuery = (value: unknown): boolean => {
    const raw = Array.isArray(value) ? value[0] : value;
    return raw === true || raw === 'true' || raw === '1';
};

export const populateModelVariants = async (items: unknown[]) => {
    const modelIds = items.map((item) => { const m = item as { _id?: unknown; id?: unknown }; return m._id ?? m.id; }).filter(Boolean).map(String);
    if (modelIds.length === 0) return items;
    const [variantDocs, variantModelDocs] = await getVariantsAndModelsForParentModels(modelIds);
    const variantsByModelId = new Map<string, unknown[]>();
    for (const v of variantDocs) { const mid = String((v as { modelId?: unknown }).modelId ?? ''); if (!mid) continue; const ex = variantsByModelId.get(mid) ?? []; ex.push(v); variantsByModelId.set(mid, ex); }
    const variantModelsByParentId = new Map<string, unknown[]>();
    for (const vm of variantModelDocs) { const pid = String((vm as { variantOfModelId?: unknown }).variantOfModelId ?? ''); if (!pid) continue; const ex = variantModelsByParentId.get(pid) ?? []; ex.push(vm); variantModelsByParentId.set(pid, ex); }
    return items.map((item) => {
        const plain = typeof (item as { toObject?: () => unknown }).toObject === 'function' ? (item as { toObject: () => Record<string, unknown> }).toObject() : { ...(item as Record<string, unknown>) };
        const id = String(plain._id ?? plain.id ?? '');
        return { ...plain, variants: variantsByModelId.get(id) ?? [], variantModels: variantModelsByParentId.get(id) ?? [] };
    });
};

export const applyModelHierarchyPayload = async (payload: Record<string, unknown>, options: { existingModel?: unknown } = {}) => {
    const normalizedPayload = {
        ...payload,
        brandId: toOptionalString(payload.brandId) ?? payload.brandId,
        parentModelId: payload.parentModelId === null ? null : toOptionalString(payload.parentModelId) ?? payload.parentModelId,
        variantOfModelId: payload.variantOfModelId === null ? null : toOptionalString(payload.variantOfModelId) ?? payload.variantOfModelId,
    };
    return validateModelHierarchyMutation(normalizedPayload, { existingModel: options.existingModel as any });
};

export const logModelDuplicateCandidates = async (req: Request, payload: Record<string, unknown>, options: { excludeId?: string } = {}) => {
    const name = String(payload.displayName ?? payload.name ?? payload.canonicalName ?? '').trim();
    const brandId = toOptionalString(payload.brandId);
    if (!name || !brandId) return;
    const candidates = await getBrandModelsForDuplicateCheck(brandId, options.excludeId);
    const dupes = detectDuplicateCandidates(name, candidates as unknown as Record<string, unknown>[]);
    if (dupes.length > 0) logger.warn('[CatalogSearch] Potential model duplicate candidates detected', { requestPath: req.originalUrl || req.path, candidateCount: dupes.length, input: name, candidates: dupes });
};

export const applyCacheWriteThrough = (res: Response, cacheKey: string) => {
    const originalJson = res.json.bind(res);
    res.json = (body: unknown) => {
        if (res.statusCode >= 200 && res.statusCode < 300) setCache(cacheKey, body, CATALOG_CACHE_TTL).catch(() => {});
        return originalJson(body);
    };
};

