            new MongoCategoryRepositoryAdapter(),
            new MongoBrandRepositoryAdapter(),
            new MongoModelRepositoryAdapter(),
            new MongoSparePartRepositoryAdapter(),
            new MongoScreenSizeRepositoryAdapter()
        );
    }
    return serviceInstance;
}

