    resetUnreadCount(conversationId: string, unreadField: string): Promise<void>;
}

import mongoose from 'mongoose';
import { env } from '../../../../../config/env';
import Boost from '../../../../../models/Boost';
import Category from '../../../../../models/Category';
import { getListingRepository } from '../../../../../composition/listings';
import type { ListingFilter, Listing } from '../../../../../domains/listings/ports/ListingRepositoryPort';
import { buildPublicAdFilter } from '../../../../../utils/FeedVisibilityGuard';
import { normalizeAdImagesForResponse } from '../../../../../domains/listings/application/queries/adQuery/AdQueryHelpers';
import { normalizeGeoInput } from '../../../../../utils/mongoGeoUtils';
import type { HomeFeedResponse } from "@esparex/contracts";
import logger from '../../../../../utils/logger';
import { FeedDecisionEngine } from '../FeedDecisionEngine';
import { HomeFeedRequest, ParsedHomeFeedCursor } from './FeedCursorService';
import { LISTING_TYPE } from '@esparex/contracts';
import { 
    filterBeforeCursor, 
    mergeRankedFeed, 
    extractAdId, 
    extractObjectIdHex 
} from './FeedRankerService';

interface FeedFacetResult {
    spotlight: Record<string, unknown>[];
    boosted: Record<string, unknown>[];
    organic: Record<string, unknown>[];
}

export const buildHomeFeed = async (
    input: HomeFeedRequest,
    limit: number,
    cursor: ParsedHomeFeedCursor | null
): Promise<HomeFeedResponse> => {
    const startedAt = Date.now();

    // 1. Resolve Match Criteria
    const baseFilter: ListingFilter = {
        listingType: LISTING_TYPE.AD,
    };

    if (typeof input.locationId === 'string' && mongoose.Types.ObjectId.isValid(input.locationId)) {
        baseFilter.locationId = input.locationId;
    } else if (typeof input.location === 'string' && input.location.trim().length > 0) {
        const safeLoc = input.location.trim().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        if (input.level === 'state') {
            baseFilter.locationState = { $regex: `^${safeLoc}$`, $options: 'i' };
        } else if (input.level === 'city' || !input.level) {
            baseFilter.locationCity = { $regex: `^${safeLoc}$`, $options: 'i' };
        }
    }

    let resolvedCategoryId: string | undefined = undefined;
    if (typeof input.categoryId === 'string' && input.categoryId.trim().length > 0) {
        resolvedCategoryId = input.categoryId.trim();
    } else if (typeof input.category === 'string' && input.category.trim().length > 0) {
        const lookup = input.category.trim();
        const found = await Category.findOne({
            $or: [
                { slug: lookup.toLowerCase() },
                { name: { $regex: `^${lookup.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`, $options: 'i' } }
            ]
        }).select('_id').lean<{ _id: mongoose.Types.ObjectId } | null>();
        if (found) {
            resolvedCategoryId = found._id.toString();
        }
    }

    if (resolvedCategoryId) {
        baseFilter.categoryId = resolvedCategoryId;
    }

    const visibilityFilter = buildPublicAdFilter() as unknown as Partial<ListingFilter>;
    Object.assign(baseFilter, visibilityFilter);

    if (cursor) {
        baseFilter.cursorCreatedAt = cursor.createdAt;
        if (cursor.id) baseFilter.cursorId = cursor.id;
    }

    if (env.FEED_DEBUG) {
        logger.debug(`[FeedDebug] Final Match Filter`, { baseFilter });
    }

    // 2. Fetch Active Boosts (Fast Indexed Query)
    const now = new Date();
    const boostCandidates = await Boost.find({
        entityType: 'ad',
        isActive: true,
        startsAt: { $lte: now },
        endsAt: { $gt: now }
    })
        .select('entityId')
        .sort({ createdAt: -1 })
        .limit(200) // Safety cap
        .lean<Array<{ entityId?: mongoose.Types.ObjectId }>>();

    const boostedIds = boostCandidates
        .map((entry: { entityId?: mongoose.Types.ObjectId }) => entry.entityId)
        .filter((id: mongoose.Types.ObjectId | undefined): id is mongoose.Types.ObjectId => id instanceof mongoose.Types.ObjectId);

    const { lat, lng, hasGeo } = normalizeGeoInput(input.lat, input.lng);
    const normalizedLevel = typeof input.level === 'string' ? input.level.toLowerCase() : undefined;
    const shouldUseGeo = hasGeo && normalizedLevel !== 'state' && normalizedLevel !== 'country';
    const safeRadius = shouldUseGeo 
        ? Math.min(Math.max(Number(input.radiusKm) || 50, 1), 500) 
        : 0;

    // 3. Unified Fetch via ListingRepositoryPort
    const spotlightFilter: ListingFilter = {
        ...baseFilter,
        isSpotlight: true,
        spotlightExpiresAt: { $gt: now }
    };

    const nonSpotlightFilter: ListingFilter = {
        ...baseFilter,
        $or: [
            { isSpotlight: { $ne: true } },
            { spotlightExpiresAt: { $exists: false } },
            { spotlightExpiresAt: null },
            { spotlightExpiresAt: { $lte: now } }
        ]
    };

    const boostedFilter: ListingFilter = {
        ...nonSpotlightFilter,
        ids: boostedIds.map(String)
    };

    const organicFilter: ListingFilter = {
        ...nonSpotlightFilter,
        idsNotIn: boostedIds.map(String)
    };

    const sortOption: Record<string, 1 | -1> = { createdAt: -1, _id: -1 };

    const fetch = async (filter: ListingFilter): Promise<readonly Listing[]> => {
        if (shouldUseGeo && lat !== undefined && lng !== undefined) {
            return getListingRepository().findWithinRadius(lng, lat, safeRadius, filter, sortOption, limit * 2);
        }
        return getListingRepository().findWithLimit(filter, sortOption, limit * 2);
    };

    const [spotlightListings, boostedListings, organicListings] = await Promise.all([
        fetch(spotlightFilter),
        fetch(boostedFilter),
        fetch(organicFilter)
    ]);

    const toFeedAd = (l: Listing, overrides: { isSpotlight: boolean, isBoosted: boolean }) => ({
        ...l,
        _id: l.id,
        ...overrides
    });

    const spotlightAds = filterBeforeCursor(
        spotlightListings.map(l => toFeedAd(l, { isSpotlight: true, isBoosted: false })),
        cursor
    );
    const boostedAds = filterBeforeCursor(
        boostedListings.map(l => toFeedAd(l, { isSpotlight: false, isBoosted: true })),
        cursor
    );
    const organicAds = filterBeforeCursor(
        organicListings.map(l => toFeedAd(l, { isSpotlight: false, isBoosted: false })),
        cursor
    );

    // 4. Merge results
    const merged = mergeRankedFeed(spotlightAds as Record<string, unknown>[], boostedAds as Record<string, unknown>[], organicAds as Record<string, unknown>[], limit);

    // 5. Fallback Logic
    let isFallbackResult = false;
    const isStrictLocation = Boolean(input.locationId || input.location || shouldUseGeo);

    if (!cursor && merged.ads.length < 4 && isStrictLocation) {
        isFallbackResult = true;
        const seenIds = new Set(merged.ads.map(extractAdId).filter(Boolean));

        const engineResult = await FeedDecisionEngine.getFallbackFeed(
            {
                locationId: input.locationId,
                city: typeof input.location === 'string' ? input.location.trim() : undefined,
                state: input.level === 'state' && typeof input.location === 'string' ? input.location.trim() : undefined,
                lat: shouldUseGeo ? input.lat : undefined,
                lng: shouldUseGeo ? input.lng : undefined,
            },
            Array.from(seenIds),
            limit - merged.ads.length,
            input.categoryId
        );

        const sortedBucket = engineResult.ads;
        for (const ad of sortedBucket) {
            if (merged.ads.length >= limit) break;
            const id = extractAdId(ad);
            if (!id || seenIds.has(id)) continue;
            seenIds.add(id);
            merged.ads.push(ad);
        }
    }

    const lastAd = merged.ads[merged.ads.length - 1];
    const lastAdCursor = lastAd
        ? {
            createdAt: new Date(String(lastAd.createdAt ?? '')).toISOString(),
            id: extractObjectIdHex(lastAd) || String(extractAdId(lastAd))
        }
        : null;

    logger.debug('Home feed build timings', { 
        durationMs: Date.now() - startedAt,
        adsCount: merged.ads.length,
        isFallback: isFallbackResult
    });

    return {
        ads: merged.ads.map(ad => normalizeAdImagesForResponse(ad as Record<string, unknown>)) as HomeFeedResponse['ads'],
        nextCursor: merged.hasRemaining ? lastAdCursor : null,
        hasMore: merged.hasRemaining && merged.ads.length > 0,
        isFallback: isFallbackResult
    };
};

import mongoose from 'mongoose';
import User from '../../../../../models/User';
import Business from '../../../../../models/Business';
import BlockedUser from '../../../../../models/BlockedUser';
import { UserRepositoryPort, UserProfileData } from '../../../ports/UserRepositoryPort';
import { normalizeRole } from '../../../application/roles/roleNormalization';

export class MongoUserRepositoryAdapter implements UserRepositoryPort {
    public async findActiveProfileById(id: string): Promise<UserProfileData | null> {
        if (!mongoose.Types.ObjectId.isValid(id)) return null;
        return await User.findOne({ _id: new mongoose.Types.ObjectId(id), status: { $ne: 'deleted' } })
            .select('name avatar createdAt isVerified location.city location.state location.country')
            .lean<UserProfileData | null>();
    }
    public async updateUser(id: string, updates: any): Promise<any> {
        const safeId = typeof id === 'string' ? id : String(id);
        const rawUpdates = (updates && typeof updates === 'object' && !Array.isArray(updates)) ? updates : {};
        const sanitizedUpdates = Object.fromEntries(
            Object.entries(rawUpdates).filter(([key]) => !key.startsWith('$') && !key.includes('.'))
        );
        return await User.findByIdAndUpdate(
            safeId,
            { $set: sanitizedUpdates },
            { new: true, runValidators: true }
        ).select('-password');
    }
    public async removeUserFcmToken(userId: any, token: string): Promise<void> {
        const safeId = typeof userId === 'string' ? userId : String(userId ?? '');
        await User.findByIdAndUpdate(safeId, { $pull: { fcmTokens: { token: String(token ?? '') } } });
    }
    public async getUserById(userId: string): Promise<any> {
        const safeId = typeof userId === 'string' ? userId : String(userId);
        const user = await User.findById(safeId).lean() as any;
        if (user && user.role) user.role = normalizeRole(user.role);
        return user;
    }
    public async getUserWithBusiness(userId: string): Promise<{ user: any; business: any }> {
        const safeId = typeof userId === 'string' ? userId : String(userId);
        const [user, business] = await Promise.all([
            User.findById(safeId).select('-password -salt').lean() as any,
            Business.findOne({ userId: String(userId) }).lean(),
        ]);
        if (user && user.role) user.role = normalizeRole(user.role);
        return { user, business };
    }
    public async getUserPhoneVerification(userId: string): Promise<any> {
        const safeId = typeof userId === 'string' ? userId : String(userId);
        return User.findById(safeId).select('isPhoneVerified mobile').lean();
    }
    public async findUserByEmail(email: string): Promise<any> {
        const safeEmail = typeof email === 'string' ? email : String(email ?? '');
        return User.findOne({ email: safeEmail });
    }
    public async getUserAvatarById(userId: string): Promise<any> {
        const safeId = typeof userId === 'string' ? userId : String(userId);
        return User.findById(safeId).select('avatar').lean();
    }
    public async checkUserExistsById(userId: string): Promise<boolean> {
        const exists = await User.exists({ _id: new mongoose.Types.ObjectId(userId), isDeleted: { $ne: true } });
        return !!exists;
    }
    public async blockUserById(blockerId: string, blockedUserId: string): Promise<any> {
        return BlockedUser.updateOne(
            { blockerId: new mongoose.Types.ObjectId(blockerId), blockedId: new mongoose.Types.ObjectId(blockedUserId) },
            { $setOnInsert: { blockerId: new mongoose.Types.ObjectId(blockerId), blockedId: new mongoose.Types.ObjectId(blockedUserId) } },
            { upsert: true }
        );
    }
    public async unblockUserById(blockerId: string, blockedUserId: string): Promise<any> {
        return BlockedUser.deleteOne({ blockerId: new mongoose.Types.ObjectId(blockerId), blockedId: new mongoose.Types.ObjectId(blockedUserId) });
    }
}

import Admin, { IAdmin } from '../../../../../models/Admin';
import User from '../../../../../models/User';
import { USER_STATUS, Role } from '@esparex/contracts';
import { hashPassword } from '../../auth/auth';
import { AppError } from '../../../../../utils/AppError';
import type { AdminLogFn } from '../../../../../services/AdminListingsService';
import { recalculateTrustScore } from '../../../../../services/TrustService';
import { revokeAdminSessionsForAdmin } from '../../sessions/AdminSessionService';
import { normalizeAdminManagedUser, ALLOWED_ADMIN_ROLES, ensureRoleAssignmentAllowed } from './helpers';
import { isLastActiveSuperAdmin } from './superAdmin';

export const getAdmins = async (pagination: { skip?: number; limit?: number } = {}) => {
    const skip = pagination.skip ?? 0;
    const limit = pagination.limit ?? 50;
    const [admins, total] = await Promise.all([
        Admin.find().select('-password').sort({ createdAt: -1 }).skip(skip).limit(limit),
        Admin.countDocuments(),
    ]);
    return { data: admins, total };
};
export const getAdminByIdForAdmin = async (id: string) => Admin.findById(id).select('-password');
export const getUserByIdForAdmin = async (id: string) => User.findById(id).select('-password');

export const updateAdminUser = async (userId: string, data: Record<string, unknown>, actorId: string, logFn: AdminLogFn) => {
    const { name, email, mobile } = data as { name?: string; email?: string; mobile?: string };
    if (email || mobile) {
        const orClauses: Record<string, unknown>[] = [];
        if (email) orClauses.push({ email });
        if (mobile) orClauses.push({ mobile });
        if (orClauses.length > 0) { const exists = await User.findOne({ _id: { $ne: userId }, $or: orClauses }); if (exists) throw new AppError('Email or Mobile already in use', 409, 'USER_ALREADY_EXISTS'); }
    }
    const updateData: Record<string, unknown> = { updatedBy: actorId };
    if (name !== undefined) updateData.name = name;
    if (email !== undefined) updateData.email = email;
    if (mobile !== undefined) updateData.mobile = mobile;
    const user = await User.findByIdAndUpdate(userId, updateData, { new: true }).select('-password');
    if (!user) throw new AppError('User not found', 404, 'USER_NOT_FOUND');
    await logFn('UPDATE_USER', 'User', userId, { changes: Object.keys(data) });
    return normalizeAdminManagedUser(user as any);
};

export const verifyUserById = async (id: string, isVerified: boolean, actorId: string, logFn: AdminLogFn) => {
    const user = await User.findByIdAndUpdate(id, { isVerified }, { new: true }).select('-password');
    if (!user) throw new AppError('User not found', 404);
    await logFn('VERIFY_USER', 'User', String(user._id), { isVerified });
    setImmediate(() => void recalculateTrustScore(user._id).catch(() => {}));
    return normalizeAdminManagedUser(user as any);
};

export const findAdminByEmail = async (email: string) => Admin.findOne({ email });

export const createAdminAccount = async (data: Record<string, unknown>, actorRole: string, actorId: string, logFn: AdminLogFn) => {
    const d = data as { firstName?: string; lastName?: string; name?: string; email?: string; mobile?: string; password?: string; role?: string; permissions?: string[] };
    const normalizedEmail = typeof d.email === 'string' ? d.email.trim().toLowerCase() : '';
    const nf = typeof d.firstName === 'string' ? d.firstName.trim() : typeof d.name === 'string' ? d.name.trim().split(/\s+/)[0] || '' : '';
    const nl = typeof d.lastName === 'string' ? d.lastName.trim() : typeof d.name === 'string' ? d.name.trim().split(/\s+/).slice(1).join(' ') : '';
    if (!nf || !nl || !normalizedEmail || !d.password) throw new AppError('Name, email, and password are required', 400);
    const exists = await findAdminByEmail(normalizedEmail);
    if (exists) throw new AppError('Admin with this email already exists', 409);
    const normalizedRole = typeof d.role === 'string' && ALLOWED_ADMIN_ROLES.has(d.role as Role) ? d.role : Role.ADMIN;
    if (!ensureRoleAssignmentAllowed(actorRole, normalizedRole)) throw new AppError('Cannot assign a role higher than your own', 403);
    const permissions = Array.isArray(d.permissions) ? d.permissions.filter((v) => typeof v === 'string') : [];
    const newAdmin = await Admin.create({ firstName: nf, lastName: nl, email: normalizedEmail, mobile: d.mobile, password: d.password, role: normalizedRole as IAdmin['role'], permissions, status: USER_STATUS.LIVE });
    const ao = newAdmin.toObject() as any; delete ao.password;
    await logFn('CREATE_ADMIN', 'Admin', newAdmin._id.toString(), { role: normalizedRole, permissions });
    return ao;
};

export const updateAdminById = async (id: string, updateDataRaw: Record<string, unknown>, currentId: string, actorRole: string, logFn: AdminLogFn) => {
    const d = updateDataRaw as { firstName?: string; lastName?: string; email?: string; mobile?: string; permissions?: string[]; status?: string; password?: string; role?: string };
    if (id === currentId && d.status && [USER_STATUS.SUSPENDED, USER_STATUS.BANNED, USER_STATUS.INACTIVE].includes(d.status as any)) throw new AppError('You cannot suspend/deactivate your own admin account', 400);
    if (id === currentId && d.role) throw new AppError('You cannot change your own role', 400);
    if (d.status && [USER_STATUS.SUSPENDED, USER_STATUS.BANNED, USER_STATUS.INACTIVE].includes(d.status as any)) { if (await isLastActiveSuperAdmin(id)) throw new AppError(`Cannot suspend/deactivate the last active Super Admin`, 400); }
    const updateData: Record<string, unknown> = {};
    if (d.firstName) updateData.firstName = d.firstName;
    if (d.lastName) updateData.lastName = d.lastName;
    if (d.email) updateData.email = d.email;
    if (d.mobile) updateData.mobile = d.mobile;
    if (d.permissions) updateData.permissions = d.permissions;
    if (d.status) updateData.status = d.status;
    if (d.role) { if (!ALLOWED_ADMIN_ROLES.has(d.role as Role)) throw new AppError('Invalid admin role', 400); if (!ensureRoleAssignmentAllowed(actorRole, d.role)) throw new AppError('Cannot assign a role higher than your own', 403); updateData.role = d.role; }
    if (d.password?.trim()) updateData.password = await hashPassword(d.password);
    if (await isLastActiveSuperAdmin(id) && d.role && d.role !== Role.SUPER_ADMIN) throw new AppError('Cannot downgrade the last active Super Admin', 400);
    const updatedAdmin = await Admin.findByIdAndUpdate(id, { $set: updateData }, { new: true }).select('-password');
    if (!updatedAdmin) throw new AppError('Admin not found', 404);
    if (d.status && [USER_STATUS.INACTIVE, USER_STATUS.SUSPENDED, USER_STATUS.BANNED].includes(d.status as any)) await revokeAdminSessionsForAdmin(id);
    await logFn('UPDATE_ADMIN', 'Admin', String(id), { changes: Object.keys(updateData) });
    return updatedAdmin;
};

export const softDeleteAdminById = async (id: string, currentId: string, logFn: AdminLogFn) => {
    if (id === currentId) throw new AppError('You cannot delete yourself', 400);
    if (await isLastActiveSuperAdmin(id)) throw new AppError('Cannot delete the last active Super Admin', 400);
    const admin = await Admin.findById(id);
    if (!admin) throw new AppError('Admin not found', 404);
    await (admin as any).softDelete();
    await revokeAdminSessionsForAdmin(id);
    await logFn('DELETE_ADMIN', 'Admin', id, { email: (admin as any).email });
    return admin;
};

export const deactivateAdminById = async (id: string, currentId: string, logFn: AdminLogFn) => {
    if (id === currentId) throw new AppError('You cannot deactivate yourself', 400);
    if (await isLastActiveSuperAdmin(id)) throw new AppError('Cannot deactivate the last active Super Admin', 400);
    const admin = await Admin.findByIdAndUpdate(id, { status: USER_STATUS.INACTIVE }, { new: true }).select('-password');
    if (!admin) throw new AppError('Admin not found', 404);
    await revokeAdminSessionsForAdmin(id);
    await logFn('DEACTIVATE_ADMIN', 'Admin', id, { status: 'inactive' });
    return admin;
};

export const toggleAdminStatus = async (id: string, currentId: string, logFn: AdminLogFn) => {
    const admin = await Admin.findById(id);
    if (!admin) throw new AppError('Admin not found', 404);
    const isActive = admin.status === USER_STATUS.LIVE;
    const nextStatus = isActive ? USER_STATUS.INACTIVE : USER_STATUS.LIVE;
    if (id === currentId && isActive && nextStatus === USER_STATUS.INACTIVE) throw new AppError('You cannot deactivate yourself', 400);
    if (isActive && await isLastActiveSuperAdmin(id)) throw new AppError('Cannot deactivate the last active Super Admin', 400);
    admin.status = nextStatus;
    await admin.save();
    if (nextStatus === USER_STATUS.INACTIVE) await revokeAdminSessionsForAdmin(id);
    const ao = admin.toObject(); delete (ao as any).password;
    await logFn('TOGGLE_ADMIN_STATUS', 'Admin', id, { status: nextStatus });
    return ao;
};

import { USER_STATUS, Role } from '@esparex/contracts';
import { normalizeUserStatus } from '@esparex/shared';

const ACTIVE_USER_STATUS_QUERY = USER_STATUS.ACTIVE;
const ADMIN_ROLE_RANK: Record<string, number> = { [Role.MODERATOR]: 40, [Role.ADMIN]: 70, [Role.SUPER_ADMIN]: 100 };
export const ALLOWED_ADMIN_ROLES = new Set([Role.SUPER_ADMIN, Role.ADMIN, Role.MODERATOR]);

export const getRoleRank = (role: string | undefined): number => ADMIN_ROLE_RANK[role || ''] || 0;

export const ensureRoleAssignmentAllowed = (actorRole: string | undefined, targetRole: string): boolean => {
    if (!actorRole) return false;
    if (actorRole === Role.SUPER_ADMIN) return true;
    return getRoleRank(targetRole) <= getRoleRank(actorRole);
};

export const buildUserStatusFilter = (status?: string) => {
    if (!status || status === 'all') return undefined;
    const normalizedStatus = normalizeUserStatus(status);
    const rawStatus = typeof status === 'string' ? status.toLowerCase() : '';
    if (rawStatus === USER_STATUS.LIVE || rawStatus === USER_STATUS.ACTIVE) {
        return { $in: [USER_STATUS.ACTIVE, USER_STATUS.LIVE] };
    }
    return normalizedStatus ?? status;
};

export const normalizeAdminManagedUser = <T extends Record<string, unknown>>(input: T): T => {
    const p: Record<string, unknown> = typeof (input as any).toObject === 'function' ? (input as any).toObject() : { ...input };
    const ns = normalizeUserStatus(p.status as string | undefined);
    if (ns) p.status = ns;
    return p as T;
};

export { ACTIVE_USER_STATUS_QUERY };

import Admin from '../../../../../models/Admin';
import { USER_STATUS, Role } from '@esparex/contracts';
import { isSuperAdminRole } from '../../roles/roleNormalization';

export const isLastActiveSuperAdmin = async (adminId: string): Promise<boolean> => {
    const [targetAdmin, superAdminCount] = await Promise.all([
        Admin.findById(adminId).select('role status isDeleted').lean(),
        Admin.countDocuments({ role: { $in: [Role.SUPER_ADMIN, 'superAdmin', 'superadmin'] }, status: USER_STATUS.LIVE, isDeleted: { $ne: true } } as any),
    ]);
    if (!targetAdmin) return false;
    const a = targetAdmin as { role?: string; status?: string };
    if (!isSuperAdminRole(a.role)) return false;
    if (a.status !== USER_STATUS.LIVE) return false;
    return superAdminCount <= 1;
};

import User from '../../../../../models/User';
import Ad from '../../../../../models/Ad';
import AdminMetrics from '../../../../../models/AdminMetrics';
import { USER_STATUS, Role } from '@esparex/contracts';
import { hashPassword } from '../../auth/auth';
import { AppError } from '../../../../../utils/AppError';
import type { AdminLogFn } from '../../../../../services/AdminListingsService';
import type { UserFilters } from './types';
import { ACTIVE_USER_STATUS_QUERY, buildUserStatusFilter, normalizeAdminManagedUser } from './helpers';

export const getUsers = async (filters: UserFilters = {}, pagination: { skip: number; limit: number }) => {
    const { search, status, role, isVerified } = filters;
    const { skip, limit } = pagination;
    const query: Record<string, unknown> = { status: { $ne: USER_STATUS.DELETED }, userType: 'marketplace' };
    if (search) query.$or = [{ name: { $regex: search, $options: 'i' } }, { email: { $regex: search, $options: 'i' } }, { mobile: { $regex: search, $options: 'i' } }];
    const sq = buildUserStatusFilter(status);
    if (sq) query.status = sq;
    if (role && role !== 'all') query.role = role;
    if (isVerified !== undefined) query.isVerified = isVerified;
    const [users, total] = await Promise.all([User.find(query).select('-password').sort({ createdAt: -1 }).skip(skip).limit(limit), User.countDocuments(query)]);
    const userIds = users.map((u) => u._id);
    const adCounts = userIds.length > 0 ? await Ad.aggregate<{ _id: unknown; totalAdsPosted: number }>([{ $match: { sellerId: { $in: userIds }, isDeleted: { $ne: true } } }, { $group: { _id: '$sellerId', totalAdsPosted: { $sum: 1 } } }]) : [];
    const adsByUserId = new Map(adCounts.map((e) => [String(e._id), Number(e.totalAdsPosted) || 0]));
    const data = users.map((u) => { const p = normalizeAdminManagedUser(u.toObject ? u.toObject() as any : { ...(u as any) }); p.totalAdsPosted = adsByUserId.get(String(u._id)) || 0; return p; });
    return { data, total };
};

export const getUserManagementOverview = async () => {
    const cachedMetrics = await AdminMetrics.findOne({ metricModule: 'USERS_OVERVIEW' }).sort({ aggregationDate: -1 }).lean();
    const startOfDay = new Date(); startOfDay.setUTCHours(0, 0, 0, 0);
    const payload = (cachedMetrics && typeof cachedMetrics.payload === 'object' && cachedMetrics.payload) || {};
    const tn = (v: unknown): number | undefined => typeof v === 'number' && Number.isFinite(v) ? v : undefined;
    const [newUsersToday, suspendedUsers, bannedUsers, liveTotalUsers, liveActiveUsers, liveVerifiedUsers, individuals, businesses, verifiedBusinesses, blockedUsers] = await Promise.all([
        User.countDocuments({ userType: 'marketplace', status: { $ne: USER_STATUS.DELETED }, createdAt: { $gte: startOfDay } }),
        User.countDocuments({ userType: 'marketplace', status: USER_STATUS.SUSPENDED }),
        User.countDocuments({ userType: 'marketplace', status: USER_STATUS.BANNED }),
        tn(payload.totalUsers) ?? User.countDocuments({ userType: 'marketplace', status: { $ne: USER_STATUS.DELETED } }),
        tn(payload.activeUsers) ?? User.countDocuments({ userType: 'marketplace', status: ACTIVE_USER_STATUS_QUERY }),
        tn(payload.verifiedUsers) ?? (tn(payload.totalUsers) !== undefined && tn(payload.unverifiedUsers) !== undefined ? Math.max(tn(payload.totalUsers)! - tn(payload.unverifiedUsers)!, 0) : User.countDocuments({ userType: 'marketplace', status: { $ne: USER_STATUS.DELETED }, isVerified: true })),
        User.countDocuments({ userType: 'marketplace', role: Role.USER, status: { $ne: USER_STATUS.DELETED } }),
        User.countDocuments({ userType: 'marketplace', role: Role.BUSINESS, status: { $ne: USER_STATUS.DELETED } }),
        User.countDocuments({ userType: 'marketplace', role: Role.BUSINESS, isVerified: true, status: { $ne: USER_STATUS.DELETED } }),
        User.countDocuments({ userType: 'marketplace', status: { $in: [USER_STATUS.SUSPENDED, USER_STATUS.BANNED] } }),
    ]);
    const totalUsers = liveTotalUsers;
    const activeUsers = liveActiveUsers;
    const verifiedUsers = liveVerifiedUsers;
    return { totalUsers, activeUsers, activeUsersPercentage: totalUsers > 0 ? Number(((activeUsers / totalUsers) * 100).toFixed(1)) : 0, verifiedUsers, verifiedUsersPercentage: totalUsers > 0 ? Number(((verifiedUsers / totalUsers) * 100).toFixed(1)) : 0, businessUsers: tn(payload.businessUsers) ?? 0, newUsersThisWeek: tn(payload.newUsersThisWeek) ?? 0, weekGrowth: '', newUsersToday, suspendedUsers, bannedUsers, individuals, businesses, verifiedBusinesses, blockedUsers };
};

export const createAdminUser = async (data: Record<string, unknown>, actorId: string, logFn: AdminLogFn) => {
    const name = data.name as string | undefined; const mobile = data.mobile as string | undefined; const email = data.email as string | undefined; const password = data.password as string | undefined; const isVerified = data.isVerified;
    if (!mobile || !name) throw new AppError('Name and Mobile are required', 400);
    const exists = await User.findOne({ $or: [{ mobile }, ...(email ? [{ email }] : [])] });
    if (exists) throw new AppError('User with this mobile or email already exists', 409, 'USER_ALREADY_EXISTS');
    const userData: Record<string, unknown> = { name, mobile, role: Role.USER, email, isVerified: !!isVerified, isPhoneVerified: !!isVerified, isEmailVerified: !!isVerified && !!email, status: USER_STATUS.LIVE, createdBy: actorId };
    if (password?.trim()) userData.password = await hashPassword(password);
    const newUser = await User.create(userData);
    const uo = normalizeAdminManagedUser(newUser.toObject ? newUser.toObject() as any : { ...(newUser as any) }); delete uo.password;
    await logFn('CREATE_USER', 'User', String(uo._id), { name, mobile, role: Role.USER }); return uo;
};

