import SparePart from '../../../../../models/SparePart';
import ServiceType from '../../../../../models/ServiceType';
import Ad from '../../../../../models/Ad';
import type { HydratedAd } from './types';

async function fetchMetadataWithCache<T>(
    ids: Set<string>,
    type: string,
    query: (missingIds: string[]) => Promise<T[]>,
    idField: string = '_id'
): Promise<T[]> {
    if (ids.size === 0) return [];
    const idArray = Array.from(ids);
    const cacheKeys = idArray.map(id => CACHE_KEYS.metadata(type, id));
    const cachedResults = await getMultiCache<T>(cacheKeys);
    const results: T[] = [];
    const missingIds: string[] = [];
    cachedResults.forEach((val: any, index: any) => {
        if (val) results.push(val);
        else { const id = idArray[index]; if (id) missingIds.push(id); }
    });
    if (missingIds.length > 0) {
        const fresh = await query(missingIds);
        results.push(...fresh);
        const cacheEntries = fresh.map(item => ({ key: CACHE_KEYS.metadata(type, String((item as MetadataEntity)[idField])), value: item }));
        if (cacheEntries.length > 0) await setMultiCache(cacheEntries);
    }
    return results;
}

export async function hydrateAdMetadata(ads: HydratedAd[]): Promise<HydratedAd[]> {
    if (!ads || ads.length === 0) return ads;
    const categoryIds = new Set<string>();
    const brandIds = new Set<string>();
    const modelIds = new Set<string>();
    const sparePartIds = new Set<string>();
    const serviceTypeIds = new Set<string>();
    const extractId = (val: unknown): string | null => {
        if (!val) return null;
        if (typeof val === 'string') return val;
        if (typeof val === 'object') {
            const record = val as Record<string, unknown>;
            const objectId = record._id;
            if (typeof objectId === 'string' || objectId instanceof mongoose.Types.ObjectId) return objectId.toString();
            const id = record.id;
            if (typeof id === 'string' || id instanceof mongoose.Types.ObjectId) return id.toString();
        }
        if (val instanceof mongoose.Types.ObjectId) return val.toString();
        return null;
    };
    ads.forEach(ad => {
        const catId = extractId(ad.categoryId || ad.category); if (catId) categoryIds.add(catId);
        const bId = extractId(ad.brandId || ad.brand); if (bId) brandIds.add(bId);
        const mId = extractId(ad.modelId || ad.model); if (mId) modelIds.add(mId);
        const spId = extractId(ad.sparePartId || ad.sparePart); if (spId) sparePartIds.add(spId);
        if (Array.isArray(ad.sparePartIds)) ad.sparePartIds.forEach((id) => { const sid = extractId(id); if (sid) sparePartIds.add(sid); });
        if (Array.isArray(ad.serviceTypeIds)) ad.serviceTypeIds.forEach((id) => { const sid = extractId(id); if (sid) serviceTypeIds.add(sid); });
    });
    const [categories, brands, models, spareParts, serviceTypes] = await Promise.all([
        fetchMetadataWithCache<MetadataEntity>(categoryIds, 'category', (missing) => Category.find({ _id: { $in: missing } }).select('name slug').lean<MetadataEntity[]>()),
        fetchMetadataWithCache<MetadataEntity>(brandIds, 'brand', (missing) => Brand.find({ _id: { $in: missing } }).select('name slug').lean<MetadataEntity[]>()),
        fetchMetadataWithCache<MetadataEntity>(modelIds, 'model', (missing) => Model.find({ _id: { $in: missing } }).select('name slug').lean<MetadataEntity[]>()),
        fetchMetadataWithCache<MetadataEntity>(sparePartIds, 'sparepart', (missing) => SparePart.find({ _id: { $in: missing } }).lean<MetadataEntity[]>()),
        fetchMetadataWithCache<MetadataEntity>(serviceTypeIds, 'servicetype', (missing) => ServiceType.find({ _id: { $in: missing } }).select('name').lean<MetadataEntity[]>()),
    ]);
    const categoryMap = new Map(categories.map((c) => [String(c._id), c]));
    const brandMap = new Map(brands.map((b) => [String(b._id), b]));
    const modelMap = new Map(models.map((m) => [String(m._id), m]));
    const sparePartMap = new Map(spareParts.map((s) => [String(s._id), s]));
    const serviceTypeMap = new Map(serviceTypes.map((st) => [String(st._id), st]));
    ads.forEach(ad => {
        const catId = extractId(ad.categoryId || ad.category); if (catId) { ad.categoryId = catId; const cat = categoryMap.get(catId); if (cat?.name) ad.categoryName = cat.name; } delete ad.category;
        const bId = extractId(ad.brandId || ad.brand); if (bId) { ad.brandId = bId; const brand = brandMap.get(bId); if (brand?.name) ad.brandName = brand.name; }
        if (typeof ad.brand === 'object' && ad.brand !== null && !ad.brandName) { const b = ad.brand as any; if (b.name) ad.brandName = b.name; }
        const mId = extractId(ad.modelId || ad.model); if (mId) { ad.modelId = mId; const model = modelMap.get(mId); if (model?.name) ad.modelName = model.name; }
        if (typeof ad.model === 'object' && ad.model !== null && !ad.modelName) { const m = ad.model as any; if (m.name) ad.modelName = m.name; }
        const spId = extractId(ad.sparePartId || ad.sparePart); if (spId) ad.sparePart = sparePartMap.get(spId);
        if (Array.isArray(ad.sparePartIds)) ad.spareParts = ad.sparePartIds.map((id) => { const sid = extractId(id); return sid ? sparePartMap.get(sid) : null; }).filter(Boolean) as MetadataEntity[];
        if (Array.isArray(ad.serviceTypeIds)) ad.serviceTypes = ad.serviceTypeIds.map((id) => { const sid = extractId(id); return sid ? serviceTypeMap.get(sid) : null; }).filter(Boolean) as MetadataEntity[];
    });
    return ads;
}

export const getOwnerListings = async (query: Record<string, unknown>, page: number, limit: number) => {
    const populateSpecs = [
        { path: 'categoryId', model: Category, select: 'name slug icon' },
        { path: 'brandId', model: Brand, select: 'name slug' },
        { path: 'modelId', model: Model, select: 'name slug' },
        { path: 'sparePartId', model: SparePart, select: 'name slug' },
        { path: 'serviceTypeIds', model: ServiceType, select: 'name slug' },
    ] as const;
    const itemsQuery = populateSpecs.reduce((builder, spec) => builder.populate(spec), Ad.find(query));
    const [items, total] = await Promise.all([
        itemsQuery.sort({ createdAt: -1 }).skip((page - 1) * limit).limit(limit),
        Ad.countDocuments(query),
    ]);
    return { items, total };
};

import mongoose from 'mongoose';
import Ad from '../../../../../models/Ad';
import { serializeDoc, normalizeLocationResponse, buildGeoNearStage, normalizeGeoInput, buildPublicAdFilter, logger, RankingTelemetry, uuidv4, extractLocationIdFromAd, normalizeAdImagesForResponse, FeatureFlag, isEnabled, getBlockedSellerIds, touchLocationSearchAnalytics } from '../../../../../domains/listings/application/ad/ad/_shared/adServiceBase';
import type { AdsListResult, AdFilters, UnknownRecord, AggregationStage, PaginationOptions, PublicQueryOptions, SortStage } from '../../../../../domains/listings/application/ad/ad/_shared/adServiceBase';
import { buildAdMatchStage, buildAdSortStage } from '../../../../../domains/listings/application/ad/ad/AdSearchService';
import type { HydratedAd, TelemetryAd } from './types';
import { hydrateAdMetadata } from './metadata';

const MAX_PAGE_SIZE = 50;
const MAX_PAGE = 1000;
const MAX_RADIUS_KM = 500;

export const getAds = async (
    filters: AdFilters,
    pagination: PaginationOptions,
    options: PublicQueryOptions = {}
): Promise<AdsListResult> => {
    const { page: rawPage, limit: rawLimit, cursor } = pagination;
    const limit = Math.min(Math.max(Number(rawLimit) || 20, 1), MAX_PAGE_SIZE);
    const page = Math.min(Math.max(Number(rawPage) || 1, 1), MAX_PAGE);
    const cursorId = typeof cursor === 'string' && mongoose.Types.ObjectId.isValid(cursor) ? new mongoose.Types.ObjectId(cursor) : null;
    const isCursorMode = Boolean(cursorId);
    const isTrendingSort = filters.sortBy === 'trending';
    const skip = (page - 1) * limit;
    const shouldApplyLocationIntelligence = !options.disableLocationIntelligence && !isCursorMode;
    const { lat, lng, hasGeo } = normalizeGeoInput(
        filters.coordinates ? filters.coordinates.coordinates[1] : filters.lat,
        filters.coordinates ? filters.coordinates.coordinates[0] : filters.lng
    );
    const normalizedLevel = typeof filters.level === 'string' ? filters.level.toLowerCase() : undefined;
    const isRegionLevel = normalizedLevel === 'country' || normalizedLevel === 'state';
    const shouldUseGeo = hasGeo && !isRegionLevel;
    const shouldSkipExactCount = shouldUseGeo && !isCursorMode && options.enforcePublicVisibility !== false;
    const shouldUseRankScore = isTrendingSort || (shouldUseGeo && !filters.sortBy);
    const safeRadius = shouldUseGeo ? Math.min(Math.max(Number(filters.radiusKm) || 50, 1), MAX_RADIUS_KM) : 0;
    const effectiveFilters: AdFilters = { ...filters };
    const locationLabel = typeof filters.location === 'string' ? filters.location.trim() : '';
    if (normalizedLevel === 'state' && !effectiveFilters.state && locationLabel.length > 0) effectiveFilters.state = locationLabel;
    if (normalizedLevel === 'country' && !effectiveFilters.country && locationLabel.length > 0) effectiveFilters.country = locationLabel;
    if (!shouldUseGeo) { delete effectiveFilters.lat; delete effectiveFilters.lng; delete effectiveFilters.radiusKm; delete effectiveFilters.coordinates; }
    const allowLegacyListingTypeNullCompat = await isEnabled(FeatureFlag.ENABLE_AD_LISTINGTYPE_NULL_COMPAT);
    const pipeline: AggregationStage[] = [];
    let match: UnknownRecord = { ...(await buildAdMatchStage(effectiveFilters, { allowLegacyListingTypeNullCompat, trackListingTypeCompatMetrics: options.trackListingTypeCompatMetrics, metricContext: 'getAds' })) };
    if (match.__isUnresolvableCategory) {
        logger.info('[AdAggregation] Short-circuiting getAds for unresolvable category', { category: filters.category, categoryId: filters.categoryId });
        return {
            data: [],
            pagination: {
                page,
                limit,
                total: 0,
                hasMore: false,
            },
        };
    }
    if (options.enforcePublicVisibility) {
        logger.info('[FeedVisibility] Applying public visibility guard', { viewerId: options.viewerId ?? null });
        match = { ...match, ...buildPublicAdFilter() };
    }
    const blockedSellerIds = await getBlockedSellerIds(options.viewerId);
    if (blockedSellerIds.length > 0) {
        logger.info('[FeedVisibility] Applying blocked-seller guard', { viewerId: options.viewerId, blockedSellerCount: blockedSellerIds.length });
        const blockedFilter = { sellerId: { $nin: blockedSellerIds } };
        match = Object.keys(match).length > 0 ? { $and: [match, blockedFilter] } : blockedFilter;
    }
    const textSearch = typeof filters.search === 'string' && filters.search.trim().length > 0 ? filters.search.trim() : undefined;
    if (cursorId) {
        const cursorMatch = { _id: { $lt: cursorId } };
        match = Object.keys(match).length > 0 ? { $and: [match, cursorMatch] } : cursorMatch;
    }
    if (shouldUseGeo) {
        if (textSearch) match.$text = { $search: textSearch };
        delete match['location.city']; delete match['location.state']; delete match['location.country']; delete match['location.display']; delete match['location.district'];
        if (Array.isArray(match.$or)) {
            const currentOr = match.$or as UnknownRecord[];
            const filteredOr = currentOr.filter((cond) => !Object.keys(cond).some(k => k.startsWith('location.')));
            if (filteredOr.length === 0) delete match.$or; else match.$or = filteredOr;
        }
        pipeline.push(buildGeoNearStage({ lng, lat, radiusKm: safeRadius, query: match }));
    } else {
        if (textSearch) match.$text = { $search: textSearch };
        pipeline.push({ $match: match });
    }
    const countPipeline: AggregationStage[] = isCursorMode ? [] : [...pipeline];
    if (shouldUseRankScore) pipeline.push({ $sort: { isSpotlight: -1, createdAt: -1 } as SortStage });
    const sort = buildAdSortStage({ ...effectiveFilters, search: shouldUseGeo ? undefined : effectiveFilters.search });
    if (!shouldUseRankScore) pipeline.push({ $sort: sort });
    if (!isCursorMode && !shouldSkipExactCount) { countPipeline.push({ $count: 'total' }); pipeline.push({ $skip: skip }); pipeline.push({ $limit: limit }); }
    else { pipeline.push({ $skip: skip }); pipeline.push({ $limit: limit + 1 }); }
    if (shouldUseRankScore) {
        pipeline.push({
            $lookup: { from: 'locationanalytics', let: { locationRef: '$location.locationId' }, pipeline: [{ $match: { $expr: { $eq: ['$locationId', '$$locationRef'] } } }, { $project: { popularityScore: 1, isHotZone: 1 } }, { $limit: 1 }], as: 'locationAnalytics' }
        });
        pipeline.push({
            $addFields: {
                locationAnalytics: { $arrayElemAt: ['$locationAnalytics', 0] },
                hoursSince: { $divide: [{ $subtract: [new Date(), '$createdAt'] }, 1000 * 60 * 60] },
                freshnessScore: { $max: [0, { $subtract: [100, { $divide: [{ $subtract: [new Date(), '$createdAt'] }, 1000 * 60 * 60] }] }] },
                distanceScore: { $cond: [{ $ifNull: ['$distance', false] }, { $max: [0, { $subtract: [100, { $multiply: [{ $divide: ['$distance', 1000] }, 2] }] }] }, 0] },
                popularityScore: { $min: [{ $ifNull: ['$locationAnalytics.popularityScore', 0] }, 100] },
                spotlightScore: { $cond: [{ $and: [{ $eq: ['$isSpotlight', true] }, { $gt: ['$spotlightExpiresAt', new Date()] }] }, 100, 0] },
                engagementScore: { $min: [{ $divide: [{ $ifNull: ['$views.total', 0] }, 10] }, 100] },
                hotZoneBoost: { $cond: [{ $eq: ['$locationAnalytics.isHotZone', true] }, 10, 0] }
            }
        });
        pipeline.push({ $addFields: { rankScore: { $add: [{ $multiply: ['$distanceScore', 0.4] }, { $multiply: ['$freshnessScore', 0.25] }, { $multiply: ['$popularityScore', 0.15] }, { $multiply: ['$spotlightScore', 0.1] }, { $multiply: ['$engagementScore', 0.1] }, '$hotZoneBoost', { $multiply: [{ $ifNull: ['$sellerTrustSnapshot', 50] }, 0.05] }, { $multiply: [{ $ifNull: ['$listingQualityScore', 0] }, 0.08] }, { $multiply: [{ $ifNull: ['$sellerPriorityScore', 1] }, 0.07] }, { $multiply: [{ $ifNull: ['$fraudScore', 0] }, -1] }] } } });
        pipeline.push({ $sort: { rankScore: -1, createdAt: -1 } });
    }
    const isLightweightListing = await isEnabled(FeatureFlag.ENABLE_LIGHTWEIGHT_LISTING);
    const shouldJoinSeller = !isLightweightListing || !options.enforcePublicVisibility;
    if (shouldJoinSeller) {
        pipeline.push({ $lookup: { from: 'users', let: { refId: '$sellerId' }, pipeline: [{ $match: { $expr: { $eq: ['$_id', '$$refId'] } } }, { $project: { name: 1, firstName: 1, lastName: 1, phone: 1, mobile: 1, email: 1 } }], as: 'seller' } });
        pipeline.push({ $unwind: { path: '$seller', preserveNullAndEmptyArrays: true } });
    }
    pipeline.push({
        $project: {
            title: 1, price: 1, priceMin: 1, priceMax: 1, diagnosticFee: 1, images: 1, description: 1,
            location: 1, status: 1, createdAt: 1, updatedAt: 1, views: 1, categoryId: 1, brandId: 1, modelId: 1,
            sellerId: 1, listingType: 1, planType: 1, isSpotlight: 1, spotlightExpiresAt: 1, expiresAt: 1,
            publishedAt: 1, approvedAt: 1, soldAt: 1, rejectionReason: 1, fraudScore: 1, moderationStatus: 1,
            distance: 1, distanceKm: { $cond: [{ $ifNull: ['$distance', false] }, { $divide: ['$distance', 1000] }, null] },
            rankScore: 1, distanceScore: 1, freshnessScore: 1, popularityScore: 1, sellerTrustSnapshot: 1,
            sellerPriorityScore: 1, listingQualityScore: 1, onsiteService: 1, turnaroundTime: 1, warranty: 1, included: 1, excluded: 1,
            serviceTypeIds: 1, sparePartId: 1, condition: 1, stock: 1, deviceType: 1, deviceCondition: 1,
            sparePartsSnapshot: 1, sparePartIds: 1, category: 1, brand: 1, model: 1, seller: 1, spareParts: 1
        }
    });

    const [rawResults, countResult] = await Promise.all([
        Ad.aggregate<HydratedAd>(pipeline),
        isCursorMode || shouldSkipExactCount ? Promise.resolve([]) : Ad.aggregate<{ total: number }>(countPipeline),
    ]);
    const useCursorStyleMeta = isCursorMode || shouldSkipExactCount;
    const hasMore = useCursorStyleMeta ? rawResults.length > limit : false;
    const results = useCursorStyleMeta ? rawResults.slice(0, limit) : rawResults;
    const shouldHydrateMetadata = !isLightweightListing || !options.enforcePublicVisibility;
    if (shouldHydrateMetadata) await hydrateAdMetadata(results);
    const nextCursor = useCursorStyleMeta && hasMore && results.length > 0 ? String(results[results.length - 1]?._id || '') : undefined;
    const total = useCursorStyleMeta ? results.length : countResult[0]?.total || 0;
    const data = results.map(ad => {
        const serializedAd = serializeDoc(ad);
        if (serializedAd.location) serializedAd.location = normalizeLocationResponse(serializedAd.location);
        return normalizeAdImagesForResponse(serializedAd as unknown as Record<string, unknown>);
    });
    const hasLocationContext = Boolean(hasGeo || effectiveFilters.locationId || effectiveFilters.location || effectiveFilters.district || effectiveFilters.state || effectiveFilters.country || effectiveFilters.level);
    if (hasLocationContext && !options.disableLocationIntelligence) {
        const trackedLocationIds = Array.from(new Set([typeof effectiveFilters.locationId === 'string' ? effectiveFilters.locationId : null, ...data.map((ad) => extractLocationIdFromAd(ad))].filter((v): v is string => Boolean(v))));
        if (trackedLocationIds.length > 0) {
            setImmediate(() => { touchLocationSearchAnalytics(trackedLocationIds).catch((error) => { logger.warn('Failed to update location_search analytics', { locationIds: trackedLocationIds, error: error instanceof Error ? error.message : String(error) }); }); });
        }
    }
    if (shouldApplyLocationIntelligence && shouldUseGeo && !isCursorMode && !filters.radiusKm) {
        // L1-L4 fallback logic inlined below
        const mergedById = new Map<string, Record<string, unknown>>();
        let locationHierarchyLevel: 'L1' | 'L2' | 'L3' | 'L4' = 'L1';
        const mergeAds = (items: Array<Record<string, unknown>>) => { for (const item of items) { const key = String(item.id || item._id || ''); if (!key || mergedById.has(key)) continue; mergedById.set(key, item); } };
        mergeAds(data);
        const minimumTarget = Math.min(limit, 10);
        const fetchMore = async (nextFilters: AdFilters) => { const remaining = Math.max(limit - mergedById.size, 1); if (remaining <= 0) return; const response = await getAds({ ...nextFilters, excludeIds: Array.from(mergedById.keys()) }, { page: 1, limit: remaining }, { ...options, disableLocationIntelligence: true }); mergeAds(response.data); };
        if (mergedById.size < minimumTarget && effectiveFilters.locationId) { locationHierarchyLevel = 'L2'; await fetchMore({ status: filters.status, locationId: effectiveFilters.locationId, categoryId: effectiveFilters.categoryId, sortBy: 'newest' }); }
        if (mergedById.size < minimumTarget && effectiveFilters.state) { locationHierarchyLevel = 'L3'; await fetchMore({ status: filters.status, state: effectiveFilters.state, categoryId: effectiveFilters.categoryId, sortBy: 'newest' }); }
        if (mergedById.size < minimumTarget) { locationHierarchyLevel = 'L4'; await fetchMore({ status: filters.status, categoryId: effectiveFilters.categoryId, sortBy: 'newest' }); }
        const merged = Array.from(mergedById.values());
        merged.sort((left, right) => {
            const leftScore = Number((left as { rankScore?: unknown }).rankScore ?? 0);
            const rightScore = Number((right as { rankScore?: unknown }).rankScore ?? 0);
            if (shouldUseRankScore && rightScore !== leftScore) return rightScore - leftScore;
            if (filters.sortBy === 'price-low') return Number((left as { price?: unknown }).price || 0) - Number((right as { price?: unknown }).price || 0);
            if (filters.sortBy === 'price-high') return Number((right as { price?: unknown }).price || 0) - Number((left as { price?: unknown }).price || 0);
            return new Date(String((right as { createdAt?: unknown }).createdAt || 0)).getTime() - new Date(String((left as { createdAt?: unknown }).createdAt || 0)).getTime();
        });
        const limited = merged.slice(0, limit);
        logger.info('[AdAggregationService] Location intelligence fallback applied', { locationHierarchyLevel, totalFound: merged.length, targetSize: limit, minimumTarget, searchState: effectiveFilters.state, searchLocationId: effectiveFilters.locationId, effectiveRadiusKm: safeRadius });
        return { data: limited, meta: { effectiveRadiusKm: safeRadius, locationHierarchyLevel }, pagination: { page, limit, hasMore: merged.length > limit, nextCursor: merged.length > limit ? String((limited[limited.length - 1] as { id?: unknown; _id?: unknown })?.id || (limited[limited.length - 1] as { id?: unknown; _id?: unknown })?._id || '') : undefined, cursor: cursor || null } };
    }
    return {
        data,
        meta: { effectiveRadiusKm: shouldUseGeo ? safeRadius : undefined },
        pagination: {
            page, limit,
            ...(useCursorStyleMeta ? { hasMore, nextCursor, cursor: cursor || null } : { total, hasMore: total > page * limit, totalPages: Math.ceil(total / limit) }),
        }
    };
};

// Ranking telemetry — sampled 5%
export async function recordRankingTelemetry(data: Record<string, unknown>[]) {
    if (Math.random() < 0.05 && data && data.length > 0) {
        setImmediate(() => {
            try {
                const eventId = uuidv4();
                const docs = (data as TelemetryAd[]).slice(0, 10).map((ad, index) => ({
                    eventId, adId: ad.id || ad._id, position: index + 1, rankScore: ad.rankScore || 0,
                    components: { qualityScore: ad.listingQualityScore || 0, distanceScore: ad.distanceScore || 0, freshnessScore: ad.freshnessScore || 0, popularityScore: ad.popularityScore || 0, sellerTrust: ad.sellerTrustSnapshot || 50 }
                }));
                RankingTelemetry.insertMany(docs).catch((err: Error) => logger.warn('Failed to insert ranking telemetry', { error: err.message }));
            } catch (error: any) { logger.warn('Ranking telemetry error', { error: error instanceof Error ? error.message : String(error) }); }
        });
    }
}

import { pLimit } from '../../../../../utils/pLimit';
import { AppError } from '../../../../../utils/AppError';
import { dispatchTemplatedNotification } from '../../../../notifications/application/NotificationService';
import Ad from '../../../../../models/Ad';
import type { AdminLogFn } from './types';
import {
    adminApproveListing, adminRejectListing, adminDeactivateListing,
    adminExpireListing, adminExtendListing,
} from './mutations';
import { validateListingId } from './helpers';

const ADMIN_BULK_CONCURRENCY = 5;

const executeAdminListingsBulkOperation = async <T>(
    ids: string[],
    actionFn: (id: string) => Promise<T>,
    includeResults: boolean = true
) => {
    if (!Array.isArray(ids) || ids.length === 0) throw new AppError('A non-empty list of listing IDs is required', 400);
    const limit = pLimit(ADMIN_BULK_CONCURRENCY);
    const tasks = ids.map(id =>
        limit(async () => {
            try {
                const updated = await actionFn(id);
                return { id, success: true as const, listing: (updated as any)?.listing || updated };
            } catch (error) {
                return { id, success: false as const, message: error instanceof Error ? error.message : String(error), statusCode: (error as any).statusCode || 500 };
            }
        })
    );
    const results = await Promise.all(tasks);
    const response: any = { processedCount: ids.length, successCount: results.filter(r => r.success).length, errorCount: results.filter(r => !r.success).length };
    if (includeResults) response.results = results;
    return response;
};

export const adminBulkApproveListings = async (ids: string[], actorId: string, logFn: AdminLogFn) =>
    executeAdminListingsBulkOperation(ids, id => adminApproveListing(id, actorId, logFn), true);

export const adminBulkRejectListings = async (ids: string[], actorId: string, rejectionReason: string, logFn: AdminLogFn) => {
    if (!rejectionReason || !rejectionReason.trim()) throw new AppError('Rejection reason is required for bulk rejection', 400);
    return executeAdminListingsBulkOperation(ids, id => adminRejectListing(id, actorId, rejectionReason, logFn), true);
};

export const adminBulkDeactivateListings = async (ids: string[], actorId: string, logFn: AdminLogFn) =>
    executeAdminListingsBulkOperation(ids, id => adminDeactivateListing(id, actorId, logFn), false);

export const adminBulkExpireListings = async (ids: string[], actorId: string, logFn: AdminLogFn) =>
    executeAdminListingsBulkOperation(ids, id => adminExpireListing(id, actorId, logFn), false);

export const adminBulkExtendListings = async (ids: string[], actorId: string, logFn: AdminLogFn) =>
    executeAdminListingsBulkOperation(ids, id => adminExtendListing(id, actorId, logFn), false);

export const adminBulkResendListingWarnings = async (ids: string[], actorId: string, logFn: AdminLogFn) => {
    return executeBulkWarningOperation(ids, actorId, logFn, {
        notificationTemplate: 'LISTING_EXPIRY_WARNING_3D',
        getNotificationData: (ad) => ({ title: ad.title, date: ad.expiresAt?.toLocaleDateString() || 'N/A' }),
        getNotificationOptions: (ad) => ({ adId: ad._id.toString() }),
        updateSet: { expiryWarningSentAt: new Date(), lastExpiryWarningChannel: 'in-app' },
        updateInc: { expiryWarningCount: 1 },
        logDomain: 'ExpiryWarning',
        getLogData: (adminId) => ({ entityType: 'Ad', adminId })
    });
};

export const adminBulkResendSpotlightWarnings = async (ids: string[], actorId: string, logFn: AdminLogFn) => {
    return executeBulkWarningOperation(ids, actorId, logFn, {
        validate: (ad) => (!ad.isSpotlight ? 'Listing is not in spotlight' : null),
        notificationTemplate: 'SPOTLIGHT_EXPIRY_WARNING_3D',
        getNotificationData: (ad) => ({ title: ad.title, date: ad.spotlightExpiresAt?.toLocaleDateString() || 'N/A' }),
        getNotificationOptions: (ad) => ({ adId: ad._id.toString(), type: 'spotlight' }),
        updateSet: { spotlightWarningSentAt: new Date(), lastExpiryWarningChannel: 'in-app' },
        updateInc: { spotlightWarningCount: 1 },
        logDomain: 'SpotlightPromotion',
        getLogData: (adminId) => ({ type: 'spotlight', adminId })
    });
};

type AdDocument = InstanceType<typeof Ad>;

const executeBulkWarningOperation = async (
    ids: string[],
    actorId: string,
    logFn: AdminLogFn,
    config: {
        validate?: (ad: AdDocument) => string | null;
        notificationTemplate: string;
        getNotificationData: (ad: AdDocument) => Record<string, any>;
        getNotificationOptions: (ad: AdDocument) => Record<string, any>;
        updateSet: Record<string, unknown>;
        updateInc: Record<string, number>;
        logDomain: string;
        getLogData: (actorId: string) => Record<string, unknown>;
    }
) => {
    if (!Array.isArray(ids) || ids.length === 0) throw new AppError('A non-empty list of listing IDs is required', 400);
    const ads = await Ad.find({ _id: { $in: ids } });
    const adsById = new Map(ads.map(a => [a._id.toString(), a]));
    const results: Array<{ id: string; success: boolean; message?: string }> = [];
    const bulkOps: Array<{
        updateOne: {
            filter: { _id: typeof ads[0]['_id'] };
            update: { $set: Record<string, unknown>; $inc?: Record<string, number> };
        };
    }> = [];

    for (const id of ids) {
        const ad = adsById.get(id);
        if (!ad) { results.push({ id, success: false, message: 'Listing not found' }); continue; }

        if (config.validate) {
            const errorMsg = config.validate(ad);
            if (errorMsg) { results.push({ id, success: false, message: errorMsg }); continue; }
        }

        try {
            await dispatchTemplatedNotification(
                ad.sellerId.toString(),
                'SYSTEM',
                config.notificationTemplate,
                config.getNotificationData(ad),
                config.getNotificationOptions(ad)
            );

            bulkOps.push({
                updateOne: {
                    filter: { _id: ad._id },
                    update: { $set: config.updateSet, $inc: config.updateInc }
                }
            });

            await logFn('expiry_warning_resent', config.logDomain as any, id, config.getLogData(actorId));
            results.push({ id, success: true });
        } catch (error) {
            results.push({ id, success: false, message: error instanceof Error ? error.message : String(error) });
        }
    }

    if (bulkOps.length > 0) await Ad.bulkWrite(bulkOps, { ordered: false });
    return { processedCount: ids.length, successCount: results.filter(r => r.success).length, errorCount: results.filter(r => !r.success).length, results };
};

