        'proactive_expiry_warning',
        {},
        {
            repeat: { pattern: '0 8 * * *' }, // Run daily at 8:00 AM
            removeOnComplete: true,
            removeOnFail: 1000,
        },
        correlationId
    );
};

import { CATALOG_APPROVAL_STATUS } from '@esparex/shared';
import Category from '../models/Category';
