export const adminGetLocationAnalyticsData = async (reqQuery: Record<string, unknown>) => {
    const sixMonthsAgo = new Date();
    sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

    const cityFilter = typeof reqQuery.city === 'string' ? reqQuery.city.trim() : '';
    const districtFilter = typeof reqQuery.district === 'string' ? reqQuery.district.trim() : '';
    const stateFilter = typeof reqQuery.state === 'string' ? reqQuery.state.trim() : '';
    const countryFilter = typeof reqQuery.country === 'string' ? reqQuery.country.trim() : '';

    const scope = await resolveLocationScope({
        city: cityFilter || undefined,
        district: districtFilter || undefined,
        state: stateFilter && stateFilter !== 'all' ? stateFilter : undefined,
        country: countryFilter && countryFilter !== 'all' ? countryFilter : undefined,
    });
    const locationScopeIds = scope.locationIds;

    const buildScopedLocationQuery = (extra: Record<string, unknown> = {}) => {
        if (locationScopeIds === undefined || locationScopeIds === null) {
            return { isActive: true, ...extra };
        }
        if (locationScopeIds.length === 0) {
            return { _id: { $in: [] }, ...extra };
        }
        return {
            isActive: true,
            ...extra,
            $or: [
                { _id: { $in: locationScopeIds } },
                { path: { $in: locationScopeIds } },
            ],
        };
    };

    const buildScopedAdQuery = (extra: Record<string, unknown> = {}) => {
        if (locationScopeIds === undefined || locationScopeIds === null) {
            return extra;
        }
        if (locationScopeIds.length === 0) {
            return { _id: { $in: [] }, ...extra };
        }
        return {
            ...extra,
            $or: [
                { 'location.locationId': { $in: locationScopeIds } },
                { locationPath: { $in: locationScopeIds } },
            ],
        };
    };

    const buildScopedUserQuery = (extra: Record<string, unknown> = {}) => {
        if (locationScopeIds === undefined || locationScopeIds === null) {
            return extra;
        }
        if (locationScopeIds.length === 0) {
            return { _id: { $in: [] }, ...extra };
        }

        const orQuery: Array<Record<string, unknown>> = [
            { locationId: { $in: locationScopeIds } },
            { 'location.locationId': { $in: locationScopeIds } },
        ];

        if (cityFilter) {
            orQuery.push({ 'location.city': new RegExp(`^${escapeRegExp(cityFilter)}$`, 'i') });
        }
        if (stateFilter && stateFilter !== 'all') {
            orQuery.push({ 'location.state': new RegExp(`^${escapeRegExp(stateFilter)}$`, 'i') });
        }

        return {
            ...extra,
            $or: orQuery,
        };
    };

    if (Array.isArray(locationScopeIds) && locationScopeIds.length === 0) {
        return {
            totalLocations: 0,
            totalAds: 0,
            totalUsers: 0,
            topCities: [],
            adsByState: [],
            hotZones: [],
            monthlyTrends: [],
        };
    }

    const hotZoneQuery: Record<string, unknown> = {
        isHotZone: true,
        ...(Array.isArray(locationScopeIds) ? { locationId: { $in: locationScopeIds } } : {}),
    };

    const {
        totalLocations,
        totalAds,
        totalUsers,
        adsByLocationAgg,
        monthlyAds,
        monthlyUsers,
        monthlyLocs,
        topHotZonesRaw,
    } = await getLocationAnalyticsRawData({
        sixMonthsAgo,
        buildScopedLocationQuery,
        buildScopedAdQuery,
        buildScopedUserQuery,
        hotZoneQuery,
    });

    const hotZoneLocationIds = topHotZonesRaw.map((zone: any) => zone.locationId);
    const hotZoneLocations = await getHotZoneLocations(hotZoneLocationIds.map(String));
    const hotZoneHierarchyMap = await loadHierarchyMapForLocations(hotZoneLocations);
    const hotZoneLocationMap = new Map(
        hotZoneLocations.map((location: any) => [String(location._id), location])
    );
    const hotZones = topHotZonesRaw.map((zone: any) => {
        const location = hotZoneLocationMap.get(String(zone.locationId));
        const summary = location ? buildLocationSummary(location, hotZoneHierarchyMap) : undefined;
        return {
            _id: String(zone._id),
            city: summary?.city ?? '',
            state: summary?.state ?? '',
            popularityScore: zone.popularityScore ?? 0,
            isHotZone: true,
        };
    });

    // Format Monthly Trends
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const trends = [];
    for (let i = 0; i < 6; i++) {
        const d = new Date();
        d.setMonth(d.getMonth() - (5 - i));
        const m = d.getMonth() + 1;
        const y = d.getFullYear();

        const ads = monthlyAds.find((a: any) => a._id.month === m && a._id.year === y)?.count || 0;
        const users = monthlyUsers.find((u: any) => u._id.month === m && u._id.year === y)?.count || 0;
        const locs = monthlyLocs.find((l: any) => l._id.month === m && l._id.year === y)?.count || 0;

        trends.push({
            month: monthNames[m - 1],
            adsPosted: ads,
            activeUsers: users,
            newLocations: locs
        });
    }

    const adsByLocationIds = adsByLocationAgg
        .map((entry: any) => entry?._id as string | undefined)
        .filter((value: string | undefined): value is string => Boolean(value))
        .map((value: string) => String(value));
    const analyticsLocations = await getAnalyticsLocations(adsByLocationIds);
    const analyticsHierarchyMap = await loadHierarchyMapForLocations(analyticsLocations);
    const analyticsLocationMap = new Map(
        analyticsLocations.map((location: any) => [String(location._id), location])
    );

    const topCityMap = new Map<string, { _id: string; city: string; state: string; adsCount: number }>();
    const adsByStateMap = new Map<string, { _id: string; count: number }>();

    for (const entry of adsByLocationAgg as any[]) {
        const location = analyticsLocationMap.get(String(entry._id));
        if (!location) continue;

        const summary = buildLocationSummary(location, analyticsHierarchyMap);
        const count = typeof entry?.adsCount === 'number' ? entry.adsCount : Number(entry?.adsCount || 0);

        if (summary.city && summary.state && summary.level !== 'state' && summary.level !== 'country') {
            const cityKey = `${summary.city.toLowerCase()}::${summary.state.toLowerCase()}`;
            const existingCity = topCityMap.get(cityKey);
            if (existingCity) {
                existingCity.adsCount += count;
            } else {
                topCityMap.set(cityKey, {
                    _id: cityKey,
                    city: summary.city,
                    state: summary.state,
                    adsCount: count,
                });
            }
        }

        const stateLabel = normalizeStateLabel(summary.state);
        const stateKey = stateLabel.toLowerCase();
        const existing = adsByStateMap.get(stateKey);
        if (existing) {
            existing.count += count;
            continue;
        }
        adsByStateMap.set(stateKey, { _id: stateLabel, count });
    }
    const topCities = Array.from(topCityMap.values())
        .sort((a, b) => b.adsCount - a.adsCount)
        .slice(0, 10);
    const adsByState = Array.from(adsByStateMap.values()).sort((a, b) => b.count - a.count);

    return {
        totalLocations,
        totalAds,
        totalUsers,
        topCities,
        adsByState,
        hotZones,
        monthlyTrends: trends.map(t => ({
            month: t.month,
            ads: t.adsPosted,
            users: t.activeUsers,
        })),
    };
};

import { z } from 'zod';
import logger from '../utils/logger';
import { env } from '../config/env';
import { AIProviderFactory } from './ai/AIProviderFactory';
import { getAiConfig } from '../config/ai';
import { generateListingPromptV1, identifyDevicePromptV1 } from '../prompts/listings/v1';
import { moderateAdPromptV1 } from '../prompts/moderation/v1';
import { MAX_AD_TITLE_CHARS, MAX_AD_DESCRIPTION_CHARS } from '@esparex/contracts';
import { AiErrorCode } from '@esparex/contracts/v1/common/enums';
import { AIProviderError } from './ai/types';
import { getCache, setCache } from '../utils/redisCache';

export type AIRequestType = 'identify' | 'generate' | 'moderate';

export type AIRequestBody = {
    type?: string;
    context?: Record<string, unknown>;
    image?: string;
};

export type AIServiceSuccess = {
    ok: true;
    data: Record<string, unknown>;
};

export type AIServiceFailure = {
    ok: false;
    status: number;
    error: string;
    code?: string;
    details?: Record<string, unknown>;
};

export type AIServiceResult = AIServiceSuccess | AIServiceFailure;

type ExecuteAiRequestInput = {
    type: AIRequestType;
    context: Record<string, unknown>;
    image?: string;
    contextText: string;
};

export const AI_REQUEST_TIMEOUT_MS = env.AI_REQUEST_TIMEOUT_MS ?? 30000;
export const AI_MAX_IMAGE_BYTES = env.AI_MAX_IMAGE_BYTES ?? (4 * 1024 * 1024);

const AI_QUOTA_CACHE_KEY = 'sys:ai:quota_exhausted';
const AI_QUOTA_COOLDOWN_SECONDS = 60;

export const isAIRequestType = (value: unknown): value is AIRequestType =>
    value === 'identify' || value === 'generate' || value === 'moderate';

export const getAiContext = (body: AIRequestBody): {
    context: Record<string, unknown>;
    image?: string;
    contextText: string;
} => {
    const context = body?.context && typeof body.context === 'object' ? body.context : {};
    const rootImage = typeof body?.image === 'string' ? body.image : undefined;
    const contextImage = typeof context.image === 'string' ? context.image : undefined;
    const image = rootImage || contextImage;
    const contextText = typeof context.text === 'string' ? context.text : '';

    return { context, image, contextText };
};

const toServiceFailure = (response: AIServiceFailure): AIServiceFailure => response;

const mapProviderError = (error: unknown): AIServiceFailure => {
    if ((error as AIProviderError).code) {
        const providerError = error as AIProviderError;
        const code = providerError.code;
        const status = providerError.status || 502;

        switch (code) {
            case 'Timeout': return { ok: false, status: 504, error: 'AI provider timeout', code: AiErrorCode.AI_PROVIDER_TIMEOUT };
            case 'RateLimit': return { ok: false, status: 429, error: 'AI quota exceeded or rate limit reached', code: AiErrorCode.AI_QUOTA_EXHAUSTED };
            case 'Authentication': return { ok: false, status: 500, error: 'AI provider authentication failed (Invalid API Key)', code: AiErrorCode.AI_INVALID_API_KEY };
            case 'ServiceUnavailable': return { ok: false, status: 503, error: 'AI provider unavailable', code: AiErrorCode.AI_UNAVAILABLE };
            case 'Validation': return { ok: false, status: 502, error: 'AI Provider Validation Error', code: AiErrorCode.AI_INVALID_JSON };
        }
        return { ok: false, status, error: providerError.message, code: AiErrorCode.AI_PROVIDER_ERROR };
    }
    return { ok: false, status: 502, error: error instanceof Error ? error.message : 'Unknown AI Error', code: AiErrorCode.AI_UNKNOWN_ERROR };
};

export const getStatus = async (): Promise<{ available: boolean; reason: string | null; retryAfter: number }> => {
    const config = await getAiConfig();
    if (!config.geminiApiKey && !config.openAiApiKey) {
        return { available: false, reason: AiErrorCode.AI_UNAVAILABLE, retryAfter: 0 };
    }

    const quotaExhausted = await getCache(AI_QUOTA_CACHE_KEY);
    if (quotaExhausted) {
        return { available: false, reason: AiErrorCode.AI_QUOTA_EXHAUSTED, retryAfter: AI_QUOTA_COOLDOWN_SECONDS };
    }

    return { available: true, reason: null, retryAfter: 0 };
};

export const executeAiRequest = async (input: ExecuteAiRequestInput): Promise<AIServiceResult> => {
    const { type, context, image, contextText } = input;

    if (type === 'generate' && !context.brand && !context.model) {
        return toServiceFailure({ ok: false, status: 400, error: 'Brand and Model context are required for generation' });
    }

    const status = await getStatus();
    if (!status.available) {
        return toServiceFailure({ 
            ok: false, 
            status: status.reason === AiErrorCode.AI_QUOTA_EXHAUSTED ? 429 : 503, 
            error: 'AI service unavailable',
            code: status.reason || AiErrorCode.AI_UNAVAILABLE
        });
    }

    const config = await getAiConfig();
    try {
        const provider = AIProviderFactory.create(config.provider);

        if (type === 'identify') {
            const prompt = identifyDevicePromptV1(contextText);
            const schema = z.object({
                brand: z.string(),
                model: z.string(),
                confidence: z.number().optional()
            });

            const result = await provider.generateStructured(prompt, schema, { timeoutMs: AI_REQUEST_TIMEOUT_MS });

            return { ok: true, data: result as Record<string, unknown> };
        }

        if (type === 'generate') {
            const prompt = generateListingPromptV1(context);
            const schema = z.object({
                title: z.string().max(MAX_AD_TITLE_CHARS),
                description: z.string().max(MAX_AD_DESCRIPTION_CHARS)
            });

            const result = await provider.generateStructured(prompt, schema, { timeoutMs: AI_REQUEST_TIMEOUT_MS });
            return { ok: true, data: result as Record<string, unknown> };
        }

        if (type === 'moderate') {
            const prompt = moderateAdPromptV1(contextText);
            const schema = z.object({
                safe: z.boolean(),
                reason: z.string().nullable()
            });

            const result = await provider.generateStructured(prompt, schema, { timeoutMs: AI_REQUEST_TIMEOUT_MS });
            return { ok: true, data: result as Record<string, unknown> };
        }

        return toServiceFailure({ ok: false, status: 400, error: 'Invalid AI request type' });
    } catch (error) {
        logger.error('[AiService] executeAiRequest error', { error });
        const serviceFailure = mapProviderError(error);

        if (serviceFailure.code === AiErrorCode.AI_QUOTA_EXHAUSTED) {
            await setCache(AI_QUOTA_CACHE_KEY, '1', AI_QUOTA_COOLDOWN_SECONDS);
        }

        return serviceFailure;
    }
};

import Business from '../../models/Business';
