const ADMIN_STATES_CACHE_TTL_SECONDS = 300;

export const adminGetDistinctStates = async () => {
    const cachedStates = await getCache<string[]>(ADMIN_STATES_CACHE_KEY);
    if (Array.isArray(cachedStates)) return cachedStates;
    const states = await getDistinctStateLocations();
    const sorted = states.map((e) => resolveStringField(e.name)).filter((v): v is string => Boolean(v)).sort((a, b) => a.localeCompare(b));
    await setCache(ADMIN_STATES_CACHE_KEY, sorted, ADMIN_STATES_CACHE_TTL_SECONDS);
    return sorted;
};

export const adminReverseGeocode = async (latRaw: string, lngRaw: string) => {
    const lat = parseFloat(latRaw), lng = parseFloat(lngRaw);
    if (isNaN(lat) || isNaN(lng)) throw new AppError('Coordinates (lat, lng) are required.', 400);
    return getReverseGeocodeMatch(lat, lng);
};

export const adminGetAllLocations = async (query: AdminLocationPaginationQuery) => {
    const { page, limit, skip } = parsePaginationParams(query);
    const search = typeof query.q === 'string' ? query.q.trim() : undefined;
    const status = typeof query.status === 'string' ? query.status : undefined;
    const state = typeof query.state === 'string' ? query.state : undefined;
    const level = typeof query.level === 'string' ? query.level : undefined;
    const dbQuery: Record<string, unknown> = {};
    if (status === 'active') dbQuery.isActive = true;
    if (status === 'inactive') dbQuery.isActive = false;
    if (level && level !== 'all') dbQuery.level = level;
    if (search) {
        const escaped = escapeRegExp(search);
        dbQuery.$or = [{ name: { $regex: escaped, $options: 'i' } }, { normalizedName: { $regex: escaped, $options: 'i' } }, { slug: { $regex: escaped, $options: 'i' } }, { aliases: { $regex: escaped, $options: 'i' } }];
    }
    const scope = state && state !== 'all' ? await resolveLocationScope({ state }) : { locationIds: null as mongoose.Types.ObjectId[] | null };
    Object.assign(dbQuery, toScopeQuery(scope.locationIds));
    const { locations, total } = await getLocationsPaginated(dbQuery, skip, limit);
    const items = await hydrateLocationResponses(locations as CanonicalLocationDoc[]);
    return { items, total, page, limit };
};

export const adminCreateStateLocation = async (body: AdminCreateLocationBody) => {
    const stateName = resolveStringField(body.name) || resolveStringField(body.state);
    if (!stateName) throw new AppError('State name is required.', 400);
    return adminCreateLocation({ ...body, name: stateName, level: 'state', parentId: null });
};

export const adminCreateCityLocation = async (body: AdminCreateLocationBody) => {
    const stateId = resolveStringField(body.stateId);
    const cityName = resolveStringField(body.name) || resolveStringField(body.city);
    if (!stateId) throw new AppError('stateId is required.', 400);
    if (!cityName) throw new AppError('City name is required.', 400);
    if (!mongoose.Types.ObjectId.isValid(stateId)) throw new AppError('Invalid stateId.', 400);
    const stateAnchor = await findLocationByIdLean<CanonicalLocationDoc>(stateId, '_id name country level parentId path');
    const stateSummary = await resolveLocationSummary(stateAnchor);
    if (!stateSummary?.state) throw new AppError('State not found.', 404);
    return adminCreateLocation({ ...body, name: cityName, country: resolveStringField(body.country) || stateSummary.country || 'Unknown', level: 'city', parentId: stateId });
};

export const adminCreateAreaLocation = async (body: AdminCreateLocationBody) => {
    const cityId = resolveStringField(body.cityId);
    const areaName = resolveStringField(body.name) || resolveStringField(body.area);
    if (!cityId) throw new AppError('cityId is required.', 400);
    if (!areaName) throw new AppError('Area name is required.', 400);
    if (!mongoose.Types.ObjectId.isValid(cityId)) throw new AppError('Invalid cityId.', 400);
    const cityAnchor = await findLocationByIdLean<CanonicalLocationDoc>(cityId, '_id name country level parentId path');
    const citySummary = await resolveLocationSummary(cityAnchor);
    if (!citySummary?.city || !citySummary?.state) throw new AppError('City not found.', 404);
    return adminCreateLocation({ ...body, name: areaName, country: resolveStringField(body.country) || citySummary.country || 'Unknown', level: 'area', parentId: cityId });
};

export const adminCreateLocation = async (createBody: AdminCreateLocationBody) => {
    const { country, latitude, longitude, isActive, level, name } = createBody;
    const coords = normalizeCoordinates({ lat: latitude, lng: longitude });
    if (!coords || (coords.coordinates[0] === 0 && coords.coordinates[1] === 0)) throw new AppError('Valid map coordinates are required.', 400);
    const displayName = resolveStringField(name);
    if (!displayName) throw new AppError('Location name is required.', 400);
    const requestedLevel = resolveStringField(level)?.toLowerCase();
    const finalLevel: 'country' | 'state' | 'district' | 'city' | 'area' | 'village' = requestedLevel === 'country' || requestedLevel === 'state' || requestedLevel === 'district' || requestedLevel === 'city' || requestedLevel === 'area' || requestedLevel === 'village' ? requestedLevel : 'city';
    const explicitParentId = resolveStringField(createBody.parentId);
    let parentLocation: { _id: unknown; level?: string; path?: unknown } | null = null;
    if (explicitParentId) {
        if (!/^[a-f\d]{24}$/i.test(explicitParentId)) throw new AppError('Invalid parentId.', 400);
        parentLocation = await findActiveParentById(explicitParentId);
        if (!parentLocation) throw new AppError('Parent location not found.', 404);
    } else {
        parentLocation = await resolveParentLocation({ level: finalLevel, country: resolveStringField(country) || 'Unknown', state: resolveStringField(createBody.state), district: resolveStringField(createBody.district), city: resolveStringField(createBody.city) || displayName });
    }
    const parentSummary = parentLocation ? await resolveLocationSummary(parentLocation as CanonicalLocationDoc) : null;
    const normalizedCountry = resolveStringField(country) || parentSummary?.country || 'Unknown';
    const slug = safeSlugify([displayName, parentSummary?.state, normalizedCountry].filter((p): p is string => Boolean(p)).join('-'));
    const existing = await findDuplicateLocation(displayName, normalizedCountry, finalLevel, parentLocation?._id);
    if (existing) throw new AppError('Location already exists in this state.', 400);
    const locationId = generateLocationId();
    const location = await createLocationRecord({ _id: locationId, name: displayName, country: normalizedCountry, coordinates: coords, level: finalLevel, parentId: parentLocation?._id || null, path: buildHierarchyPath(locationId, parentLocation as any), slug, isActive: isActive !== undefined ? isActive : true, priority: 0 });
    await invalidateLocationStateCache();
    const [response] = await hydrateLocationResponses([location.toObject()]);
    return response;
};

export const adminUpdateLocation = async (id: string, updateBody: AdminUpdateLocationBody) => {
    const { country, latitude, longitude, isActive, level, name } = updateBody;
    const nextCountry = resolveStringField(country);
    const nextName = resolveStringField(name);
    const location = await findLocationById(id);
    if (!location) throw new AppError('Location not found', 404);
    if (level) { const nl = resolveStringField(level)?.toLowerCase(); if (nl === 'country' || nl === 'state' || nl === 'district' || nl === 'city' || nl === 'area' || nl === 'village') location.level = nl; }
    if (nextCountry) location.country = nextCountry;
    if (nextName) location.name = nextName;
    const parentIdFromBody = updateBody.parentId;
    const hasParentMutation = parentIdFromBody !== undefined;
    if (hasParentMutation) {
        if (parentIdFromBody === undefined || parentIdFromBody === '') { location.parentId = undefined as any; }
        else { const pid = resolveStringField(parentIdFromBody); if (!pid || !/^[a-f\d]{24}$/i.test(pid)) throw new AppError('Invalid parentId.', 400); const pe = await locationExists(pid); if (!pe) throw new AppError('Parent location not found.', 404); location.parentId = new mongoose.Types.ObjectId(pid); }
    }
    if (latitude !== undefined && longitude !== undefined) {
        const coords = normalizeCoordinates({ lat: latitude, lng: longitude });
        if (!coords || (coords.coordinates[0] === 0 && coords.coordinates[1] === 0)) throw new AppError('Valid map coordinates are required.', 400);
        location.coordinates = coords;
    }
    if (isActive !== undefined) location.isActive = Boolean(isActive);
    if (name || country || level || hasParentMutation) {
        let parentLocation: any = null;
        if (location.parentId) parentLocation = await findLocationParent(location.parentId);
        location.path = buildHierarchyPath(location._id, parentLocation);
        const ps = parentLocation ? await resolveLocationSummary(parentLocation) : null;
        location.slug = safeSlugify([location.name, ps?.state, location.country || 'unknown'].filter((p): p is string => Boolean(p)).join('-'));
    }
    await saveLocation(location);
    await invalidateLocationStateCache();
    const [response] = await hydrateLocationResponses([location.toObject()]);
    return response;
};

export const adminToggleLocationStatus = async (id: string) => {
    const location = await findLocationById(id);
    if (!location) throw new AppError('Location not found', 404);
    location.isActive = !location.isActive;
    await saveLocation(location);
    await invalidateLocationStateCache();
    return normalizeLocationResponse(location);
};

export const adminDeleteLocation = async (id: string, logFn: AdminLogFn) => {
    const location = await findLocationById(id);
    if (!location) throw new AppError('Location not found', 404);
    const locationSummary = await resolveLocationSummary(location.toObject());
    const adUsageQuery: any = { $or: [{ 'location.locationId': id }] };
    const userUsageQuery: any = { $or: [{ locationId: id }] };
    if (locationSummary?.city && locationSummary?.state) { adUsageQuery.$or.push({ 'location.city': locationSummary.city, 'location.state': locationSummary.state }); userUsageQuery.$or.push({ 'location.city': locationSummary.city, 'location.state': locationSummary.state }); }
    const [adsCount, usersCount] = await Promise.all([countAdsForLocation(adUsageQuery), countUsersForLocation(userUsageQuery)]);
    if (adsCount > 0 || usersCount > 0) throw new AppError(`Cannot delete location "${locationSummary?.name || location.name}". It is currently used by ${adsCount} ads and ${usersCount} users. Consider deactivating it instead.`, 409);
    await softDeleteLocation(location);
    await invalidateLocationStateCache();
    await logFn('DELETE_LOCATION', 'Location', id, { name: locationSummary?.name || location.name, city: locationSummary?.city, state: locationSummary?.state });
    return true;
};

/**
 * Moderation Model Registry (PR 1)
 *
 * Provides lifecycle management, registration, and resolution for AI moderation model adapters.
 * Does NOT perform inference directly; delegates prediction to registered ModelAdapters.
 */
import { ModelAdapter, ModelAdapterMetadata, ModelType } from './ModelAdapter';

export class DuplicateModelRegistrationError extends Error {
    constructor(modelId: string) {
        super(`Model adapter with ID "${modelId}" is already registered in ModerationModelRegistry.`);
        this.name = 'DuplicateModelRegistrationError';
    }
}

export class ModelNotFoundError extends Error {
    constructor(modelId: string) {
        super(`Model adapter with ID "${modelId}" was not found in ModerationModelRegistry.`);
        this.name = 'ModelNotFoundError';
    }
}

export class ModerationModelRegistry {
    private adapters: Map<string, ModelAdapter<any, any>> = new Map();

    /**
     * Registers a model adapter in the registry.
     * Does NOT automatically call initialize() on registration (explicit loading strategy).
     * @throws DuplicateModelRegistrationError if an adapter with the same modelId is already registered.
     */
    registerAdapter<TInput, TOutput>(adapter: ModelAdapter<TInput, TOutput>): void {
        if (this.adapters.has(adapter.modelId)) {
            throw new DuplicateModelRegistrationError(adapter.modelId);
        }
        this.adapters.set(adapter.modelId, adapter);
    }

    /**
     * Checks whether an adapter with the specified modelId exists in the registry.
     */
    hasAdapter(modelId: string): boolean {
        return this.adapters.has(modelId);
    }

    /**
     * Resolves a registered adapter by its unique modelId.
     * @throws ModelNotFoundError if no adapter matches the modelId.
     */
    getAdapter<TInput = unknown, TOutput = unknown>(modelId: string): ModelAdapter<TInput, TOutput> {
        const adapter = this.adapters.get(modelId);
        if (!adapter) {
            throw new ModelNotFoundError(modelId);
        }
        return adapter as ModelAdapter<TInput, TOutput>;
    }

    /**
     * Resolves all registered adapters matching the specified ModelType category.
     */
    getAdaptersByType<TInput = unknown, TOutput = unknown>(
        modelType: ModelType
    ): ModelAdapter<TInput, TOutput>[] {
        const results: ModelAdapter<TInput, TOutput>[] = [];
        for (const adapter of this.adapters.values()) {
            if (adapter.modelType === modelType) {
                results.push(adapter as ModelAdapter<TInput, TOutput>);
            }
        }
        return results;
    }

    /**
     * Lists diagnostic metadata for all registered models in the registry.
     */
    listRegisteredModels(): ModelAdapterMetadata[] {
        return Array.from(this.adapters.values()).map((adapter) => ({
            modelId: adapter.modelId,
            modelType: adapter.modelType,
            version: adapter.version,
            isLoaded: adapter.isLoaded(),
            initializedAt: adapter.getInitializedAt(),
        }));
    }

    /**
     * Unregisters an adapter by modelId, disposing it if loaded.
     */
    async unregisterAdapter(modelId: string): Promise<void> {
        const adapter = this.adapters.get(modelId);
        if (adapter) {
            if (adapter.isLoaded()) {
                await adapter.dispose();
            }
            this.adapters.delete(modelId);
        }
    }

    /**
     * Disposes all registered model adapters and clears the registry.
     */
    async disposeAll(): Promise<void> {
        for (const adapter of this.adapters.values()) {
            try {
                if (adapter.isLoaded()) {
                    await adapter.dispose();
                }
            } catch {
                // Ignore disposal errors during bulk cleanup
            }
        }
        this.adapters.clear();
    }
}

import { GoogleGenAI } from '@google/genai';
import { z } from 'zod';
import { AIProvider } from '../AIProvider';
import { AIResult, AIStreamChunk, GenerateTextOptions, HealthCheckResult, AIProviderError } from '../types';
import { getAiConfig } from '../../../config/ai';
import { withTimeout } from '../../../utils/resilience';

export class GeminiProviderError extends Error implements AIProviderError {
    code: 'Authentication' | 'RateLimit' | 'Timeout' | 'Validation' | 'ServiceUnavailable' | 'Unknown';
    provider = 'gemini';
    status?: number;
    details?: unknown;

    constructor(message: string, code: AIProviderError['code'], status?: number, details?: unknown) {
        super(message);
        this.name = 'GeminiProviderError';
        this.code = code;
        this.status = status;
        this.details = details;
    }
}

export class GeminiProvider implements AIProvider {
    private clientPromise: Promise<GoogleGenAI>;
    private modelNamePromise: Promise<string>;

    constructor() {
        const configPromise = getAiConfig();
        this.clientPromise = configPromise.then((c: any) => new GoogleGenAI({ apiKey: c.geminiApiKey }));
        this.modelNamePromise = configPromise.then((c: any) => c.geminiModel);
    }

    private mapError(error: unknown): GeminiProviderError {
        // Simple error mapping for demonstration
        if (error instanceof Error) {
            if (error.message.includes('Timeout')) {
                return new GeminiProviderError('Gemini request timed out', 'Timeout');
            }
            if (error.message.includes('401') || error.message.includes('403')) {
                return new GeminiProviderError('Authentication failed', 'Authentication', 401);
            }
            if (error.message.includes('429')) {
                return new GeminiProviderError('Rate limit exceeded', 'RateLimit', 429);
            }
        }
        return new GeminiProviderError(error instanceof Error ? error.message : 'Unknown error', 'Unknown');
    }

    async generateText(prompt: string, options?: GenerateTextOptions): Promise<AIResult> {
        const startTime = Date.now();
        try {
            const client = await this.clientPromise;
            const model = await this.modelNamePromise;
            const config = await getAiConfig();

            const response = await withTimeout(
                client.models.generateContent({
                    model,
                    contents: prompt,
                    config: {
                        maxOutputTokens: options?.maxTokens ?? config.maxOutputTokens,
                        temperature: options?.temperature ?? config.temperature,
                        topP: options?.topP ?? config.topP,
                    }
                }),
                options?.timeoutMs ?? config.timeoutMs,
                'Gemini generateText'
            );

            return {
                provider: 'gemini',
                model,
                text: response.text || '',
                usage: response.usageMetadata ? {
                    promptTokens: response.usageMetadata.promptTokenCount ?? 0,
                    completionTokens: response.usageMetadata.candidatesTokenCount ?? 0,
                    totalTokens: response.usageMetadata.totalTokenCount ?? 0,
                } : undefined,
                latency: Date.now() - startTime,
                cached: false
            };
        } catch (error) {
            throw this.mapError(error);
        }
    }

    async generateStructured<T>(prompt: string, schema: z.ZodSchema<T>, options?: GenerateTextOptions): Promise<T> {
        // Structured output usually uses responseSchema or parsing from text. 
        // For simplicity, we just prompt to return JSON and parse it.
        const res = await this.generateText(`${prompt}\n\nReturn strict JSON that matches the required schema.`, options);
        try {
            const start = res.text.indexOf('{');
            const end = res.text.lastIndexOf('}');
            const jsonText = start !== -1 && end !== -1 ? res.text.slice(start, end + 1) : res.text;
            return schema.parse(JSON.parse(jsonText));
        } catch (err) {
            throw new GeminiProviderError('Failed to parse structured output', 'Validation');
        }
    }

    async *streamText(prompt: string, options?: GenerateTextOptions): AsyncIterable<AIStreamChunk> {
        try {
            const client = await this.clientPromise;
            const model = await this.modelNamePromise;
            const config = await getAiConfig();

            const responseStream = await client.models.generateContentStream({
                model,
                contents: prompt,
                config: {
                    maxOutputTokens: options?.maxTokens ?? config.maxOutputTokens,
                    temperature: options?.temperature ?? config.temperature,
                    topP: options?.topP ?? config.topP,
                }
            });

            for await (const chunk of responseStream) {
                if (chunk.text) {
                    yield { text: chunk.text };
                }
            }
        } catch (error) {
            throw this.mapError(error);
        }
    }

    async healthCheck(): Promise<HealthCheckResult> {
        const startTime = Date.now();
        let model = 'unknown';
        try {
            model = await this.modelNamePromise;
            await this.generateText('ping', { maxTokens: 5, timeoutMs: 5000 });
            return {
                healthy: true,
                provider: 'gemini',
                model,
                latency: Date.now() - startTime
            };
        } catch (error) {
            return {
                healthy: false,
                provider: 'gemini',
                model,
                latency: Date.now() - startTime,
                error: error instanceof Error ? error.message : String(error)
            };
        }
    }
}

import { getListingRepository } from '../../composition/listings';
import { LISTING_STATUS } from '@esparex/contracts';
import { ACTOR_TYPE } from '@esparex/contracts';
import { mutateStatusesBulk } from './StatusMutationService';
import { lifecycleEvents } from '../../events';
import logger from '../../utils/logger';

export type ListingExpirySweepResult = {
    expiredCount: number;
    touchedCount: number;
    listingIds: string[];
};

export class ListingExpiryService {
    static async runSweep(now: Date = new Date()): Promise<ListingExpirySweepResult> {
        const expiringListings = await getListingRepository().find({
            status: LISTING_STATUS.LIVE,
            expiresAt: { $lte: now } as any,
            isDeleted: false as any,
        });

        if (expiringListings.length === 0) {
            return {
                expiredCount: 0,
                touchedCount: 0,
                listingIds: [],
            };
        }

        const listingIds = expiringListings
            .map((doc) => doc.id)
            .filter((id) => id.length > 0);

        await getListingRepository().updateMany(
            { ids: listingIds },
            {
                isSpotlight: false,
                isChatLocked: true,
            }
        );

        const expiredCount = await mutateStatusesBulk(
            'ad',
            listingIds,
            LISTING_STATUS.EXPIRED,
            { type: ACTOR_TYPE.SYSTEM, id: 'listing_expiry_cron' },
            'Automated expiry'
        );

        await lifecycleEvents.dispatch('listing.expired.bulk', {
            count: expiredCount,
            listingIds,
            source: 'ListingExpiryService',
        });

        const { getListingsCache } = await import('../../composition/listings');
        await getListingsCache().invalidateAdFeedCaches();

        logger.info('[ListingExpiryService] Expiry sweep completed', {
            expiredCount,
            touchedCount: listingIds.length,
        });

        return {
            expiredCount,
            touchedCount: listingIds.length,
            listingIds,
        };
    }
}

import mongoose, { ClientSession } from 'mongoose';
import { pLimit } from '../../utils/pLimit';
import { 
    validateTransition as validateLifecycleTransition, 

    resolveLifecycleDomain,
    type ValidDomain 
} from './LifecycleGuard';
import { enforceLifecycleMutationPolicy } from './LifecyclePolicyGuard';
import StatusHistory from '../../models/StatusHistory';
import AdminMetrics from '../../models/AdminMetrics';
import logger from '../../utils/logger';
import { ActorMetadata, ACTOR_TYPE, LISTING_STATUS, BusinessErrorCode } from '@esparex/contracts';
import { AppError } from '../../shared-kernel/errors/AppError';
import { lifecycleEvents } from '../../events';

// Import domain models
import Ad from '../../models/Ad';
import User from '../../models/User';
import Business from '../../models/Business';

export type { ValidDomain };

export interface MutationRequest {
    domain: ValidDomain;
    entityId: string | mongoose.Types.ObjectId;
    toStatus: string;
    actor: ActorMetadata;
    reason?: string;
    patch?: Record<string, unknown>; // Status-specific updates like soldAt, rejectionReason
    metadata?: Record<string, unknown>; // Audit metadata
    session?: unknown; // Optional external session
}


const toLower = (value: unknown): string =>
    typeof value === 'string' ? value.trim().toLowerCase() : '';

const isListingLifecycleDomain = (domain: ValidDomain): boolean =>
    domain === 'ad' || domain === 'service' || domain === 'spare_part_listing';

const isModerationDeactivationAction = (metadata?: Record<string, unknown>): boolean => {
    const action = toLower(metadata?.action);
    return action === 'moderation_deactivate' || action === 'moderation_soft_delete';
};

const canBypassInvalidTransition = (params: {
    error: unknown;
    actor: ActorMetadata;
    toStatus: string;
    resolvedDomain: ValidDomain;
    metadata?: Record<string, unknown>;
}): boolean => {
    const typedError = params.error as { code?: string };
    if (typedError.code !== 'INVALID_LIFECYCLE_TRANSITION') return false;
    if (params.actor.type !== ACTOR_TYPE.ADMIN) return false;
    if (!isListingLifecycleDomain(params.resolvedDomain)) return false;
    if (toLower(params.toStatus) !== LISTING_STATUS.DEACTIVATED) return false;
    return isModerationDeactivationAction(params.metadata);
};

interface IStatusable {
    status: string;
    statusChangedAt?: Date;
    statusReason?: string;
    moderationStatus?: string;
    listingType?: string;
    save: (options?: { session?: ClientSession }) => Promise<mongoose.Document>;
    toObject: () => Record<string, unknown>;
    [key: string]: unknown;
}

const createHistoryRecord = async (params: {
    domain: ValidDomain;
    entityId: string | mongoose.Types.ObjectId;
    fromStatus: string;
    toStatus: string;
    actor: ActorMetadata;
    reason?: string;
    metadata?: Record<string, unknown>;
    session: any;
}) => {
    const { domain, entityId, fromStatus, toStatus, actor, reason, metadata, session } = params;
    await StatusHistory.create([{
        domain,
        entityId: (entityId instanceof mongoose.Types.ObjectId) ? entityId : new mongoose.Types.ObjectId(String(entityId)),
        fromStatus,
        toStatus,
        actorType: actor.type,
        actorId: (actor.id && mongoose.Types.ObjectId.isValid(actor.id)) ? new mongoose.Types.ObjectId(actor.id) : undefined,
        reason,
        metadata: {
            ...metadata,
            ip: actor.ip,
            ua: actor.userAgent,
            mutationService: 'v1'
        }
    }], { session });
};

/**
 * 🛠️ Centralized Status Mutation Service
 * 
 * Enforces transaction-safe lifecycle transitions across all domains.
 * Integrates with:
 * 1. LifecycleGuard (Validation)
 * 2. StatusHistory (Unified Audit Trail)
 * 3. Metrics Telemetry (Observability)
 */
export const mutateStatus = async (request: MutationRequest): Promise<Record<string, unknown> | null> => {
    const { domain, entityId, toStatus, actor, reason, patch, metadata, session: externalSession } = request;
    const startTime = Date.now();

    let fromStatus = 'unknown';
    let resolvedListingType: string | undefined;

    try {
        let result: Record<string, unknown> | null = null;

        const executeOperations = async (activeSession: any) => {
            if (isListingLifecycleDomain(domain)) {
                return executeListingOperations(activeSession);
            }

            // 1. Resolve Model
            const Model = getModelForDomain(domain);
            const doc = await (Model as unknown as mongoose.Model<mongoose.Document>).findById(entityId).setOptions({ withDeleted: true }).session(activeSession) as (mongoose.Document & IStatusable) | null;
            if (!doc) {
                throw new AppError(`Entity ${String(entityId)} not found in domain ${domain}`, 404, BusinessErrorCode.RESOURCE_NOT_FOUND);
            }

            fromStatus = doc.status;
            const listingType = doc.listingType;
            resolvedListingType = listingType;

            // 2. Lifecycle Validation (Type-aware for unified ad model)
            const resolvedDomain = resolveLifecycleDomain(domain, listingType);
            try {
                validateLifecycleTransition(resolvedDomain, fromStatus, toStatus);
            } catch (error) {
                if (!canBypassInvalidTransition({
                    error,
                    actor,
                    toStatus,
                    resolvedDomain,
                    metadata,
                })) {
                    throw error;
                }

                logger.warn('Status Mutation BYPASS: allowing admin moderation deactivation outside strict transition map', {
                    domain,
                    resolvedDomain,
                    entityId: String(entityId),
                    fromStatus,
                    toStatus,
                    action: metadata?.action,
                    actorType: actor.type,
                    actorId: actor.id,
                });
            }
            enforceLifecycleMutationPolicy({
                domain: resolvedDomain,
                fromStatus,
                toStatus,
                actor,
                patch,
                metadata,
            });

            // 4. Update Document
            doc.status = toStatus;
            doc.statusChangedAt = new Date();
            if (reason) doc.statusReason = reason;

            // 🛡️ DATA INTEGRITY: Coerce stale/legacy moderationStatus values that are
            // not in the current enum. These exist in documents written before the enum
            // was tightened (e.g. "approved" was an old value, now split into
            // "auto_approved" / "manual_approved"). Mongoose validates the entire
            // document on .save(), so a single stale field blocks ALL mutations.
            const VALID_MODERATION_STATUSES = new Set([
                'auto_approved', 'held_for_review', 'manual_approved', 'rejected', 'community_hidden'
            ]);
            const currentModerationStatus = doc.moderationStatus;
            if (currentModerationStatus && !VALID_MODERATION_STATUSES.has(currentModerationStatus)) {
                logger.warn('StatusMutationService: coercing stale moderationStatus', {
                    entityId: String(entityId),
                    domain,
                    staleValue: currentModerationStatus,
                    coercedTo: 'manual_approved',
                });
                doc.moderationStatus = 'manual_approved';
            }

            // Apply status-specific patch (e.g., soldAt, rejectionReason, $push: { timeline })
            if (patch) {
                for (const [key, value] of Object.entries(patch)) {
                    if (key === '$push' && typeof value === 'object' && value !== null) {
                        for (const [pKey, pVal] of Object.entries(value as Record<string, unknown>)) {
                            const field = doc[pKey];
                            if (Array.isArray(field)) {
                                field.push(pVal);
                            }
                        }
                    } else {
                        doc[key] = value;
                    }
                }
            }

            await doc.save({ session: activeSession as any });

            // 5. Record Unified Status History
            await createHistoryRecord({ domain, entityId, fromStatus, toStatus, actor, reason, metadata, session: activeSession });

            return (typeof doc.toObject === 'function' ? doc.toObject() : doc) as Record<string, unknown>;
        };

        const executeListingOperations = async (activeSession: any) => {
            const { getListingRepository } = await import('../../composition/listings');
            const repo = getListingRepository();
            const listing = await repo.findOne({ ids: [entityId.toString()], isDeleted: { $in: [true, false] } as any, session: activeSession });

            if (!listing) {
                throw new AppError(`Entity ${String(entityId)} not found in domain ${domain}`, 404, BusinessErrorCode.RESOURCE_NOT_FOUND);
            }

            fromStatus = listing.status as string;
            resolvedListingType = listing.listingType as string;

            const resolvedDomain = resolveLifecycleDomain(domain, resolvedListingType);
            try {
                validateLifecycleTransition(resolvedDomain, fromStatus, toStatus);
            } catch (error) {
                if (!canBypassInvalidTransition({ error, actor, toStatus, resolvedDomain, metadata })) {
                    throw error;
                }
            }
            enforceLifecycleMutationPolicy({ domain: resolvedDomain, fromStatus, toStatus, actor, patch, metadata });

            const updateDoc: Record<string, unknown> = {
                status: toStatus,
                statusChangedAt: new Date(),
            };
            if (reason) updateDoc.statusReason = reason;

            const VALID_MODERATION_STATUSES = new Set(['auto_approved', 'held_for_review', 'manual_approved', 'rejected', 'community_hidden']);
            const currentModerationStatus = listing.moderationStatus;
            if (currentModerationStatus && !VALID_MODERATION_STATUSES.has(currentModerationStatus)) {
                updateDoc.moderationStatus = 'manual_approved';
            }

            if (patch) {
                for (const [key, value] of Object.entries(patch)) {
                    updateDoc[key] = value;
                }
            }

            const updated = await repo.updateOne(entityId.toString(), updateDoc as any, activeSession);

            await createHistoryRecord({ domain, entityId, fromStatus, toStatus, actor, reason, metadata, session: activeSession });

            return updated as any;
        };

        if (externalSession) {
            result = await executeOperations(externalSession);
        } else {
            const { getListingUnitOfWork } = await import('../../composition/listings');
            result = await getListingUnitOfWork().executeTransaction(async (session) => {
                return executeOperations(session);
            });
        }

        const duration = Date.now() - startTime;

        // 6. Record Real-time Telemetry (Success) - Always outside critical transaction
        setImmediate(() => {
            recordMutationMetric('success', domain, fromStatus, toStatus, actor.type).catch(err => {
                logger.error('Telemetry Error (Success Path):', err);
            });
        });

        logger.info(`Status Mutation SUCCESS: ${domain} ${String(entityId)} (${fromStatus} -> ${toStatus})`, {
            durationMs: duration,
            actorType: actor.type,
            actorId: actor.id
        });

        // 7. Dispatch Global Lifecycle Event (Decoupled side-effects)
        if (domain === 'ad') {
            // 🛡️ PRODUCTION HARDENING: Fire-and-forget cache invalidation
            // Cache bust runs independently — a Redis failure must NOT block
            // lifecycle event dispatch that downstream consumers depend on.
            import('@esparex/core/composition/listings').then(({ getListingsCache }) => {
                const listingsCache = getListingsCache();
                return Promise.all([
                    listingsCache.invalidatePublicAdCache(entityId.toString()),
                    listingsCache.invalidateAdFeedCaches()
                ]);
            }).catch((cacheErr) => {
                logger.error('Failed to bust cache during status mutation', { adId: entityId.toString(), cacheErr });
            });

            await lifecycleEvents.dispatch('ad.lifecycle.changed', {
                adId: entityId.toString(),
                fromStatus,
                toStatus,
                actorType: actor.type,
                actorId: actor.id,
                source: actor.type,
                reason
            });

            if (
                toStatus === 'rejected'
                && String(metadata?.action || '').trim().toLowerCase() === 'moderation_reject'
            ) {
                await lifecycleEvents.dispatch('listing.rejected', {
                    listingId: entityId.toString(),
                    listingType: resolvedListingType || 'ad',
                    rejectionReason: typeof (patch)?.rejectionReason === 'string'
                        ? String((patch).rejectionReason)
                        : undefined,
                    actorType: actor.type,
                    actorId: actor.id,
                });
            }

            if (
                toStatus === 'live'
                && String(metadata?.action || '').trim().toLowerCase() === 'moderation_approve'
            ) {
                const listingType =
                    typeof metadata?.listingType === 'string'
                        ? String(metadata.listingType)
                        : (
                            typeof (patch)?.listingType === 'string'
                                ? String((patch).listingType)
                                : undefined
                        );
                await lifecycleEvents.dispatch('listing.approved', {
                    listingId: entityId.toString(),
                    listingType: listingType || 'ad',
                    approvedAt: (
                        (patch)?.approvedAt instanceof Date
                            ? ((patch).approvedAt).toISOString()
                            : new Date().toISOString()
                    ),
                    actorType: actor.type,
                    actorId: actor.id,
                    source: String(metadata?.sourceRoute || metadata?.action || actor.type),
                });
            }
        }

        return result;
    } catch (error: unknown) {
        const duration = Date.now() - startTime;
        const err = error as { message?: string; code?: string };

        // Record Real-time Telemetry (Rejection/Failure)
        const isValidationFailure = err.code === 'INVALID_LIFECYCLE_TRANSITION' || err.code === 'LIFECYCLE_LOCKED';
        const metricStatus = isValidationFailure ? 'rejection' : 'failure';

        setImmediate(() => {
            recordMutationMetric(metricStatus as 'success' | 'rejection' | 'failure', domain, fromStatus, toStatus, actor.type).catch(err => {
                logger.error('Telemetry Error (Error Path):', err);
            });
        });

        logger.error(`Status Mutation FAILED: ${domain} ${String(entityId)} -> ${toStatus}`, {
            error: err.message,
            code: err.code,
            durationMs: duration,
            actorType: actor.type
        });

        throw error;
    }
};

const MUTATE_STATUSES_CONCURRENCY = 5;

/**
 * 🛠️ Bulk Status Mutation Service
 * Processes multiple entity transitions with bounded concurrency.
 *
 * Each mutation is fully independent (different entity, own transaction),
 * so concurrent execution is safe while preserving per-mutation audit trails.
 */
export const mutateStatuses = async (requests: MutationRequest[]): Promise<(Record<string, unknown> | null)[]> => {
    const limit = pLimit(MUTATE_STATUSES_CONCURRENCY);
    return Promise.all(requests.map(request => limit(() => mutateStatus(request))));
};

export const mutateStatusesBulk = async (
    domain: ValidDomain,
    entityIds: string[],
    toStatus: string,
    actor: MutationRequest['actor'],
    reason?: string
): Promise<number> => {
    if (!entityIds.length) return 0;

    const Model = getModelForDomain(domain);
    type BulkMutationDoc = { _id: mongoose.Types.ObjectId; listingType?: string };
    const docs = await (Model as unknown as mongoose.Model<mongoose.Document>).find({ _id: { $in: entityIds } })
        .select('_id status listingType')
        .lean<BulkMutationDoc[]>();
    if (!docs.length) return 0;

    await mutateStatuses(
        docs.map((doc) => ({
            domain,
            entityId: String(doc._id),
            toStatus,
            actor,
            reason,
            metadata: {
                action: 'bulk_mutation',
                sourceRoute: 'StatusMutationService.mutateStatusesBulk',
                listingType: doc.listingType,
            },
        }))
    );

    if (domain === 'ad' && toStatus === LISTING_STATUS.EXPIRED) {
        await lifecycleEvents.dispatch('ad.expired.bulk', { count: docs.length, source: 'cron_expireOutdatedAds' });
    }

    return docs.length;
};

/**
 * Domain-to-Model mapping SSOT
 */
function getModelForDomain(domain: ValidDomain) {
    switch (domain) {
        case 'ad': return Ad;
        case 'user': return User;
        case 'business': return Business;
        case 'service': return Ad;
        case 'spare_part_listing': return Ad;
        case 'catalog_part': throw new Error('Domain \'catalog_part\' uses CatalogStatus — route through admin catalog service, not statusMutationService');
        default: throw new Error(`Unsupported domain: ${domain as string}`);
    }
}


/**
 * Record mutation metrics for observability
 */
async function recordMutationMetric(
    status: 'success' | 'rejection' | 'failure',
    domain: string,
    from: string,
    to: string,
    actorType: string
) {
    try {
        // 1. Prometheus Telemetry (High-Resolution)
        if (status === 'success') {
            const { listingStatusTransitionsTotal } = await import('../../utils/metrics');
            listingStatusTransitionsTotal.inc({
                fromStatus: from,
                toStatus: to,
                actorType: actorType,
                listingType: domain,
            });
        }

        // 2. Database Metrics (Historical Trends)
        const date = new Date();
        date.setHours(0, 0, 0, 0);

        const update: Record<string, unknown> = {
            $inc: {
                [`payload.total`]: 1,
                [`payload.${status}`]: 1,
                [`payload.domains.${domain}`]: 1,
                [`payload.transitions.${from}_to_${to}`]: 1
            }
        };

        // AdminMetrics often resides on a separate restricted connection
        await AdminMetrics.findOneAndUpdate(
            { metricModule: 'status_mutations', aggregationDate: date },
            update,
            { upsert: true }
        );
    } catch (err) {
        // Telemetry failure should NEVER block the mutation transaction
        logger.error('Critical Telemetry Failure:', { error: String(err) });
    }
}

type LimitFunction = <T>(fn: () => Promise<T>) => Promise<T>;

export const pLimit = (concurrency: number): LimitFunction => {
    const queue: Array<() => void> = [];
    let active = 0;

    const next = () => {
        active--;
        if (queue.length > 0) {
            const entry = queue.shift()!;
            entry();
        }
    };

    const run = async <T>(fn: () => Promise<T>, resolve: (val: T) => void, reject: (err: unknown) => void) => {
        active++;
        try {
            const result = await fn();
            resolve(result);
        } catch (err) {
            reject(err);
        }
        next();
    };

    const enqueue = <T>(fn: () => Promise<T>, resolve: (val: T) => void, reject: (err: unknown) => void) => {
        queue.push(() => run(fn, resolve, reject));
    };

    return <T>(fn: () => Promise<T>) =>
        new Promise<T>((resolve, reject) => {
            const entry = () => run(fn, resolve, reject);
            if (active < concurrency) {
                entry();
            } else {
                queue.push(() => run(fn, resolve, reject));
            }
        });
};

import { client, isConnected, cacheMetrics } from './config';
import logger from '../logger';
import { withTimeout } from '../resilience';
import { scanKeysByPattern } from './scan';
import {
    GOVERNED_CACHE_PATTERNS, REDIS_TTL_AUDIT_SAMPLE_LIMIT,
    REDIS_PROBE_TIMEOUT_MS, REDIS_HEALTH_PROBE_TTL_SECONDS,
    REDIS_MEMORY_PRESSURE_THRESHOLD, RECOMMENDED_REDIS_EVICTION_POLICY,
    CACHE_NAMESPACES, parseInfoNumberMetric, parseInfoStringMetric, getDefaultTtlForKey,
} from './constants';

let lastRedisConfigWarningSignature: string | null = null;

const getHitRateStatus = () => {
    const total = cacheMetrics.hits + cacheMetrics.misses;
    if (total === 0) return 'healthy';
    const rate = cacheMetrics.hits / total;
    if (rate < 0.5) return 'critical';
    if (rate < 0.7) return 'warning';
    return 'healthy';
};

const checkMemoryHealth = async () => {
    if (!isConnected) return;
    try {
        const info = await client.info('memory');
        const used = parseInfoNumberMetric(info, 'used_memory') ?? 0;
        const max = parseInfoNumberMetric(info, 'maxmemory') ?? 0;
        const maxMemoryPolicy = parseInfoStringMetric(info, 'maxmemory_policy') || 'unknown';
        if (max > 0) {
            (globalThis as any).__redisHighMemoryPressure = (used / max) > REDIS_MEMORY_PRESSURE_THRESHOLD;
        } else {
            (globalThis as any).__redisHighMemoryPressure = false;
        }
        if (process.env.NODE_ENV === 'production') {
            const warnings: string[] = [];
            if (max <= 0) warnings.push('maxmemory is not configured');
            if (maxMemoryPolicy !== RECOMMENDED_REDIS_EVICTION_POLICY) warnings.push(`maxmemory_policy is ${maxMemoryPolicy} (recommended: ${RECOMMENDED_REDIS_EVICTION_POLICY})`);
            const sig = warnings.join(' | ');
            if (sig && sig !== lastRedisConfigWarningSignature) { logger.warn(`[REDIS_CONFIG] ${sig}`); lastRedisConfigWarningSignature = sig; }
            if (!sig) lastRedisConfigWarningSignature = null;
        }
    } catch { /* silent */ }
};

setInterval(() => void checkMemoryHealth(), 300000).unref();

const buildProbeKey = (): string => `${CACHE_NAMESPACES.SYSTEM}:health:probe:${Date.now().toString(36)}:${Math.random().toString(36).slice(2, 8)}`;

export const getRedisHealthProbe = async (): Promise<{
    connected: boolean; pingOk: boolean; roundTripOk: boolean; latencyMs: number | null; error?: string;
}> => {
    const { reliabilityAlertsTotal } = await import('../metrics');
    const { emitReliabilityAlert } = await import('../reliabilityAlerts');

    if (!isConnected) {
        reliabilityAlertsTotal.labels('REDIS_DOWN', 'critical').inc();
        void emitReliabilityAlert({
            type: 'REDIS_DOWN', title: 'Redis is unavailable', severity: 'critical',
            summary: 'Redis client is disconnected', dedupeKey: 'redis_down',
            metadata: { redisMode: process.env.REDIS_MODE, connected: isConnected },
        });
        return { connected: false, pingOk: false, roundTripOk: false, latencyMs: null, error: 'Redis client is disconnected' };
    }

    const probeKey = buildProbeKey();
    const probeValue = Date.now().toString(36);
    const startedAt = Date.now();

    try {
        const pong = await withTimeout(client.ping(), REDIS_PROBE_TIMEOUT_MS, 'Redis ping probe');
        const pingOk = pong === 'PONG';
        await withTimeout(client.set(probeKey, probeValue, 'EX', REDIS_HEALTH_PROBE_TTL_SECONDS), REDIS_PROBE_TIMEOUT_MS, 'Redis probe set');
        const readBack = await withTimeout(client.get(probeKey), REDIS_PROBE_TIMEOUT_MS, 'Redis probe get');
        await withTimeout(client.del(probeKey), REDIS_PROBE_TIMEOUT_MS, 'Redis probe del');
        const roundTripOk = readBack === probeValue;
        if (!(pingOk && roundTripOk)) {
            reliabilityAlertsTotal.labels('REDIS_DEGRADED', 'high').inc();
            void emitReliabilityAlert({
                type: 'REDIS_DEGRADED', title: 'Redis health probe degraded', severity: 'high',
                summary: 'Redis ping or round-trip probe failed', dedupeKey: 'redis_degraded', metadata: { pingOk, roundTripOk },
            });
        }
        return { connected: true, pingOk, roundTripOk, latencyMs: Date.now() - startedAt };
    } catch (error: unknown) {
        cacheMetrics.errors++;
        reliabilityAlertsTotal.labels('REDIS_DOWN', 'critical').inc();
        void emitReliabilityAlert({
            type: 'REDIS_DOWN', title: 'Redis probe failed', severity: 'critical',
            summary: 'Redis health probe operation failed', dedupeKey: 'redis_probe_failure',
            metadata: { error: error instanceof Error ? error.message : String(error) },
        });
        return { connected: true, pingOk: false, roundTripOk: false, latencyMs: Date.now() - startedAt, error: error instanceof Error ? error.message : String(error) };
    }
};

const auditKeyTtl = async (key: string): Promise<{ ttl: number | null; autoFixed: boolean }> => {
    try {
        const ttl = await client.ttl(key);
        if (ttl === -1) {
            const fallbackTtl = getDefaultTtlForKey(key);
            if (fallbackTtl && fallbackTtl > 0) {
                const repaired = await client.expire(key, fallbackTtl);
                if (repaired === 1) return { ttl: fallbackTtl, autoFixed: true };
            }
        }
        return { ttl, autoFixed: false };
    } catch { cacheMetrics.errors++; return { ttl: null, autoFixed: false }; }
};

export const getCacheStats = async () => {
    let memoryUsedBytes = 0, totalKeys = 0, maxMemoryBytes = 0;
    let maxMemoryPolicy = 'unknown';
    let ttlAudit = { sampledKeys: 0, keysWithoutTtl: 0, keysAutoFixed: 0 };
    const redisHealth = await getRedisHealthProbe();

    if (isConnected) {
        try {
            const info = await client.info('memory');
            memoryUsedBytes = parseInfoNumberMetric(info, 'used_memory') ?? 0;
            maxMemoryBytes = parseInfoNumberMetric(info, 'maxmemory') ?? 0;
            maxMemoryPolicy = parseInfoStringMetric(info, 'maxmemory_policy') || 'unknown';
            totalKeys = await client.dbsize();
            await checkMemoryHealth();
            const sampled = new Set<string>();
            for (const pattern of GOVERNED_CACHE_PATTERNS) {
                const keys = await scanKeysByPattern(pattern, { count: 100, maxKeys: 50 });
                for (const key of keys) { sampled.add(key); if (sampled.size >= REDIS_TTL_AUDIT_SAMPLE_LIMIT) break; }
                if (sampled.size >= REDIS_TTL_AUDIT_SAMPLE_LIMIT) break;
            }
            const sampledKeys = Array.from(sampled);
            if (sampledKeys.length > 0) {
                let keysAutoFixed = 0;
                const results = await Promise.all(sampledKeys.map(key => auditKeyTtl(key)));
                for (const r of results) { if (r.autoFixed) keysAutoFixed += 1; }
                const ttlValues = results.map(r => r.ttl);
                ttlAudit = { sampledKeys: sampledKeys.length, keysWithoutTtl: ttlValues.filter(t => t === -1).length, keysAutoFixed };
            }
        } catch { /* ignore */ }
    }

    return {
        connected: isConnected,
        mode: process.env.REDIS_MODE,
        namespaces: CACHE_NAMESPACES,
        redisHealth,
        redisConfig: { maxMemoryBytes, maxMemoryPolicy, evictionPolicyRecommended: RECOMMENDED_REDIS_EVICTION_POLICY, isRecommendedPolicy: maxMemoryPolicy === RECOMMENDED_REDIS_EVICTION_POLICY },
        metrics: { ...cacheMetrics, memoryUsedMB: Number((memoryUsedBytes / (1024 * 1024)).toFixed(2)), totalKeys, ttlAudit, lastUpdated: new Date() },
        healthStatus: getHitRateStatus(),
        memoryPressureStatus: (globalThis as any).__redisHighMemoryPressure ? 'critical' : 'normal',
    };
};

setInterval(() => {
    if (isConnected) {
        const total = cacheMetrics.hits + cacheMetrics.misses;
        if (total > 0) {
            const rate = ((cacheMetrics.hits / total) * 100).toFixed(2);
            logger.info(`[REDIS_METRICS] Hit Rate: ${rate}% | Hits: ${cacheMetrics.hits} | Misses: ${cacheMetrics.misses}`);
        }
    }
}, 60000).unref();

import slugify from 'slugify';
import { nanoid } from 'nanoid';
import { Model } from 'mongoose';

type SlugModel = Model<any>;

/**
 * Generates a unique SEO-friendly slug with DB-checked retries to avoid
 * duplicate-key race conditions when saving documents that have a unique
 * `seoSlug` index.
 *
 * @param model - Mongoose Model to check for collisions (expects `seoSlug` field)
 * @param title - Source text (e.g., ad title)
 * @param oldSlug - Optional existing slug (returns early if unchanged)
 * @param excludeId - Optional _id to exclude from collision checks (useful on updates)
 */
export async function generateUniqueSlug(
    model: SlugModel,
    title: string,
    oldSlug?: string,
    excludeId?: string,
    fieldName = 'seoSlug',
): Promise<string> {
    if (!title) return nanoid(10);

    const baseSlug = slugify(title, {
        lower: true,
        strict: true,
        trim: true,
        replacement: '-',
        remove: /[*+~.()'"!:@]/g,
    });

    // Try a few times to find a non-colliding slug by checking the DB.
    const maxAttempts = 6;
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
        const suffix = nanoid(5);
        const candidate = `${baseSlug}-${suffix}`;

        if (oldSlug && oldSlug === candidate) return oldSlug;

        const query: Record<string, unknown> = { [fieldName]: candidate };
        if (excludeId) query._id = { $ne: excludeId };

        try {
            const exists = await model.exists(query);
            if (!exists) return candidate;
        } catch {
            // If the DB check fails for any reason, fall back to generating
            // a more unique slug and return it. Avoid throwing here to keep
            // slug generation resilient during transient DB issues.
            return `${baseSlug}-${nanoid(8)}`;
        }
    }

    return `${baseSlug}-${nanoid(8)}`;
}

/**
 * Decoupled slug generator that uses a callback to check existence.
 */
export async function generateUniqueSlugWithChecker(
    title: string,
    checkExists: (candidate: string) => Promise<boolean>,
    oldSlug?: string
): Promise<string> {
    if (!title) return nanoid(10);

    const baseSlug = slugify(title, {
        lower: true,
        strict: true,
        trim: true,
        replacement: '-',
        remove: /[*+~.()'"!:@]/g,
    });

    const maxAttempts = 6;
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
        const suffix = nanoid(5);
        const candidate = `${baseSlug}-${suffix}`;

        if (oldSlug && oldSlug === candidate) return oldSlug;

        try {
            const exists = await checkExists(candidate);
            if (!exists) return candidate;
        } catch {
            return `${baseSlug}-${nanoid(8)}`;
        }
    }

    return `${baseSlug}-${nanoid(8)}`;
}

import logger from './logger';
import Category from '../models/Category';
import Brand from '../models/Brand';
import Model from '../models/Model';
import type { Model as MongooseModel } from 'mongoose';
import { getDatabaseHealthProbe } from '../config/db';
import { getQueueHealthProbe } from '../queues/queueHealth';
import { getRedisHealthProbe } from './redisCache';
import { env } from '../config/env';

const STARTUP_COUNT_MAX_TIME_MS = 1200;

const getFastCollectionCount = async (model: any): Promise<number> => {
    try {
        return await model.collection.estimatedDocumentCount({
            maxTimeMS: STARTUP_COUNT_MAX_TIME_MS
        });
    } catch (estimateError) {
        const modelName = model.modelName || 'Unknown';
        logger.warn('[MetadataHealth] estimatedDocumentCount failed; falling back to countDocuments', {
            model: modelName,
            error: estimateError instanceof Error ? estimateError.message : String(estimateError)
        });

        return model.collection.countDocuments({}, {
            maxTimeMS: STARTUP_COUNT_MAX_TIME_MS
        });
    }
};

/**
 * Validates the integrity of metadata collections at startup.
 * Since metadata (Categories, Brands) often resides in a separate Admin DB,
 * this check ensures that the application is correctly connected and the data is present.
 */
export async function validateMetadataHealth() {
    try {
        const [categoryCount, brandCount, modelCount] = await Promise.all([
            getFastCollectionCount(Category),
            getFastCollectionCount(Brand),
            getFastCollectionCount(Model)
        ]);

        if (categoryCount === 0 || brandCount === 0) {
            logger.warn('⚠️ METADATA ALERT: Category or Brand collection is empty. Listings may lack critical metadata.', {
                categories: categoryCount,
                brands: brandCount,
                models: modelCount
            });
        } else {
            logger.info('✅ Metadata health verified', {
                categories: categoryCount,
                brands: brandCount,
                models: modelCount
            });
        }
    } catch (err) {
        logger.error('❌ Metadata validation failed', {
            error: err instanceof Error ? err.message : String(err)
        });
    }
}

const STARTUP_READINESS_TIMEOUT_MS = env.RELIABILITY_STARTUP_READINESS_TIMEOUT_MS ?? 12_000;

export const assertCriticalStartupReadiness = async (): Promise<void> => {
    const startedAt = Date.now();
    const [databaseHealth, redisHealth, queueHealth] = await Promise.all([
        getDatabaseHealthProbe(),
        getRedisHealthProbe(),
        getQueueHealthProbe(),
    ]);

    const readinessFailures: string[] = [];
    if (databaseHealth.overall === 'down') {
        readinessFailures.push('database subsystem is down');
    }

    const redisConnected = redisHealth.connected && redisHealth.pingOk && redisHealth.roundTripOk;
    const isProduction = env.NODE_ENV === 'production';
    const redisRequired = isProduction;

    if (!redisConnected) {
        if (redisRequired) {
            readinessFailures.push('redis subsystem is unavailable');
        } else {
            logger.warn('Redis unavailable; continuing with in-memory cache and rate limiter fallbacks.', {
                connected: redisHealth.connected,
                pingOk: redisHealth.pingOk,
                roundTripOk: redisHealth.roundTripOk
            });
        }
    }
    if (queueHealth.status === 'down') {
        if (redisRequired) {
            readinessFailures.push('queue subsystem is down');
        } else {
            logger.warn('Queue subsystem unavailable; running without background jobs.', {
                status: queueHealth.status
            });
        }
    }

    if (Date.now() - startedAt > STARTUP_READINESS_TIMEOUT_MS) {
        readinessFailures.push(`readiness evaluation exceeded ${STARTUP_READINESS_TIMEOUT_MS}ms`);
    }

    if (readinessFailures.length > 0) {
        throw new Error(`Critical startup readiness failed: ${readinessFailures.join('; ')}`);
    }

    logger.info('Critical startup readiness passed', {
        databaseStatus: databaseHealth.overall,
        redisConnected: redisHealth.connected,
        redisPingOk: redisHealth.pingOk,
        redisRoundTripOk: redisHealth.roundTripOk,
        queueStatus: queueHealth.status,
        evaluatedInMs: Date.now() - startedAt,
    });
};

import Ad from "../models/Ad";
import User from "../models/User";
import { locationRepository, locationAnalyticsRepository } from "../composition/location";
import { LISTING_STATUS } from '@esparex/contracts';
import logger from '../utils/logger';
import { runWithDistributedJobLock } from '../utils/distributedJobLock';

export const runLocationAnalyticsJob = async () => {
    await runWithDistributedJobLock(
        'location_analytics_refresh',
        { ttlMs: 2 * 60 * 60 * 1000, failOpen: false },
        async () => {
            logger.info('Starting Location Analytics Worker...');
            try {
                await updateLocationStats();
                logger.info('Location Analytics Worker completed successfully.');
            } catch (error) {
                logger.error('Location Analytics Worker failed', { error });
            }
        }
    );
};

/**
 * Refreshes LocationAnalytics for all active locations via LocationAnalyticsRepositoryPort.
 * Computes adsCount, activeAdsCount, usersCount, searchCount, viewCount,
 * popularityScore, and isHotZone in a single consolidated write.
 */
export const updateLocationStats = async (triggeredBy: 'cron' | 'manual' = 'cron') => {
    logger.info('Updating location analytics...', { triggeredBy });

    let jobLog;
    try {
        const JobLogStart = (await import('@esparex/core/models/JobLog')).default;
        jobLog = await JobLogStart.create({
            jobName: 'refreshLocationStats',
            status: 'started',
            triggeredBy,
            startedAt: new Date()
        });
    } catch (e) {
        logger.error('Failed to create start JobLog', { error: e });
    }

    const startTime = Date.now();

    try {
        const locations = await locationRepository.findMany({ isActive: true });
        const locationIds = locations.map((loc: any) => loc._id);

        const [adCountsAgg, userCountsAgg, existingAnalyticsDocs] = await Promise.all([
            Ad.aggregate<{
                _id: unknown;
                adsCount: number;
                activeAdsCount: number;
            }>([
                { $match: { 'location.locationId': { $in: locationIds } } },
                {
                    $group: {
                        _id: '$location.locationId',
                        adsCount: { $sum: 1 },
                        activeAdsCount: {
                            $sum: { $cond: [{ $eq: ['$status', LISTING_STATUS.LIVE] }, 1, 0] }
                        }
                    }
                }
            ]),
            User.aggregate<{
                _id: unknown;
                usersCount: number;
            }>([
                { $match: { locationId: { $in: locationIds } } },
                {
                    $group: {
                        _id: '$locationId',
                        usersCount: { $sum: 1 }
                    }
                }
            ]),
            locationAnalyticsRepository.findAnalytics({ locationId: { $in: locationIds } })
        ]);

        const adCountByLocationId = new Map<string, { adsCount: number; activeAdsCount: number }>();
        const userCountByLocationId = new Map<string, number>();
        const analyticsByLocationId = new Map<string, { searchCount: number; viewCount: number }>();

        for (const item of adCountsAgg) {
            adCountByLocationId.set(String(item._id), {
                adsCount: Number(item.adsCount || 0),
                activeAdsCount: Number(item.activeAdsCount || 0)
            });
        }
        for (const item of userCountsAgg) {
            userCountByLocationId.set(String(item._id), Number(item.usersCount || 0));
        }
        for (const item of existingAnalyticsDocs) {
            analyticsByLocationId.set(String(item.locationId), {
                searchCount: Number((item as { searchCount?: number }).searchCount || 0),
                viewCount: Number((item as { viewCount?: number }).viewCount || 0)
            });
        }

        const analyticsBulkOps: any[] = [];

        for (const loc of locations) {
            const locationKey = String(loc._id);
            const adCounts = adCountByLocationId.get(locationKey);
            const adsCount = adCounts?.adsCount ?? 0;
            const activeAdsCount = adCounts?.activeAdsCount ?? 0;
            const usersCount = userCountByLocationId.get(locationKey) ?? 0;
            const existingAnalytics = analyticsByLocationId.get(locationKey);
            const searchCount = existingAnalytics?.searchCount ?? 0;
            const viewCount = existingAnalytics?.viewCount ?? 0;

            const popularityScore = Number(
                (adsCount * 0.4 + searchCount * 0.3 + viewCount * 0.3).toFixed(2)
            );
            const isHotZone = searchCount >= 100 || adsCount >= 50;

            analyticsBulkOps.push({
                updateOne: {
                    filter: { locationId: loc._id },
                    update: {
                        $set: {
                            locationId: loc._id,
                            adsCount,
                            activeAdsCount,
                            usersCount,
                            searchCount,
                            viewCount,
                            popularityScore,
                            isHotZone,
                            lastUpdated: new Date()
                        }
                    },
                    upsert: true
                }
            });
        }

        let updateCount = 0;
        if (analyticsBulkOps.length > 0) {
            const result = (await locationAnalyticsRepository.bulkWriteAnalytics(analyticsBulkOps)) as { modifiedCount: number; upsertedCount: number };
            updateCount = result.modifiedCount + result.upsertedCount;
            logger.info(`Updated analytics for ${analyticsBulkOps.length} locations.`, { updateCount });
        } else {
            logger.info('No location analytics to update.');
        }


        if (jobLog) {
            jobLog.status = 'success';
            jobLog.completedAt = new Date();
            jobLog.durationMs = Date.now() - startTime;
            jobLog.result = { processedLocations: locations.length, updatedAnalytics: updateCount };
            await jobLog.save();
        }

    } catch (err: unknown) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error';
        logger.error('Error updating location analytics:', { error: err });

        if (jobLog) {
            jobLog.status = 'failed';
            jobLog.completedAt = new Date();
            jobLog.durationMs = Date.now() - startTime;
            jobLog.error = errorMessage;
            await jobLog.save();
        }
        throw err;
    }
};

import { Worker } from 'bullmq';
import { redisConnection, shouldDisableQueueConnection } from '../queues/redisConnection';
import { NotificationDispatcher } from '../services/notification/NotificationDispatcher';
import { NotificationIntent } from '../domain/NotificationIntent';
import logger from '../utils/logger';
import { enqueueDeadLetter } from '../queues/deadLetterQueue';
import { queueWorkerBackoffStrategy } from '../queues/queueDefaults';
import { TraceContext } from '@esparex/shared';
import { clearReliabilityContext, setReliabilityContext } from '../utils/reliabilityContext';

/**
 * Notification Delivery Worker
 * Domain: notification
 * Queue:  notification.delivery.queue
 *
 * Responsibilities:
 *  1. Execute the final delivery of notifications (DB, WebSocket, FCM).
 *  2. Provide retry logic for failed push attempts.
 */
const createNoopWorker = <T>() => ({
    on: () => undefined,
    close: async () => undefined,
} as unknown as Worker<T>);

export const notificationDeliveryProcessor = async (job: any) => {
    const traceId = (job.data as { _trace?: { requestId?: string } } | undefined)?._trace?.requestId || `job-${String(job.id || 'unknown')}`;
    const traceUserId = (job.data as { _trace?: { userId?: string } } | undefined)?._trace?.userId;
    TraceContext.setCorrelationId(traceId);
    setReliabilityContext({
        traceId,
        userId: traceUserId,
        queueName: 'notification.delivery.queue',
        jobId: job.id ? String(job.id) : undefined,
        jobName: job.name,
        requestPath: `queue://notification.delivery.queue/${job.name}`,
        method: 'QUEUE',
    });
    const { intent, options } = job.data as {
        intent: ConstructorParameters<typeof NotificationIntent>[0];
        options: { shadowDispatch?: boolean }
    };

    logger.info(`[NotificationDeliveryWorker] Processing ${job.name} for User ${intent.userId}`, {
        jobId: job.id,
        type: intent.type
    });

    try {
        // Reconstruct the intent object to ensure all defaults are applied 
        // and any internal logic runs (though executeDispatch uses properties mostly).
        const notificationIntent = new NotificationIntent(intent);

        await NotificationDispatcher.executeDispatch(notificationIntent, options);

        logger.info(`[NotificationDeliveryWorker] Completed delivery for User ${intent.userId}`, {
            jobId: job.id
        });
    } catch (error) {
        logger.error(`[NotificationDeliveryWorker] Failed delivery for User ${intent.userId}`, {
            jobId: job.id,
            error: error instanceof Error ? error.message : String(error)
        });
        // Propagate error to BullMQ for retry (configured in adQueue.ts defaultJobOptions)
        throw error;
    } finally {
        TraceContext.clear();
        clearReliabilityContext();
    }
};

export const notificationDeliveryWorker = shouldDisableQueueConnection
    ? createNoopWorker()
    : new Worker(
        'notification.delivery.queue',
        notificationDeliveryProcessor,
        {
            connection: redisConnection,
            concurrency: 50, // High concurrency for network-bound tasks (FCM, WebSocket)
            settings: {
                backoffStrategy: (attemptsMade: number) => {
                    // Exponential: 5s → 10s → 20s → 40s → 80s
                    return queueWorkerBackoffStrategy(attemptsMade, 5_000, 600_000);
                }
            }
        }
    );

if (!shouldDisableQueueConnection) {
    notificationDeliveryWorker.on('failed', (job, err) => {
        if (job) {
            logger.error(`[NotificationDeliveryWorker] Delivery Job ${job.id} permanently failed`, {
                error: err.message,
                attempts: job.attemptsMade,
                attemptsConfigured: job.opts.attempts || 1,
            });
            void enqueueDeadLetter('notification.delivery.queue', job, err);
        }
    });

    notificationDeliveryWorker.on('completed', (job) => {
        logger.debug(`[NotificationDeliveryWorker] Delivery Job ${job.id} completed successfully`);
    });

    notificationDeliveryWorker.on('error', (err) => {
        logger.error('[NotificationDeliveryWorker] Worker runtime error', {
            error: err.message
        });
    });
}

