// Helper to convert hex to HSL (Tailwind format: "H S% L%")
function hexToHsl(hex: string): string {
  if (hex.startsWith('var(') || hex === 'transparent' || hex === 'currentColor') {
    return hex;
  }

  // Remove hash
  hex = hex.replace(/^#/, '');

  // Parse hex values
  let r = parseInt(hex.substring(0, 2), 16) / 255;
  let g = parseInt(hex.substring(2, 4), 16) / 255;
  let b = parseInt(hex.substring(4, 6), 16) / 255;

  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  let h = 0, s = 0, l = (max + min) / 2;

  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      case b: h = (r - g) / d + 4; break;
    }
    h /= 6;
  }

  h = Math.round(h * 360 * 10) / 10;
  s = Math.round(s * 100 * 10) / 10;
  l = Math.round(l * 100 * 10) / 10;

  return `${h} ${s}% ${l}%`;
}

function generateCss() {
  let css = `/* GENERATED FILE - DO NOT EDIT MANUALLY */\n`;
  css += `/* Source: @esparex/design-tokens */\n\n`;

  // Generate Light Mode variables
  css += `:root {\n`;

  for (const [key, value] of Object.entries(colors.semantic.light)) {
    css += `    --${key}: ${hexToHsl(value as string)};\n`;
  }

  // Hardcoded radius to preserve current globals.css behavior (usually handled by tokens, but globals uses rem for border-radius base)
  css += `    --radius: 0.5rem;\n`;

  css += `}\n\n`;

  // Generate Dark Mode variables
  css += `.dark {\n`;
  for (const [key, value] of Object.entries(colors.semantic.dark)) {
    css += `    --${key}: ${hexToHsl(value as string)};\n`;
  }
  css += `}\n`;

  const distDir = path.join(__dirname, '../dist');
  if (!fs.existsSync(distDir)) {
    fs.mkdirSync(distDir, { recursive: true });
  }

  fs.writeFileSync(path.join(distDir, 'css-variables.css'), css, 'utf8');
  console.log('✅ Generated packages/design-tokens/dist/css-variables.css');
}

generateCss();

export class Result<T> {
    public isSuccess: boolean;
    public isFailure: boolean
    public error: T | string | null;
    private _value: T | null;

    private constructor(isSuccess: boolean, error?: T | string | null, value?: T | null) {
        if (isSuccess && error) {
            throw new Error('InvalidOperation: A result cannot be successful and contain an error');
        }
        if (!isSuccess && !error) {
            throw new Error('InvalidOperation: A failing result needs to contain an error message');
        }

        this.isSuccess = isSuccess;
        this.isFailure = !isSuccess;
        this.error = error || null;
        this._value = value || null;

        Object.freeze(this);
    }

    public getValue(): T {
        if (!this.isSuccess) {
            console.log(this.error);
            throw new Error('Can not get the value of an error result. Use errorValue instead.');
        }
        return this._value as T;
    }

    public errorValue(): T {
        return this.error as T;
    }

    public static ok<U>(value?: U): Result<U> {
        return new Result<U>(true, null, value);
    }

    public static fail<U>(error: any): Result<U> {
        return new Result<U>(false, error);
    }

    public static combine(results: Result<any>[]): Result<any> {
        for (const result of results) {
            if (result.isFailure) return result;
        }
        return Result.ok();
    }
}

interface ValueObjectProps {
    [index: string]: any;
}

export abstract class ValueObject<T extends ValueObjectProps> {
    public readonly props: T;

    constructor(props: T) {
        this.props = Object.freeze(props);
    }

    public equals(vo?: ValueObject<T>): boolean {
        if (vo === null || vo === undefined) {
            return false;
        }
        if (vo.props === undefined) {
            return false;
        }
        return JSON.stringify(this.props) === JSON.stringify(vo.props);
    }
}

import { EventEmitter } from 'events';

export interface DomainEvent {
    readonly eventName: string;
    readonly occurredOn: Date;
}

type EventHandler<T extends DomainEvent> = (event: T) => void | Promise<void>;

export class DomainEventBus {
    private emitter: EventEmitter;

    constructor() {
        this.emitter = new EventEmitter();
        this.emitter.setMaxListeners(50);
    }

    public subscribe<T extends DomainEvent>(eventName: string, handler: EventHandler<T>): void {
        this.emitter.on(eventName, (event: T) => {
            void Promise.resolve(handler(event)).catch(error => {
                console.error(`[DomainEventBus] Error in handler for ${eventName}:`, error);
            });
        });
    }

    public publish<T extends DomainEvent>(event: T): void {
        // Decouple event publishing from the current transaction/execution context
        setImmediate(() => {
            try {
                this.emitter.emit(event.eventName, event);
            } catch (error) {
                console.error(`[DomainEventBus] Failed to emit ${event.eventName}:`, error);
            }
        });
    }
}

export const domainEventBus = new DomainEventBus();

