"use client";

import React, { useRef } from "react";
import { useVirtualizer } from "@tanstack/react-virtual";
import { ArrowUpDown } from "lucide-react";
import { DataTableToolbar } from "./DataTableToolbar";
import { DataTableBody } from "./DataTableBody";
import { DataTablePagination } from "./DataTablePagination";
import type { ColumnDef } from "./DataTableTypes";

;

interface PaginationProps {
    currentPage: number;
    totalPages: number;
    totalItems: number;
    pageSize: number;
    onPageChange: (page: number) => void;
}

interface DataTableProps<T> {
    data: T[];
    columns: ColumnDef<T>[];
    isLoading?: boolean;
    emptyMessage?: string;
    onRowClick?: (item: T) => void;
    pagination?: PaginationProps;
    viewportClassName?: string;
    toolbar?: React.ReactNode;
    selectedCount?: number;
    bulkActions?: React.ReactNode;
    enableColumnVisibility?: boolean;
    enableCsvExport?: boolean;
    csvFileName?: string;
    onExportCsv?: () => void;
    sortState?: { columnId: string; direction: "asc" | "desc" } | null;
    onSortChange?: (columnId: string) => void;
    columnVisibility?: Record<string, boolean>;
    onColumnVisibilityChange?: (visibility: Record<string, boolean>) => void;
    hideColumnVisibilityButton?: boolean;
    virtualOverscan?: number;
    virtualEstimateSize?: number;
    loadingRowCount?: number;
    emptyState?: React.ReactNode;
}

export function DataTable<T extends { id: string | number }>({
    data,
    columns,
    isLoading,
    emptyMessage = "No data found",
    onRowClick,
    pagination,
    viewportClassName,
    toolbar,
    selectedCount = 0,
    bulkActions,
    enableColumnVisibility = false,
    enableCsvExport = false,
    csvFileName = "export.csv",
    onExportCsv,
    sortState,
    onSortChange,
    columnVisibility: controlledColumnVisibility,
    onColumnVisibilityChange,
    hideColumnVisibilityButton = false,
    virtualOverscan = 5,
    virtualEstimateSize = 40,
    loadingRowCount = 5,
    emptyState,

}: DataTableProps<T>) {
    const loadingRows = Array.from({ length: loadingRowCount }, (_, i) => i);

    const { currentPage = 1, totalPages = 1, totalItems = data.length, pageSize = 20, onPageChange } = pagination || {};
    const startItem = (currentPage - 1) * pageSize + 1;
    const endItem = Math.min(currentPage * pageSize, totalItems);

    const parentRef = useRef<HTMLDivElement>(null);
    const [internalColumnVisibility, setInternalColumnVisibility] = React.useState<Record<string, boolean>>(() =>
        Object.fromEntries(
            columns.map((column, index) => [
                column.id || String(column.accessorKey || index),
                column.defaultVisible !== false,
            ])
        )
    );

    const columnVisibility = controlledColumnVisibility ?? internalColumnVisibility;
    const setColumnVisibility = (updater: Record<string, boolean> | ((prev: Record<string, boolean>) => Record<string, boolean>)) => {
        if (onColumnVisibilityChange) {
            const nextValue = typeof updater === "function" ? updater(columnVisibility) : updater;
            onColumnVisibilityChange(nextValue);
        } else {
            setInternalColumnVisibility(updater);
        }
    };


    const getScrollElement = React.useCallback(() => parentRef.current, []);
    const estimateSize = React.useCallback(() => virtualEstimateSize, [virtualEstimateSize]);

    // eslint-disable-next-line react-hooks/incompatible-library -- TanStack Virtual uses controlled internal mutation and is intentionally isolated here.
    const rowVirtualizer = useVirtualizer({
        count: data.length,
        getScrollElement,
        estimateSize,
        overscan: virtualOverscan,
    });

    const virtualItems = rowVirtualizer.getVirtualItems();
    const firstVirtualItem = virtualItems[0];
    const lastVirtualItem = virtualItems.length > 0 ? virtualItems[virtualItems.length - 1] : undefined;
    const visibleColumns = columns.filter((column, index) => {
        const key = column.id || String(column.accessorKey || index);
        return columnVisibility[key] !== false;
    });

    const exportCsv = () => {
        if (onExportCsv) {
            onExportCsv();
            return;
        }

        const headers = visibleColumns.map((column) => column.header);
        const rows = data.map((item) =>
            visibleColumns.map((column) => {
                const value = column.exportValue
                    ? column.exportValue(item)
                    : column.accessorKey
                        ? item[column.accessorKey]
                        : "";
                const normalized = value == null ? "" : String(value).replace(/"/g, '""');
                return `"${normalized}"`;
            })
        );

        const csv = [headers.join(","), ...rows.map((row) => row.join(","))].join("\n");
        const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = csvFileName;
        link.click();
        URL.revokeObjectURL(url);
    };

    return (
        <div className="w-full flex-col overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
            {isLoading ? (
                <div className="w-full bg-white border border-slate-200 rounded-xl overflow-hidden animate-pulse">
                    <div className="h-12 bg-slate-50 border-b border-slate-100" />
                    {loadingRows.map((i) => (
                        <div key={i} className="h-16 border-b border-slate-50 mx-4" />
                    ))}
                </div>
            ) : (
                <>
                    <DataTableToolbar
                        toolbar={toolbar}
                        bulkActions={bulkActions}
                        selectedCount={selectedCount}
                        enableColumnVisibility={enableColumnVisibility}
                        hideColumnVisibilityButton={hideColumnVisibilityButton}
                        columns={columns}
                        columnVisibility={columnVisibility}
                        setColumnVisibility={setColumnVisibility}
                        enableCsvExport={enableCsvExport}
                        exportCsv={exportCsv}
                    />
                    <div
                        ref={parentRef}
                        className={`custom-scrollbar overflow-auto max-h-[70vh] ${viewportClassName || ""}`}
                    >
                        <table className="w-full text-left text-sm border-collapse min-w-[600px]">
                            <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 sticky top-0 z-10">
                                <tr>
                                    {visibleColumns.map((col, idx) => (
                                        <th key={idx} className={`px-3.5 py-2.5 sm:px-4 sm:py-2.5 font-semibold uppercase tracking-wider text-tiny ${col.className || ""}`}>
                                            <button
                                                type="button"
                                                disabled={!col.sortable || !onSortChange}
                                                onClick={() => {
                                                    const columnId = col.id || String(col.accessorKey || idx);
                                                    if (col.sortable && onSortChange) onSortChange(columnId);
                                                }}
                                                className={`flex items-center gap-2 group transition-colors ${col.sortable && onSortChange ? "cursor-pointer hover:text-slate-900" : "cursor-default"}`}
                                                aria-label={col.sortable && onSortChange ? `Sort by ${col.header}` : undefined}
                                            >
                                                {col.header}
                                                <ArrowUpDown
                                                    size={12}
                                                    className={`transition-opacity ${
                                                        sortState && (col.id || String(col.accessorKey || idx)) === sortState.columnId
                                                            ? "opacity-100 text-slate-900"
                                                            : "opacity-0 group-hover:opacity-100"
                                                    }`}
                                                />
                                            </button>
                                        </th>
                                    ))}
                                </tr>
                            </thead>
                            <DataTableBody
                                data={data}
                                virtualItems={virtualItems}
                                firstVirtualItem={firstVirtualItem}
                                lastVirtualItem={lastVirtualItem}
                                visibleColumns={visibleColumns}
                                rowVirtualizer={rowVirtualizer}
                                emptyMessage={emptyMessage}
                                emptyState={emptyState}
                                onRowClick={onRowClick}
                            />
                        </table>
                    </div>

                    <DataTablePagination
                        currentPage={currentPage}
                        totalPages={totalPages}
                        totalItems={totalItems}
                        startItem={startItem}
                        endItem={endItem}
                        dataLength={data.length}
                        onPageChange={onPageChange}
                    />
                </>
            )}
        </div>
    );
}

/**
 * Esparex — Monetization DB Consistency Audit
 *
 * Usage:
 *   npx ts-node -P tsconfig.json scripts/db-consistency-audit.ts
 *
 * Compares UserWallet credit fields against summed active Entitlement.remaining
 * values for a sample of users, and checks for downstream record gaps.
 *
 * This is a READ-ONLY script. It makes no writes.
 */

import mongoose from 'mongoose';
import { env } from '../core/src/config/env';

// ─── Model imports (adjust paths if running from a different CWD) ─────────────
import '../core/src/config/db';
import UserWallet from '../core/src/models/UserWallet';
import Entitlement from '../core/src/models/Entitlement';
import UserPlan from '../core/src/models/UserPlan';
import { Transaction } from '../core/src/models/Transaction';
import Invoice from '../core/src/models/Invoice';

// ─── Config ───────────────────────────────────────────────────────────────────
const SAMPLE_SIZE = 50;
const NOW = new Date();

// ─── Helpers ──────────────────────────────────────────────────────────────────
function fmt(label: string, value: unknown) {
    console.log(`  ${label.padEnd(36)} ${String(value)}`);
}

function warn(msg: string) {
    console.warn(`  ⚠️  ${msg}`);
}

function ok(msg: string) {
    console.log(`  ✅ ${msg}`);
}

// ─── Run ──────────────────────────────────────────────────────────────────────
async function run() {
    console.log('\n========================================');
    console.log('  Esparex Monetization Consistency Audit');
    console.log('========================================\n');

    // 1. Sample wallets that have any credits
    const wallets = await UserWallet.find({
        $or: [
            { adCredits: { $gt: 0 } },
            { spotlightCredits: { $gt: 0 } },
            { smartAlertSlots: { $gt: 0 } },
        ]
    }).limit(SAMPLE_SIZE).lean();

    console.log(`Sampling ${wallets.length} wallets with non-zero credits.\n`);

    let driftCount = 0;
    let orphanedPlanCount = 0;
    let missingInvoiceCount = 0;
    let stringUserIdCount = 0;

    for (const wallet of wallets) {
        const userId = wallet.userId;
        console.log(`────────────────────────────────────────`);
        console.log(`  User: ${String(userId)}`);

        // ── Check userId storage type ────────────────────────────────────────
        if (typeof userId === 'string') {
            warn(`userId stored as STRING (not ObjectId) → wallet query mismatch risk`);
            stringUserIdCount++;
        }

        const userObjId = new mongoose.Types.ObjectId(String(userId));

        // ── Entitlement sums ─────────────────────────────────────────────────
        const entitlements = await Entitlement.find({
            userId: userObjId,
            status: 'ACTIVE',
        }).lean();

        const entitlementSums = {
            AD_POSTING: 0,
            SPOTLIGHT_CAT: 0,
            SMART_ALERT_SLOT: 0,
        };
        let expiredButActiveCount = 0;

        for (const e of entitlements) {
            const type = e.type as keyof typeof entitlementSums;
            if (type in entitlementSums) {
                entitlementSums[type] += Number(e.remaining ?? 0);
            }
            if (e.expiresAt && new Date(e.expiresAt) < NOW) {
                expiredButActiveCount++;
            }
        }

        // ── Wallet vs Entitlement drift ──────────────────────────────────────
        const walletAdCredits = Number(wallet.adCredits ?? 0);
        const walletSpotlight = Number(wallet.spotlightCredits ?? 0);
        const walletSmartAlert = Number(wallet.smartAlertSlots ?? 0);

        let userHasDrift = false;

        if (walletAdCredits !== entitlementSums.AD_POSTING) {
            warn(`adCredits DRIFT: wallet=${walletAdCredits} | entitlement_sum=${entitlementSums.AD_POSTING} | delta=${walletAdCredits - entitlementSums.AD_POSTING}`);
            userHasDrift = true;
        } else {
            ok(`adCredits consistent: ${walletAdCredits}`);
        }

        if (walletSpotlight !== entitlementSums.SPOTLIGHT_CAT) {
            warn(`spotlightCredits DRIFT: wallet=${walletSpotlight} | entitlement_sum=${entitlementSums.SPOTLIGHT_CAT} | delta=${walletSpotlight - entitlementSums.SPOTLIGHT_CAT}`);
            userHasDrift = true;
        } else {
            ok(`spotlightCredits consistent: ${walletSpotlight}`);
        }

        if (walletSmartAlert !== entitlementSums.SMART_ALERT_SLOT) {
            warn(`smartAlertSlots DRIFT: wallet=${walletSmartAlert} | entitlement_sum=${entitlementSums.SMART_ALERT_SLOT} | delta=${walletSmartAlert - entitlementSums.SMART_ALERT_SLOT}`);
            userHasDrift = true;
        } else {
            ok(`smartAlertSlots consistent: ${walletSmartAlert}`);
        }

        if (userHasDrift) driftCount++;

        if (expiredButActiveCount > 0) {
            warn(`${expiredButActiveCount} entitlement(s) have status=ACTIVE but expiresAt < NOW (no expiry job running)`);
        }

        // ── UserPlan check ───────────────────────────────────────────────────
        const activePlans = await UserPlan.find({ userId: userObjId, status: 'active' }).lean();
        if (activePlans.length > 1) {
            warn(`Multiple active UserPlans (${activePlans.length}) — UserPlan.updateMany logic may not be idempotent`);
            orphanedPlanCount++;
        } else if (activePlans.length === 0) {
            fmt('Active UserPlan', 'none');
        } else {
            fmt('Active UserPlan', activePlans[0]?.planId);
        }

        // ── Transaction coverage ─────────────────────────────────────────────
        const successTxs = await Transaction.find({
            userId: userObjId,
            status: 'SUCCESS',
            applied: true,
            amount: { $gt: 0 }     // exclude internal credit-only transactions
        }).lean();

        for (const tx of successTxs) {
            const invoice = await Invoice.findOne({ transactionId: tx._id }).lean();
            if (!invoice) {
                warn(`Transaction ${String(tx._id)} (${String(tx.planSnapshot?.name)}) has no Invoice record`);
                missingInvoiceCount++;
            }

            const entForTx = await Entitlement.find({ sourceId: tx._id }).lean();
            if (entForTx.length === 0 && (tx.planSnapshot?.type !== 'FREE_DEFAULT')) {
                warn(`Transaction ${String(tx._id)} (type=${String(tx.planSnapshot?.type)}) has no Entitlement records`);
            }
        }
    }

    // ─── Summary ─────────────────────────────────────────────────────────────
    console.log('\n════════════════════════════════════════');
    console.log('  AUDIT SUMMARY');
    console.log('════════════════════════════════════════');
    fmt('Wallets sampled', wallets.length);
    fmt('Wallets with credit drift', `${driftCount} / ${wallets.length}`);
    fmt('Wallets with string userId', `${stringUserIdCount} / ${wallets.length}`);
    fmt('Users with multiple active plans', orphanedPlanCount);
    fmt('Transactions missing invoices', missingInvoiceCount);

    if (driftCount === 0) {
        ok('No wallet↔entitlement drift detected in sample');
    } else {
        warn(`${driftCount} wallets have credit drift — UserWallet is NOT a reliable projection of Entitlements`);
    }

    await mongoose.disconnect();
    console.log('\nDone.\n');
}

run().catch((err) => {
    console.error('Audit failed:', err);
    process.exit(1);
});

