/**
 * enforce-mobile-architecture-guard.js
 *
 * Automated Architecture Guard for Esparex Mobile (`apps/mobile/src`).
 * Enforces strict layer boundaries:
 *
 * 1. Presentation (screens, steps, components) MUST NOT import:
 *    - infrastructure/
 *    - Api* implementations directly
 *    - apiClient directly
 *
 * 2. Presentation Hooks MUST NOT import:
 *    - infrastructure/
 *    - Api* implementations directly
 *    - apiClient directly
 *
 * 3. Application Services & Domain MUST NOT import:
 *    - presentation/
 *    - infrastructure/ (except via bootstrap composition root)
 *    - react / react-native
 */

const fs = require("node:fs");
const path = require("node:path");

const repoRoot = path.resolve(__dirname, "..");
const mobileSrcDir = path.join(repoRoot, "apps", "mobile", "src");

if (!fs.existsSync(mobileSrcDir)) {
  console.log("Mobile package not found, skipping mobile architecture guard.");
  process.exit(0);
}

function toUnixPath(input) {
  return input.replaceAll(path.sep, "/");
}

function walk(dir, output = []) {
  if (!fs.existsSync(dir)) return output;

  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (["node_modules", "dist", ".expo", "coverage"].includes(entry.name)) continue;

    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(fullPath, output);
    } else if (entry.isFile() && /\.(ts|tsx)$/.test(entry.name)) {
      output.push(fullPath);
    }
  }
  return output;
}

const allFiles = walk(mobileSrcDir);
const violations = [];

for (const filePath of allFiles) {
  const relPath = toUnixPath(path.relative(mobileSrcDir, filePath));
  const content = fs.readFileSync(filePath, "utf8");
  const lines = content.split("\n");

  lines.forEach((line, index) => {
    // Only inspect import statements
    if (!/^\s*import\b/.test(line)) return;

    const lineNum = index + 1;

    // Rule 1: Presentation & Presentation Hooks cannot import infrastructure or Api* classes directly
    if (relPath.includes("/presentation/")) {
      if (line.includes("/infrastructure/") || line.includes("infrastructure/api/apiClient")) {
        violations.push({
          file: relPath,
          line: lineNum,
          rule: "Presentation cannot import infrastructure or apiClient directly. Use application hooks/services.",
          code: line.trim(),
        });
      }
      if (/import.*Api[A-Z]\w+/.test(line)) {
        violations.push({
          file: relPath,
          line: lineNum,
          rule: "Presentation cannot import concrete Api* implementations directly. Depend on service abstractions.",
          code: line.trim(),
        });
      }
    }

    // (Concrete Api* / Expo* adapters are allowed to import infrastructure / native modules)
    const isConcreteApiAdapter =
      /(^|\/)Api[A-Z]\w+\.ts$/.test(relPath) ||
      relPath.endsWith("ImageUploadService.ts") ||
      relPath.endsWith("ExpoImagePicker.ts") ||
      relPath.includes("/infrastructure/");
    const isPureDomainOrService =
      relPath.includes("/domain/") ||
      relPath.endsWith("Service.ts") ||
      relPath.endsWith("Validator.ts") ||
      relPath.endsWith("Hook.ts");

    if (
      (relPath.includes("/application/") || relPath.includes("/domain/")) &&
      !relPath.includes("/bootstrap/")
    ) {
      if (line.includes("/presentation/")) {
        violations.push({
          file: relPath,
          line: lineNum,
          rule: "Application services & domain cannot import presentation layer code.",
          code: line.trim(),
        });
      }
      if (line.includes("/infrastructure/") && !isConcreteApiAdapter) {
        violations.push({
          file: relPath,
          line: lineNum,
          rule: "Pure domain models, services, and validators cannot import infrastructure directly.",
          code: line.trim(),
        });
      }
      if (/from\s+['"]react(-native)?['"]/.test(line) && !line.includes("type ")) {
        violations.push({
          file: relPath,
          line: lineNum,
          rule: "Application services & domain cannot import React or React Native UI packages.",
          code: line.trim(),
        });
      }
    }
  });
}

if (violations.length > 0) {
  console.error("❌ Mobile Architecture Guard Violations Found:\n");
  for (const v of violations) {
    console.error(`  [${v.file}:${v.line}] ${v.rule}`);
    console.error(`    > ${v.code}\n`);
  }
  process.exit(1);
} else {
  console.log("✅ Mobile Architecture Guard: All mobile layer boundaries clean.");
  process.exit(0);
}

#!/usr/bin/env node

const { execSync, spawnSync } = require("node:child_process");
const fs = require("node:fs");
const path = require("node:path");

const WORKSPACE_ROOTS = ["apps/admin", "apps/web", "backend/api", "core", "shared"];

function run(cmd) {
  return execSync(cmd, { stdio: ["ignore", "pipe", "pipe"], encoding: "utf8" }).trim();
}

function resolveBaseRef() {
  const ghBase = process.env.GITHUB_BASE_REF;
  if (ghBase) return `origin/${ghBase}`;
  return "origin/main";
}

function resolveMergeBase(baseRef) {
  try {
    return run(`git merge-base HEAD ${baseRef}`);
  } catch {
    try {
      return run("git rev-parse HEAD~1");
    } catch {
      return "";
    }
  }
}

function getChangedTsFiles(baseSha) {
  if (!baseSha) return [];
  const raw = run(`git diff --name-only --diff-filter=ACMR ${baseSha}...HEAD`);
  return raw
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .filter((file) => /\.(ts|tsx)$/.test(file))
    .filter((file) => WORKSPACE_ROOTS.some((root) => file.startsWith(`${root}/src/`)));
}

function groupByWorkspace(files) {
  const grouped = new Map();
  for (const file of files) {
    const root = WORKSPACE_ROOTS.find((r) => file.startsWith(`${r}/`));
    if (!root) continue;
    const rel = file.slice(root.length + 1);
    if (!grouped.has(root)) grouped.set(root, []);
    grouped.get(root).push(rel);
  }
  return grouped;
}

function lintWorkspaceChangedFiles(workspace, files) {
  if (!files.length) return 0;
  const args = [
    "eslint",
    ...files,
    "--format=json",
    "--rule",
    "unused-imports/no-unused-imports:error",
  ];
  const result = spawnSync("npx", args, {
    cwd: workspace,
    stdio: ["ignore", "pipe", "pipe"],
    shell: false,
    encoding: "utf8",
  });

  try {
    const output = JSON.parse(result.stdout.trim());
    let unusedImportCount = 0;
    for (const file of output) {
      const unusedInFile = file.messages.filter(m => m.ruleId === "unused-imports/no-unused-imports");
      if (unusedInFile.length > 0) {
        console.error(`❌ Unused imports in ${workspace}/${file.filePath}:`);
        unusedInFile.forEach(m => {
          console.error(`  Line ${m.line}: ${m.message}`);
        });
        unusedImportCount += unusedInFile.length;
      }
    }
    return unusedImportCount > 0 ? 1 : 0;
  } catch (err) {
    console.error(`ESLint error or parsing error in workspace ${workspace}:`, result.stderr || result.stdout);
    return 1;
  }
}

function main() {
  const baseRef = resolveBaseRef();
  const baseSha = resolveMergeBase(baseRef);

  if (!baseSha) {
    console.log("✅ Skipping unused import guard (git base could not be resolved).");
    return;
  }

  const changed = getChangedTsFiles(baseSha);

  if (changed.length === 0) {
    console.log("✅ No TypeScript changes detected for unused import guard.");
    return;
  }

  const grouped = groupByWorkspace(changed);
  let hasFailures = false;

  for (const [workspace, files] of grouped.entries()) {
    console.log(`Checking unused imports in changed files (${workspace})...`);
    // Final safety check: filter out files that may have been deleted/moved
    const existingFiles = files.filter(f => fs.existsSync(path.join(workspace, f)));
    if (existingFiles.length === 0) continue;

    const status = lintWorkspaceChangedFiles(workspace, existingFiles);
    if (status !== 0) {
      hasFailures = true;
    }
  }

  if (hasFailures) {
    console.error("❌ New unused imports detected in changed files.");
    process.exit(1);
  }

  console.log("✅ Unused import guard passed.");
}

main();

#!/usr/bin/env node

/**
 * Schema Migration Governance Check (Cross-Platform)
 * Ensures model changes are accompanied by migrations or changelog updates.
 */

const { execSync } = require('child_process');
const fs = require('fs');

if (process.env.SKIP_MIGRATION_GATE) {
    console.log("[governance] SKIP_MIGRATION_GATE is set; skipping schema migration guard.");
    process.exit(0);
}

function runGit(cmd) {
    try {
        return execSync(cmd, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] }).trim();
    } catch (e) {
        return '';
    }
}

// Parse args
let baseRef = '';
process.argv.forEach(val => {
    if (val.startsWith('--base=')) {
        baseRef = val.split('=')[1];
    }
});

function resolveBaseRef() {
    if (baseRef) return baseRef;

    const upstream = runGit('git rev-parse --abbrev-ref --symbolic-full-name @{upstream}');
    if (upstream) return upstream;

    const develop = runGit('git show-ref --verify --quiet refs/remotes/origin/develop');
    if (develop) return 'origin/develop';

    const main = runGit('git show-ref --verify --quiet refs/remotes/origin/main');
    if (main) return 'origin/main';

    return '';
}

let targetBaseRef = resolveBaseRef();
if (targetBaseRef && !runGit(`git rev-parse --verify --quiet ${targetBaseRef}`)) {
    console.log(`[governance] Base ref '${targetBaseRef}' was not found locally; falling back to HEAD~1.`);
    targetBaseRef = '';
}

let changedFilesRaw = '';
if (targetBaseRef) {
    console.log(`[governance] Schema migration gate diff base: ${targetBaseRef}`);
    changedFilesRaw = runGit(`git diff --name-only ${targetBaseRef}...HEAD`);
} else {
    console.log('[governance] Schema migration gate diff base: HEAD~1');
    changedFilesRaw = runGit('git diff --name-only HEAD~1..HEAD');
}

const untrackedFilesRaw = runGit('git ls-files --others --exclude-standard');

// Combine and normalize files list
const allFiles = Array.from(new Set([
    ...changedFilesRaw.split('\n'),
    ...untrackedFilesRaw.split('\n')
]))
    .map(f => f.trim().replace(/\\/g, '/'))
    .filter(f => f.length > 0);

if (allFiles.length === 0) {
    console.log("[governance] No changed files detected for schema migration gate.");
    process.exit(0);
}

// Schema and model file pattern matches
const schemaPatterns = [
    /^core\/src\/models\/.*\.(ts|js)$/,
    /^shared\/src\/schemas\/.*\.(ts|js)$/,
    /^shared\/src\/types\/catalogHierarchy\.ts$/,
    /^shared\/src\/enums\/taxonomyApprovalStatus\.ts$/,
    /^core\/src\/constants\/enums\/taxonomyApprovalStatus\.ts$/
];

const schemaChanges = allFiles.filter(file => 
    schemaPatterns.some(pattern => pattern.test(file))
);

if (schemaChanges.length === 0) {
    console.log("[governance] No core model changes detected; migration gate passed.");
    process.exit(0);
}

// Migration evidence pattern matches
const migrationPatterns = [
    /^backend\/user\/migrations\//
];

const hasMigrationEvidence = allFiles.some(file =>
    migrationPatterns.some(pattern => pattern.test(file))
);

if (hasMigrationEvidence) {
    console.log("[governance] Schema change detected with migration evidence.");
    process.exit(0);
}

console.error("❌ Schema migration governance violation.");
console.error("Changed schema/model files:");
schemaChanges.forEach(file => console.error(`  - ${file}`));
console.error("\nRequired with core model changes:");
console.error("  - Add/update a migration under backend/api/migrations/");
process.exit(1);

/**
 * 🛠️ ESLint Baseline Generator
 * 
 * Usage: node scripts/generate-eslint-baseline.js
 * 
 * This script runs a full monorepo lint and saves the results to eslint-baseline.json.
 * Use this to lock in existing technical debt so CI can block ONLY new violations.
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const BASELINE_FILE = path.join(__dirname, '../eslint-baseline.json');

// CI Guard: Baseline regeneration is prohibited in CI environments.
// The baseline must only shrink (debt paid down), never expand.
// If you have new violations, fix them — do not re-baseline.
if (process.env.CI === 'true' || process.env.GITHUB_ACTIONS === 'true') {
    console.error('❌ Baseline regeneration is prohibited in CI.');
    console.error('   Fix lint violations instead of re-baselining.');
    console.error('   If you intend to reduce the baseline, run this script locally and commit the result.');
    process.exit(1);
}

console.log('🚀 Starting full monorepo lint to generate baseline...');

function normalizeFilePath(filePath) {
    if (!filePath) return '';
    let relPath = path.isAbsolute(filePath) ? path.relative(process.cwd(), filePath) : filePath;
    relPath = relPath.replace(/^.*?[/\\](apps|backend|core|shared|packages|scripts|tooling|\.agents|\.github)/, '$1');
    return relPath.replace(/\\/g, '/');
}

function processAndSaveBaseline(rawJsonOutput) {
    try {
        const parsed = JSON.parse(rawJsonOutput);
        const normalized = parsed.map(file => ({
            ...file,
            filePath: normalizeFilePath(file.filePath)
        }));
        fs.writeFileSync(BASELINE_FILE, JSON.stringify(normalized, null, 2));
        console.log(`🎉 Baseline saved to: ${BASELINE_FILE}`);
    } catch (e) {
        fs.writeFileSync(BASELINE_FILE, rawJsonOutput);
        console.log(`🎉 Raw baseline saved to: ${BASELINE_FILE}`);
    }
}

try {
    // Run full lint with JSON formatter
    const output = execSync('npx eslint . --format json', { 
        maxBuffer: 1024 * 1024 * 100, // 100MB buffer for large projects
        env: { ...process.env, NODE_OPTIONS: '--max-old-space-size=8192' }
    });

    console.log('✅ Lint complete (no issues found, or all warnings).');
    processAndSaveBaseline(output.toString());
} catch (error) {
    // execSync throws if exit code is not 0
    if (error.stdout) {
        console.log('⚠️ Lint found violations. Saving these as the baseline...');
        processAndSaveBaseline(error.stdout.toString());
    } else {
        console.error('❌ Failed to generate baseline:', error.message);
        process.exit(1);
    }
}

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { Validation, runStandalone, ROOT } = require('../shared');

const META = { id: 'ARCH-PLATFORM-001', name: 'Architecture Platform Verification', version: '1.0.0', category: 'Architecture' };

const BASELINE_PATH = path.join(ROOT, 'scripts/policy/governance-debt-baseline.json');
let baseline = { baselines: {} };
if (fs.existsSync(BASELINE_PATH)) {
  try {
    baseline = JSON.parse(fs.readFileSync(BASELINE_PATH, 'utf-8'));
  } catch {}
}

function run(val) {
  try {
    const out = execSync('npx tsx tooling/architecture/verify-architecture.ts', { cwd: ROOT, encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
    if (out.includes('Architecture Score: 100') || !out.includes('FAIL')) {
      val.info('Architecture platform verification passed (Score 100/100)');
    } else {
      const lines = out.split('\n').filter(l => l.trim().startsWith('→'));
      checkViolations(val, lines);
    }
  } catch (e) {
    const out = (e.stdout || '') + (e.stderr || '');
    const lines = out.split('\n').filter(l => l.trim().startsWith('→'));
    checkViolations(val, lines);
  }
}

function checkViolations(val, lines) {
  const missingBarrels = baseline.baselines.missingPublicBarrels || [];
  const missingManifests = baseline.baselines.missingDomainManifests || [];

  let newViolations = [];

  for (const line of lines) {
    const isBarrelGrandfathered = missingBarrels.some(b => line.includes(`Domain "${b}"`) || line.includes(`"${b}"`));
    const isManifestGrandfathered = missingManifests.some(m => line.includes(`/domains/${m}/manifest.yaml`));

    if (isBarrelGrandfathered || isManifestGrandfathered) {
      val.warning(`Grandfathered Architectural Debt: ${line.trim()}`);
    } else {
      newViolations.push(line.trim());
    }
  }

  if (newViolations.length > 0) {
    for (const v of newViolations) {
      val.error(`NEW Architectural Violation: ${v}`);
    }
    val.error(`Architecture Platform Verification failed ratchet check (${newViolations.length} new violations detected)`);
  } else {
    val.info('Architecture Platform Verification passed ratchet check (baseline debt tracked)');
  }
}

if (require.main === module) {
  runStandalone(META, run);
}
module.exports = { meta: META, run };

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { Validation, runStandalone, ROOT } = require('../shared');

const META = { id: 'ARCH-001', name: 'Architecture Compliance & Ownership Governance', version: '2.0.0', category: 'Architecture' };

function run(val) {
  // Load Canonical Ownership Registry if present
  const REGISTRY_PATH = path.join(ROOT, '.agents/governance/CANONICAL_OWNERSHIP_REGISTRY.json');
  let ownershipRegistry = null;
  if (fs.existsSync(REGISTRY_PATH)) {
    try {
      ownershipRegistry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf-8')).ownership;
    } catch (e) {}
  }

  const SEARCH_DIRS = ['apps', 'packages', 'core', 'backend'];

  function getTsFiles(dir, files = []) {
    if (!fs.existsSync(dir)) return files;
    const entries = fs.readdirSync(dir);
    for (const entry of entries) {
      if (entry === 'node_modules' || entry === 'dist' || entry === '.next' || entry === 'Pods' || entry === 'build' || entry.startsWith('.')) continue;
      const full = path.join(dir, entry);
      if (!fs.existsSync(full)) continue;
      const stat = fs.lstatSync(full);
      if (stat.isSymbolicLink()) continue;
      if (stat.isDirectory()) {
        getTsFiles(full, files);
      } else if (/\.(ts|tsx)$/.test(entry) && !entry.endsWith('.d.ts')) {
        files.push(full);
      }
    }
    return files;
  }

  const allSourceFiles = SEARCH_DIRS.flatMap(d => getTsFiles(path.join(ROOT, d)));

  // 1. Ownership & Package Boundary Validation using Registry
  if (ownershipRegistry) {
    for (const file of allSourceFiles) {
      const relPath = path.relative(ROOT, file);

      // Determine which registry section owns this file
      for (const [scopeKey, scopeRules] of Object.entries(ownershipRegistry)) {
        if (relPath.startsWith(scopeKey)) {
          const content = fs.readFileSync(file, 'utf-8');
          const importRe = /(?:from|require)\s*\(?\s*['"]([^'"]+)['"]\s*\)?/g;
          const matches = content.matchAll(importRe);

          for (const match of matches) {
            const importPath = match[1];
            if (!importPath.startsWith('@esparex/')) continue;

            const forbidden = scopeRules.forbiddenImports || [];
            for (const forbiddenPkg of forbidden) {
              if (importPath === forbiddenPkg || importPath.startsWith(forbiddenPkg + '/')) {
                val.error(`Package Ownership Violation: "${relPath}" (${scopeRules.owner}) imports forbidden package "${importPath}". Rule defined in CANONICAL_OWNERSHIP_REGISTRY.json.`);
              }
            }
          }
        }
      }
    }
  }

  // 2. GOV-006: API Layer Validation
  const appApiFiles = allSourceFiles.filter(f => f.includes('apps/') && (f.includes('/api/') || f.includes('/lib/api/')));
  const AUTHORIZED_CLIENT_FILES = ['adminClient.ts', 'client.ts', 'server.ts', 'route.ts', 'apiClient.ts'];

  for (const file of appApiFiles) {
    const filename = path.basename(file);
    if (AUTHORIZED_CLIENT_FILES.includes(filename)) continue;

    const relPath = path.relative(ROOT, file);
    const content = fs.readFileSync(file, 'utf-8');
    if (content.includes('axios.create(') || (content.includes('fetch(') && !content.includes('apiClient') && !content.includes('getMe') && !content.includes('userListingQueryAPI'))) {
      val.warning(`API Layer Warning: ${relPath} contains raw HTTP client instantiation. Prefer canonical API clients from @esparex/contracts or @esparex/shared.`);
    }
  }

  // 3. GOV-007: Hook Consolidation Validation
  const hookFiles = allSourceFiles.filter(f => path.basename(f).startsWith('use'));
  const hookNameMap = new Map();
  for (const file of hookFiles) {
    const hookName = path.basename(file, path.extname(file));
    const relPath = path.relative(ROOT, file);

    const normalizedFamily = hookName.replace(/(Modal|Dialog|Popup)/g, 'Overlay');
    if (normalizedFamily.includes('Overlay') && hookNameMap.has(normalizedFamily)) {
      const existing = hookNameMap.get(normalizedFamily);
      if (existing !== relPath && (relPath.includes('apps/') && existing.includes('apps/'))) {
        val.warning(`Hook Consolidation: "${hookName}" in ${relPath} is functionally similar to "${path.basename(existing)}" in ${existing}. Consider consolidating into @esparex/ui.`);
      }
    } else if (normalizedFamily.includes('Overlay')) {
      hookNameMap.set(normalizedFamily, relPath);
    }
  }

  val.info('Architecture compliance, package ownership boundaries, and canonical registry verified');
}

if (require.main === module) {
  runStandalone(META, run);
}
module.exports = { meta: META, run };

