    if (!fs.existsSync(fullPath)) continue;
    const content = fs.readFileSync(fullPath, 'utf-8');
    const routeMatches = content.match(/(?:router|route)\.(?:get|post|put|patch|delete|options)\s*\(\s*['"`](\/[^'"`]*)['"`]/gi);
    if (routeMatches) {
      for (const match of routeMatches) {
        const parts = match.split(/['"`]/);
        if (parts.length >= 2) {
          const routePath = parts[1];
          if (routes.has(routePath)) {
            val.error(`Duplicate route "${routePath}" in ${file} and ${routes.get(routePath)}`);
          } else {
            routes.set(routePath, file);
          }
        }
      }
    }
  }
}

if (require.main === module) {
  runStandalone(META, run);
}
module.exports = { meta: META, run };

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { Validation, runStandalone, ROOT } = require('../shared');

const META = { id: 'SSOT-001', name: 'SSOT & Canonical Ownership', version: '2.0.0', category: 'Architecture' };

function run(val) {
  // 1. Dynamic Canonical Symbol Discovery from Package Boundaries
  // Scans packages/*, shared/, core/ for exported symbols to dynamically determine canonical ownership
  const PACKAGE_DIRS = [
    { dir: 'packages/ui', name: '@esparex/ui' },
    { dir: 'packages/contracts', name: '@esparex/contracts' },
    { dir: 'shared', name: '@esparex/shared' },
    { dir: 'core', name: '@esparex/core' },
  ];

  const canonicalSymbolMap = new Map(); // symbol -> packageName

  function scanExports(dir, packageName) {
    const fullDir = path.join(ROOT, dir);
    if (!fs.existsSync(fullDir)) return;

    function getFiles(current) {
      let results = [];
      const list = fs.readdirSync(current);
      for (const item of list) {
        const p = path.join(current, item);
        const stat = fs.statSync(p);
        if (stat.isDirectory()) {
          if (item !== 'node_modules' && item !== 'dist' && !item.startsWith('.')) {
            results = results.concat(getFiles(p));
          }
        } else if (/\.(ts|tsx)$/.test(item) && !item.endsWith('.d.ts')) {
          results.push(p);
        }
      }
      return results;
    }

    const files = getFiles(fullDir);
    for (const file of files) {
      const content = fs.readFileSync(file, 'utf-8');
      const matches = content.matchAll(/^export\s+(?:const|function|class|interface|type|enum)\s+(\w+)/gm);
      for (const m of matches) {
        const symbol = m[1];
        if (!canonicalSymbolMap.has(symbol)) {
          canonicalSymbolMap.set(symbol, packageName);
        }
      }
    }
  }

  for (const pkg of PACKAGE_DIRS) {
    scanExports(pkg.dir, pkg.name);
  }

  // 2. Import & Ownership Analysis in Applications (apps/web, apps/admin)
  const appDirs = ['apps/web/src', 'apps/admin/src'];
  for (const appDir of appDirs) {
    const fullDir = path.join(ROOT, appDir);
    if (!fs.existsSync(fullDir)) continue;

    function checkAppFiles(current) {
      const list = fs.readdirSync(current);
      for (const item of list) {
        const p = path.join(current, item);
        const stat = fs.statSync(p);
        if (stat.isDirectory()) {
          if (item !== 'node_modules' && item !== '.next' && !item.startsWith('.')) {
            checkAppFiles(p);
          }
        } else if (/\.(ts|tsx)$/.test(item) && !item.endsWith('.d.ts')) {
          const content = fs.readFileSync(p, 'utf-8');
          const relPath = path.relative(ROOT, p);

          // Rule A: Verify imports — reject deep imports from dist
          const importMatches = content.matchAll(/from\s+['"](@esparex\/[^'"]+)['"]/g);
          for (const match of importMatches) {
            if (match[1].includes('/dist/')) {
              val.error(`Deep Import Violation: ${relPath} imports "${match[1]}". Import from package root instead.`);
            }
          }

          // Rule B: Dynamic Canonical Ownership & Import Resolution
          // Check if app file exports a local symbol that collides with a canonical package symbol
          const localExports = content.matchAll(/^export\s+(?:const|function|class|interface|type|enum)\s+(\w+)/gm);
          for (const exp of localExports) {
            const sym = exp[1];
            if (canonicalSymbolMap.has(sym)) {
              const canonicalOwner = canonicalSymbolMap.get(sym);
              // Allow local wrapper if file explicitly imports canonical symbol or contract/shared package, or is in page/route entry point, or if app is admin decoupled from backend core
              const importsCanonical =
                content.includes(`from "${canonicalOwner}"`) ||
                content.includes(`from '${canonicalOwner}'`) ||
                content.includes(`from "@esparex/contracts"`) ||
                content.includes(`from '@esparex/contracts'`) ||
                content.includes(`from "@esparex/shared"`) ||
                content.includes(`from '@esparex/shared'`) ||
                (relPath.startsWith('apps/admin/') && canonicalOwner === '@esparex/core');

              if (!importsCanonical && !relPath.includes('/app/') && !relPath.includes('/pages/')) {
                val.warning(`Canonical Ownership Violation: "${sym}" in ${relPath} collides with canonical symbol in ${canonicalOwner}. Import from ${canonicalOwner} instead.`);
              }
            }
          }
        }
      }
    }
    checkAppFiles(fullDir);
  }

  val.info('Dynamic canonical ownership and import resolution verified across workspace packages and applications');
}

if (require.main === module) {
  runStandalone(META, run);
}
module.exports = { meta: META, run };

const { execSync } = require('child_process');
const { ROOT } = require('../shared');

exports.meta = {
  id: 'UI-001',
  name: 'Design System Primitive Guard',
};

exports.run = (v) => {
  // Baseline counts (established at the start of Phase 2.4A)
  const baselines = {
    'space-y-': 355,
    'max-w-7xl': 15,
    'grid-cols-': 125
  };

  const countPattern = (pattern) => {
    try {
      const output = execSync(`git grep -c '${pattern}' -- 'apps/**/*.ts*' 'packages/**/*.ts*' || true`, {
        cwd: ROOT,
        encoding: 'utf8'
      });
      if (!output.trim()) return 0;

      // Output is lines of `path/to/file:count`
      return output.trim().split('\n').reduce((acc, line) => {
        const parts = line.split(':');
        const count = parseInt(parts[parts.length - 1], 10);
        return acc + count;
      }, 0);
    } catch (e) {
      return 0;
    }
  };

  const spaceY = countPattern('space-y-');
  const maxW = countPattern('max-w-7xl');
  const gridCols = countPattern('grid-cols-');

  // Verify against baselines
  if (spaceY > baselines['space-y-']) {
    v.error(`Primitive Guard Violation: 'space-y-*' usage increased to ${spaceY} (baseline ${baselines['space-y-']}). Please use <Stack gap="*"> from @esparex/ui instead.`);
  } else if (spaceY > 0) {
    v.info(`'space-y-*' legacy usages remaining: ${spaceY} (baseline ${baselines['space-y-']})`);
  }

  if (maxW > baselines['max-w-7xl']) {
    v.error(`Primitive Guard Violation: 'max-w-7xl' usage increased to ${maxW} (baseline ${baselines['max-w-7xl']}). Please use <Container variant="wide"> from @esparex/ui instead.`);
  } else if (maxW > 0) {
    v.info(`'max-w-7xl' legacy usages remaining: ${maxW} (baseline ${baselines['max-w-7xl']})`);
  }

  if (gridCols > baselines['grid-cols-']) {
    v.error(`Primitive Guard Violation: 'grid-cols-*' usage increased to ${gridCols} (baseline ${baselines['grid-cols-']}). Please use <Grid cols={*}> from @esparex/ui instead.`);
  } else if (gridCols > 0) {
    v.info(`'grid-cols-*' legacy usages remaining: ${gridCols} (baseline ${baselines['grid-cols-']})`);
  }
};

#!/usr/bin/env node
const { Validation, formatReport, ROOT } = require('./shared');

const checks = [
  require('./workspace-check'),
  require('./secret-scan'),
  require('./binary-check'),
  require('./lockfile-check'),
  require('./esparex/branch-protection'),
  require('./esparex/route-validator'),
  require('./esparex/contract-validator'),
  require('./esparex/env-validator'),
  require('./esparex/ssot-validator'),
  require('./esparex/architecture-validator'),
  require('./esparex/governance-guards-validator'),
  require('./esparex/architecture-platform-validator'),
  require('./esparex/duplicate-validator'),
  require('./esparex/circular-validator'),
  require('./esparex/dependency-validator'),
  require('./esparex/auditor-validator'),
  require('./esparex/ui-validator'),
];

const results = [];

for (const mod of checks) {
  const val = new Validation(mod.meta);
  const start = Date.now();
  try {
    mod.run(val);
  } catch (e) {
    val.error(`Validator error: ${e.message}`);
  }
  val.elapsedMs = Date.now() - start;
  results.push(val);
}

const { recordTelemetry } = require('../policy/telemetry-recorder');

const report = formatReport(results);
console.log(report);

const hasBlockers = results.some(r => r.errors.length > 0);

try {
  recordTelemetry(results, hasBlockers);
} catch (_e) {
  // Telemetry recording must be non-blocking
}

process.exit(hasBlockers ? 1 : 0);

#!/usr/bin/env node
const path = require('path');
const ROOT = path.resolve(__dirname, '../..');

const SEVERITY = { ERROR: 'error', WARNING: 'warning', INFO: 'info' };

class Validation {
  constructor(meta) {
    this.meta = meta || { id: 'UNKN-000', name: 'Unknown', version: '0.0.0', category: 'Uncategorized' };
    this.errors = [];
    this.warnings = [];
    this.infos = [];
    this.elapsedMs = 0;
  }

  get name() {
    return this.meta.name;
  }

  error(msg) {
    this.errors.push(msg);
  }

  warning(msg) {
    this.warnings.push(msg);
  }

  info(msg) {
    this.infos.push(msg);
  }

  get passed() {
    return this.errors.length === 0;
  }

  get statusLabel() {
    const hasErrors = this.errors.length > 0;
    const hasWarnings = this.warnings.length > 0;
    if (hasErrors) return '✗ FAIL';
    if (hasWarnings) return '~ WARN';
    return '✓ PASS';
  }

  get statusCode() {
    if (this.errors.length > 0) return 'ERR';
    if (this.warnings.length > 0) return 'WARN';
    return 'PASS';
  }

  get elapsed() {
    if (this.elapsedMs < 1000) return `${this.elapsedMs}ms`;
    return `${(this.elapsedMs / 1000).toFixed(2)}s`;
  }

  print() {
    for (const e of this.errors) console.error(`  [ERROR] ${e}`);
    for (const w of this.warnings) console.error(`  [WARN]  ${w}`);
    for (const i of this.infos) console.error(`  [INFO]  ${i}`);
  }
}

function formatReport(results) {
  const sep = '═'.repeat(60);
  const lines = [];
  lines.push('');
  lines.push(`╔${sep}╗`);
  lines.push(`║  Esparex Repository Integrity Report`.padEnd(62) + '║');
  lines.push(`╚${sep}╝`);
  lines.push('');

  let longestId = 0;
  let longestName = 0;
  for (const r of results) {
    if (r.meta.id.length > longestId) longestId = r.meta.id.length;
    if (r.name.length > longestName) longestName = r.name.length;
  }

  for (const r of results) {
    const status = r.statusCode.padEnd(5);
    const id = r.meta.id.padEnd(longestId + 1);
    const name = r.name.padEnd(longestName + 2);
    const counts = [];
    if (r.errors.length > 0) counts.push(`E${r.errors.length}`);
    if (r.warnings.length > 0) counts.push(`W${r.warnings.length}`);
    if (r.infos.length > 0) counts.push(`I${r.infos.length}`);
    const extra = counts.length > 0 ? ` (${counts.join(', ')})` : '';
    const time = r.elapsed.padStart(7);
    lines.push(`  ${status}  ${id} ${name}${extra}${time}`);
  }

  lines.push('');

  const totalErrors = results.reduce((s, r) => s + r.errors.length, 0);
  const totalWarnings = results.reduce((s, r) => s + r.warnings.length, 0);
  const totalInfos = results.reduce((s, r) => s + r.infos.length, 0);

  if (totalErrors > 0) {
    lines.push(`  ── Errors (${totalErrors}) ──`);
    for (const r of results) {
      if (r.errors.length > 0) {
        for (const e of r.errors) lines.push(`    ERROR  ${r.meta.id}  ${e}`);
      }
    }
    lines.push('');
  }

  if (totalWarnings > 0) {
    lines.push(`  ── Warnings (${totalWarnings}) ──`);
    for (const r of results) {
      if (r.warnings.length > 0) {
        for (const w of r.warnings) lines.push(`    WARN   ${r.meta.id}  ${w}`);
      }
    }
    lines.push('');
  }

  if (totalInfos > 0) {
    lines.push(`  ── Info (${totalInfos}) ──`);
    for (const r of results) {
      if (r.infos.length > 0) {
        for (const i of r.infos) lines.push(`    INFO   ${r.meta.id}  ${i}`);
      }
    }
    lines.push('');
  }

  const hasErrors = results.some(r => r.errors.length > 0);
  const hasWarnings = results.some(r => r.warnings.length > 0);

  if (hasErrors) {
    lines.push(`  ✗ Gate failed — ${totalErrors} error${totalErrors > 1 ? 's' : ''} found.`);
  } else if (hasWarnings) {
    lines.push(`  ~ Gate passed — ${totalWarnings} warning${totalWarnings > 1 ? 's' : ''}. Review recommended.`);
  } else {
    lines.push(`  ✓ All repository gate checks passed.`);
  }
  lines.push('');

  // GOV-008 Repository Health Summary Card
  const healthScore = totalErrors === 0 ? 100 : Math.max(0, 100 - (totalErrors * 15 + totalWarnings * 2));
  const summarySep = '─'.repeat(60);
  lines.push(`╔${sep}╗`);
  lines.push(`║                  Repository Health Summary                ║`);
  lines.push(`╠${sep}╣`);
  for (const r of results) {
    const statusIcon = r.errors.length > 0 ? '✗ FAIL' : (r.warnings.length > 0 ? '~ WARN' : '✓ PASS');
    const namePadded = r.name.padEnd(38);
    lines.push(`║  ${namePadded}  ${statusIcon.padEnd(14)} ║`);
  }
  lines.push(`╠${sep}╣`);
  lines.push(`║  Repository Status: ${(totalErrors === 0 ? 'PASS' : 'FAIL').padEnd(36)} ║`);
  lines.push(`║  Health Score: ${`${healthScore}%`.padEnd(40)} ║`);
  lines.push(`╚${sep}╝`);
  lines.push('');

  return lines.join('\n');
}

function runStandalone(meta, fn) {
  const val = new Validation(meta);
  const start = Date.now();
  fn(val);
  val.elapsedMs = Date.now() - start;
  val.print();
  console.log(`\n${val.statusLabel} ${meta.id} ${meta.name} (${val.elapsed})`);
  process.exit(val.passed ? 0 : 1);
}

module.exports = { Validation, formatReport, runStandalone, ROOT, SEVERITY };

#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { Validation, runStandalone, ROOT } = require('./shared');

const META = { id: 'WORK-001', name: 'Workspace Validation', version: '1.0.0', category: 'Structure' };

function run(val) {
  const rootPkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf-8'));
  const workspaceGlobs = rootPkg.workspaces || [];

  function resolveGlobToDirs(pattern) {
    const parts = pattern.split(/[\\/]/);
    const dirs = [];
    function walk(base, idx) {
      if (idx === parts.length) {
        if (fs.existsSync(base) && fs.statSync(base).isDirectory()) dirs.push(base);
        return;
      }
      const part = parts[idx];
      if (part === '*') {
        let entries;
        try { entries = fs.readdirSync(base, { withFileTypes: true }); } catch { return; }
        for (const entry of entries) {
          if (entry.isDirectory() && !entry.name.startsWith('.')) {
            walk(path.join(base, entry.name), idx + 1);
          }
        }
      } else {
        walk(path.join(base, part), idx + 1);
      }
    }
    walk(ROOT, 0);
    return dirs;
  }

  const matchedDirs = [];
  for (const pat of workspaceGlobs) {
    for (const dir of resolveGlobToDirs(pat)) {
      matchedDirs.push({ dir, relPath: path.relative(ROOT, dir) });
    }
  }

  const pkgNameMap = new Map();

  function isOrganizationalContainer(dir) {
    if (fs.existsSync(path.join(dir, 'package.json'))) return false;
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return false; }
    const subdirs = entries.filter(e => e.isDirectory() && !e.name.startsWith('.'));
    if (subdirs.length === 0) return false;
    return subdirs.some(sub => fs.existsSync(path.join(dir, sub.name, 'package.json')));
  }

  for (const { dir, relPath } of matchedDirs) {
    const pkgPath = path.join(dir, 'package.json');
    if (!fs.existsSync(pkgPath)) {
      if (isOrganizationalContainer(dir)) continue;
      val.error(`Directory matched by workspace glob but missing package.json: ${relPath}`);
      continue;
    }
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
    if (!pkg.name) {
      val.error(`${relPath}/package.json is missing the "name" field.`);
      continue;
    }
    if (pkgNameMap.has(pkg.name)) {
      val.error(`Duplicate package name "${pkg.name}" in ${relPath}/package.json and ${pkgNameMap.get(pkg.name)}`);
    } else {
      pkgNameMap.set(pkg.name, relPath + '/package.json');
    }
  }

  for (const { dir, relPath } of matchedDirs) {
    const pkgPath = path.join(dir, 'package.json');
    if (!fs.existsSync(pkgPath)) continue;
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
    const allDeps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}), ...(pkg.peerDependencies || {}) };
    for (const [depName, depVer] of Object.entries(allDeps)) {
      if (depVer === '*' || depVer === 'workspace:*' || depVer.startsWith('workspace:')) {
        if (!pkgNameMap.has(depName)) {
          val.error(`"${depName}" (workspace dependency) not found. Referenced by ${relPath}/package.json.`);
        }
      }
    }
  }

  const seen = new Set();
  function detectCircular(name, chain = []) {
    if (chain.includes(name)) {
      val.error(`Circular workspace dependency: ${chain.slice(chain.indexOf(name)).concat(name).join(' -> ')}`);
      return;
    }
    if (seen.has(name)) return;
    seen.add(name);
    const entry = pkgNameMap.get(name);
    if (!entry) return;
    const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, entry), 'utf-8'));
    const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}), ...(pkg.peerDependencies || {}) };
    for (const [depName, depVer] of Object.entries(deps)) {
      if ((depVer === '*' || depVer === 'workspace:*' || depVer.startsWith('workspace:')) && pkgNameMap.has(depName)) {
        detectCircular(depName, [...chain, name]);
      }
    }
  }
  for (const name of pkgNameMap.keys()) detectCircular(name);

  const lockPath = path.join(ROOT, 'package-lock.json');
  const lockData = JSON.parse(fs.readFileSync(lockPath, 'utf-8'));
  const lockWorkspaces = lockData.packages?.['']?.workspaces;
  if (lockWorkspaces) {
    const sortedRoot = [...workspaceGlobs].sort();
    const sortedLock = [...lockWorkspaces].sort();
    if (JSON.stringify(sortedRoot) !== JSON.stringify(sortedLock)) {
      val.error('package-lock.json workspaces array does not match package.json.');
    }
  }

  const otherLockFiles = [
    { name: 'pnpm-lock.yaml' }, { name: 'yarn.lock' }, { name: 'pnpm-lock.yml' },
  ];
  for (const lf of otherLockFiles) {
    if (fs.existsSync(path.join(ROOT, lf.name))) {
      val.error(`Mixed package manager: ${lf.name} found alongside npm.`);
    }
  }
}

if (require.main === module) {
  runStandalone(META, run);
}
module.exports = { meta: META, run };

