const { validateSchema } = require('./validate-schema');
const { validateReferences } = require('./validate-references');
const { validateDag } = require('./validate-dag');
const { generateLedger } = require('./build-ledger');
const { buildManifest } = require('./build-manifest');
const fs = require('fs');
const path = require('path');

const command = process.argv[2];

switch (command) {
  case 'validate':
    validateSchema();
    validateReferences();
    validateDag();
    break;
  case 'generate':
    validateSchema();
    validateReferences();
    validateDag();
    generateLedger();
    buildManifest();
    break;
  case 'check':
    validateSchema();
    validateReferences();
    validateDag();

    // Read current
    const current = fs.readFileSync(path.join(process.cwd(), 'governance', 'IMPLEMENTATION_PROGRESS.md'), 'utf-8');
    const generated = generateLedger(false);
    if (current !== generated) {
      console.error('Governance ledger is out of sync. Please run `npm run governance:generate` and commit the result.');
      process.exit(1);
    }
    console.log('Governance ledger snapshot check passed.');
    break;
  case 'graph':
    console.log('DAG visualization not yet implemented.');
    break;
  default:
    console.error('Unknown command:', command);
    process.exit(1);
}

const fs = require("fs");
const path = require("path");
const { formatRatchetMatrix } = require("./ratchet-visualizer");

const GOVERNANCE_DIR = path.resolve(__dirname, "../../.governance");
const LATEST_RUN_PATH = path.join(GOVERNANCE_DIR, "latest-run.json");
const HISTORY_PATH = path.join(GOVERNANCE_DIR, "telemetry-history.json");
const SUMMARY_PATH = path.join(GOVERNANCE_DIR, "governance-summary.json");

function loadJson(filePath) {
  if (!fs.existsSync(filePath)) return null;
  try {
    return JSON.parse(fs.readFileSync(filePath, "utf8"));
  } catch (_e) {
    return null;
  }
}

function renderDashboard() {
  const latestRun = loadJson(LATEST_RUN_PATH);
  const history = loadJson(HISTORY_PATH) || [];
  const summary = loadJson(SUMMARY_PATH);

  const statusStr = latestRun?.status || (summary?.status ?? "UNKNOWN");
  const healthScore = latestRun?.healthScore ?? (summary?.healthScore ?? 100);
  const archScore = summary?.architectureScore ?? 100;
  const ssotStatus = summary?.ssotStatus ?? "PASS";

  const totalRuns = summary?.metrics?.totalRunsRecorded ?? history.length;
  const avgMs = summary?.metrics?.averageDurationMs ?? (latestRun?.totalElapsedMs || 0);
  const passRate = summary?.metrics?.passRatePercent ?? 100;

  console.log("");
  console.log("╔════════════════════════════════════════════════════════════╗");
  console.log("║           ESPAREX GOVERNANCE OBSERVABILITY DASHBOARD       ║");
  console.log("╠════════════════════════════════════════════════════════════╣");
